/* ═══ 수비학 (22 이하 두 자리 수 축약 금지) ═══ */
const digitSum=(n)=>String(n).split("").reduce((a,b)=>a+Number(b),0);
function reduceLayer(t){
  const s=digitSum(t);
  if(s===22)return{main:0,trace:4,steps:`${t}→${s}→0(4내포)`};
  if(s>22)return{main:digitSum(s),trace:s%10,steps:`${t}→${s}→${digitSum(s)}(${s%10}내포)`};
  return{main:s,trace:null,steps:`${t}→${s}`};
}
function reduceSingle(t){
  let s=t;const c=[t];
  while(s>9){s=digitSum(s);c.push(s);}
  return{main:s,trace:null,steps:c.join("→")};
}

/* ═══ 해석 DB ═══ */
const CARDS=[
["바보","자유와 시작","손익을 계산하기 전에 몸이 먼저 움직이는 순수한 실행력과, 실패를 두려워하지 않는 낙천성이 탁월하다. 정해진 틀에 얽매이지 않아 남들이 못 보는 새로운 길을 여는 개척자적 기질을 지닌다. 그러나 계획과 마무리가 약해 벌여놓은 일이 흩어지고 무모하다는 평가를 받기 쉽다. 또한 책임이 무거워지면 자유를 찾아 떠나려는 회피 성향도 있다."],
["마법사","창조와 실행","목표가 정해지면 가진 자원과 재능을 총동원해 원하는 결과를 만들어내는 창조적 실행력이 탁월하다. 언변과 습득력이 좋아 어떤 분야든 빠르게 흡수해 자기 것으로 바꾼다. 그러나 능력을 과신해 여러 일을 동시에 벌이다 깊이를 잃기 쉽다. 또한 목적을 위해 수단을 가볍게 여기는 약삭빠름이 불신을 사기도 한다."],
["여사제","직관과 침묵","말하지 않아도 상황의 이면과 사람의 속마음을 읽어내는 직관과 통찰이 탁월하다. 감정을 겉으로 드러내지 않고 조용히 관찰하며 정확한 판단을 내리는 절제력을 지닌다. 그러나 속을 보여주지 않아 가까운 사람조차 거리감을 느끼게 한다. 또한 생각이 깊어질수록 행동이 느려져 기회를 놓치는 소극적인 면도 있다."],
["여황제","풍요와 돌봄","사람과 일을 품어 성장시키는 포용력과, 풍요를 만들어내는 현실적 생산력이 탁월하다. 미적 감각과 다정함으로 주변을 자연스럽게 자기 편으로 만든다. 그러나 돌봄이 지나쳐 상대를 의존하게 만들거나 자신을 소모하기 쉽다. 또한 편안한 상태에 머물며 변화와 도전을 미루는 게으른 면도 있다."],
["황제","질서와 통솔","혼란한 상황에 질서를 세우고 조직을 장악하는 통솔력과 추진력이 탁월하다. 한번 정한 목표는 흔들림 없이 밀고 나가는 강한 책임감을 지닌다. 그러나 자기 방식을 강요해 주변을 억압한다는 인상을 주기 쉽다. 또한 통제를 잃는 상황을 견디지 못해 융통성이 필요한 순간에도 고집을 부릴 수 있다."],
["교황","전통과 가르침","지식과 경험을 체계로 정리해 사람을 가르치고 이끄는 능력이 탁월하다. 전통과 원칙을 존중해 어디서든 신뢰받는 조언자 역할을 맡는다. 그러나 검증된 길만 고집해 새로운 방식을 받아들이는 데 인색하다. 또한 옳은 말이 잔소리가 되어 상대를 가르치려 든다는 반감을 사기도 한다."],
["연인","선택과 조화","사람 사이의 조화를 만들고 상대의 마음을 얻는 매력과 공감 능력이 탁월하다. 가치관이 맞는 대상을 만나면 놀라운 집중력과 헌신을 보인다. 그러나 선택의 갈림길에서 이것도 저것도 놓지 못해 결정을 미루는 우유부단함이 있다. 또한 관계에 기대면서 혼자 결정하고 행동하는 힘이 약해지기도 한다."],
["전차","돌파와 승부","목표를 향해 장애물을 돌파하는 승부사적 추진력과 강한 정신력이 탁월하다. 경쟁 상황일수록 오히려 집중력이 올라가 성과를 만들어낸다. 그러나 속도를 우선해 과정의 사람과 감정을 놓치기 쉽다. 또한 멈추지 못해 방향이 잘못됐을 때도 계속 밀어붙이는 면이 있다."],
["힘","인내와 제어","겉으로는 부드럽지만 어떤 압박에도 무너지지 않는 내적 강인함과 인내력이 탁월하다. 감정과 본능을 힘이 아닌 다독임으로 다스리는 성숙함을 지닌다. 그러나 참는 것이 습관이 되어 자신의 감정과 바람을 뒤로 미루기 쉽다. 또한 한계까지 버티다가 한꺼번에 지칠 위험도 있다."],
["은둔자","탐구와 성찰","홀로 깊이 파고들어 본질에 도달하는 탐구력과 성찰의 힘이 탁월하다. 유행과 여론에 흔들리지 않고 자기만의 답을 찾아내는 정신적 독립성을 지닌다. 그러나 혼자만의 세계가 길어지면 사람들과의 연결이 끊어져 고립되기 쉽다. 또한 완성될 때까지 보여주지 않으려는 완벽주의가 세상과의 타이밍을 놓치게 한다."],
["운명의 수레바퀴","전환과 기회","변화의 흐름을 빠르게 읽고 기회의 순간에 올라타는 감각이 탁월하다. 낯선 환경에도 유연하게 적응하며 위기를 새로운 출발의 계기로 바꾼다. 그러나 흐름에 의존해 스스로 판을 만드는 주도성이 약해지기 쉽다. 또한 좋고 나쁨의 좋고 나쁨의 차이가 커서 꾸준함이 필요한 일에서 흔들리기도 한다."],
["정의","균형과 판단","감정에 휘둘리지 않고 복잡한 상황도 제3자의 시선으로 냉정하게 판단하는 객관성이 탁월하다. 자신이 택한 행동과 결과는 변명 없이 책임지는 도덕성을 지닌다. 그러나 엄격한 기준을 앞세워 차갑고 인간미 없다는 인상을 주기 쉽다. 또한 양쪽 손익을 저울질하려다 결정적 순간에 결단을 미루는 우유부단함이 공존한다."],
["매달린 사람","관점 전환과 헌신","손해를 감수하면서도 더 큰 그림을 위해 기다릴 줄 아는 인내와, 상황을 뒤집어 보는 역발상이 탁월하다. 남을 위한 희생과 헌신에서 의미를 찾는 깊은 내면을 지닌다. 그러나 기다림이 길어지면 정체를 합리화하며 결단을 회피하기 쉽다. 또한 희생이 당연해지면 억울함이 쌓여 수동공격으로 새어 나오는 이면이 공존한다."],
["죽음","정리와 재생","끝난 것을 미련 없이 정리하고 완전히 새로 시작하는 결단력과 재생력이 탁월하다. 위기 상황에서 오히려 본질만 남기고 군더더기를 잘라내는 힘을 발휘한다. 그러나 정리가 빨라 주변 사람들이 따라오지 못하고 상처받기도 한다. 또한 전환기마다 모든 것을 갈아엎으려는 극단성이 공존한다."],
["절제","조율과 통합","서로 다른 것들을 섞어 최적의 균형점을 찾아내는 조율 능력이 탁월하다. 감정의 기복이 적고 꾸준해 장기전에서 강한 안정감을 지닌다. 그러나 균형을 지키려다 확실한 자기 색깔을 내지 못해 존재감이 흐려지기 쉽다. 또한 갈등을 피하려는 성향이 필요한 싸움까지 미루는 소극성으로 나타난다."],
["악마","욕망과 집중","원하는 것을 향한 강렬한 집중력과, 사람의 욕망을 꿰뚫어 움직이는 현실적 수완이 탁월하다. 해서는 안 된다고 여겨지는 일과 한계에 도전하는 대담함으로 남들이 못 가는 영역에서 성과를 낸다. 그러나 집착이 강해 관계와 물질에 얽매이면 스스로 빠져나오기 어렵다. 또한 통제욕과 소유욕이 강해지면 관계를 지배하려는 면도 나타난다."],
["탑","붕괴와 혁신","낡은 구조의 문제를 정확히 감지하고 무너뜨려 판을 새로 짜는 혁신의 힘이 탁월하다. 충격적인 상황에서도 빠르게 정신을 차리고 재건하는 회복탄력성을 지닌다. 그러나 변화가 급격해 주변에 예고 없는 충격을 주기 쉽다. 또한 안정이 길어지면 스스로 판을 흔들고 싶어 하는 파괴 충동이 공존한다."],
["별","희망과 치유","절망 속에서도 희망을 발견하고 사람들에게 방향을 제시하는 치유의 힘이 탁월하다. 순수한 이상과 비전으로 주변에 영감을 주는 존재가 된다. 그러나 이상이 높아 현실의 속도에 실망하고 지치기 쉽다. 또한 막연한 낙관에 기대어 구체적 실행을 미루는 몽상가적 면모가 공존한다."],
["달","감수성과 상상","보이지 않는 것을 감지하는 예민한 감수성과 풍부한 상상력이 탁월하다. 사람의 불안과 상처를 알아채는 능력으로 깊은 위로를 줄 수 있다. 그러나 불안이 커지면 사실보다 상상이 앞서 스스로를 괴롭히기 쉽다. 또한 기분의 파도가 커 주변이 종잡을 수 없어 하는 변덕이 공존한다."],
["태양","성취와 발현","있는 그대로의 자신을 드러내며 주변까지 밝히는 긍정의 에너지와 성취력이 탁월하다. 하는 일마다 주목받고 결과를 명확하게 만들어내는 강한 운을 지닌다. 그러나 주목받지 못하는 상황에서 급격히 에너지를 잃기 쉽다. 또한 자기 생각을 지나치게 믿어 다른 사람의 어려움을 살피지 못할 수 있다."],
["심판","재평가와 부활","과거를 냉정하게 재평가하고 두 번째 기회를 만들어내는 부활의 힘이 탁월하다. 결정적 순간에 사명감으로 움직여 자신과 주변을 한 단계 끌어올린다. 그러나 과거를 자꾸 소환해 현재를 사는 힘이 약해지기 쉽다. 또한 옳고 그름의 심판자 역할에 빠져 관계가 경직되는 경향이 공존한다."],
["세계","완성과 통합","시작한 일을 끝까지 완성해내는 마무리 능력과 통합적 시야가 탁월하다. 어디서든 조화를 이루며 인정받는 완성형의 안정감을 지닌다. 그러나 완성 이후의 공허함에 취약해 다음 목표를 찾지 못하면 방황한다. 또한 이미 이룬 균형을 깨기 싫어 새로운 도전을 회피하는 안주가 공존한다."],
];
