const SIGNS=["양자리","황소자리","쌍둥이자리","게자리","사자자리","처녀자리","천칭자리","전갈자리","사수자리","염소자리","물병자리","물고기자리"];
const SIGN_TEXT=[
"생각보다 몸이 먼저 움직이는 순발력과 개척 정신이 탁월하다. 경쟁과 도전 앞에서 오히려 에너지가 살아나 시작의 추진력이 누구보다 강하다. 그러나 지속력이 약해 벌인 일이 끝을 보기 전에 식어버리기 쉽다. 또한 성급함이 앞서 사람과 감정을 놓치고, 혼자 앞서가 고립되는 이면이 공존한다.",
"한번 시작한 것을 끝까지 지켜내는 꾸준함과 탄탄한 현실 감각이 탁월하다. 오감이 발달해 좋은 것을 알아보고 물질과 안정을 다루는 힘을 지닌다. 그러나 변화를 거부하는 고집이 굳어져 바뀐 흐름의 기회를 놓치기 쉽다. 또한 안정과 소유에 집착하면 익숙함에 눌러앉아 나아가지 못하는 이면이 공존한다.",
"빠른 두뇌 회전과 언어 감각, 정보를 연결해 새 그림을 만드는 재주가 탁월하다. 호기심이 넘쳐 어디서든 대화의 중심에 서고 낯선 분야도 빠르게 흡수한다. 그러나 관심이 여러 갈래로 흩어져 하나를 파는 깊이가 얕아지기 쉽다. 또한 말이 행동보다 앞서 가볍다는 인상을 주는 변덕이 공존한다.",
"내 사람을 지키려는 보호 본능과, 상대의 감정 결을 먼저 읽는 공감력이 탁월하다. 감정 기억이 깊어 관계의 온도를 세심하게 관리하고 오래 간직한다. 그러나 상처받으면 껍질 속으로 숨어 마음을 닫는 방어성이 커진다. 또한 지난 감정에 매여 옛 상처를 현재의 관계로 끌고 오는 이면이 공존한다.",
"타고난 존재감과, 사람을 끌어당기는 카리스마가 탁월하다. 인정과 무대가 주어질 때 능력이 배가되어 주변까지 밝히는 힘을 지닌다. 그러나 자존심이 삶의 중심이라 무시당하면 크게 흔들리고 무너지기 쉽다. 또한 주목받지 못하면 급격히 시들고, 타인의 그늘을 못 보는 이면이 공존한다.",
"디테일을 놓치지 않는 분석력과, 문제를 찾아내 개선하는 실무 능력이 탁월하다. 복잡한 일을 정돈하고 완성도를 높이는 데서 누구보다 강점을 보인다. 그러나 완벽주의와 잔걱정이 앞서 자신과 주변을 지치게 만들기 쉽다. 또한 부족한 곳부터 눈에 들어와 사소한 것에 매몰되는 이면이 공존한다.",
"균형 감각과 세련된 사교성, 대립을 조율하는 중재 능력이 탁월하다. 미적 감각이 뛰어나 관계와 공간을 조화롭게 가꾸는 힘을 지닌다. 그러나 결정을 미루고 타인의 시선을 의식하는 태도가 발목을 잡기 쉽다. 또한 갈등을 피하려다 자기 색을 흐리고 홀로 서는 힘이 약해지는 이면이 공존한다.",
"깊이 파고드는 집중력과, 위기 앞에서 되레 살아나는 승부 근성이 탁월하다. 사람과 상황의 감춰진 이면을 꿰뚫어 보는 통찰을 지닌다. 그러나 한번 등을 돌리면 되돌리지 않는 극단성이 관계를 끊어내기 쉽다. 또한 집착과 의심이 깊어지면 상대를 통제하려는 소유욕으로 번지는 이면이 공존한다.",
"낙천성과 큰 그림을 보는 시야, 자유를 향한 확장 본능이 탁월하다. 배움과 모험 속에서 성장하며 새로운 가능성을 발견하는 힘을 지닌다. 그러나 디테일과 마무리가 약하고 말에 과장이 섞이기 쉽다. 또한 한곳에 매이기 싫어 책임이 무거워지면 훌쩍 떠나버리는 이면이 공존한다.",
"목표를 향해 오래 버티는 인내와, 땅에 발붙인 현실적 야망이 탁월하다. 나이가 들수록 단단해지는 대기만성형으로 끝내 정상에 오르는 힘을 지닌다. 그러나 감정 표현에 인색해 차갑다는 오해를 사기 쉽다. 또한 성취에 매여 관계를 뒤로 미루고 정해진 틀에 갇혀 경직되는 이면이 공존한다.",
"독창적 사고와 시대를 앞서는 관점, 자유로운 개성이 탁월하다. 집단의 논리보다 자기 신념을 따르며 남들이 못 본 길을 여는 힘을 지닌다. 그러나 감정적으로 거리를 두어 가까운 사람도 차갑게 느낄 수 있다. 또한 믿음이 고집으로 굳어지면 타협을 거부하고 감정을 외면하기도 한다.",
"경계 없는 공감력과 예술적 상상력, 보이지 않는 것을 느끼는 감수성이 탁월하다. 사람의 아픔을 자기 일처럼 끌어안아 깊은 위로를 건네는 힘을 지닌다. 그러나 현실 감각이 흐려지고 헌신이 과해져 스스로를 소진하기 쉽다. 또한 경계가 없어 휘둘리고, 힘들면 현실에서 도피하려는 이면이 공존한다.",
];
