/* 상승점에 붙은 행성 — 1하우스 방향 10도 / 12하우스 방향 5도 이내면 사인을 덮어쓴다 */
const ASC_CONJ={Sun:"존재감이 뚜렷, 본인이 중심이 됨",Moon:"감정이 얼굴에 드러남, 사람들이 편하게 대함",Mercury:"말이 많고 젊어 보임, 반응이 빠름",Venus:"호감형, 외모 관리, 부드러운 인상",Mars:"강한 인상, 성급함, 부상·수술 경험",Jupiter:"크고 넉넉한 인상, 낙천적, 체중 관리 이슈",Saturn:"나이 들어 보임, 신중하고 위축된 인상, 늦게 피는 삶",Uranus:"독특함, 예측 불가, 어딘가 튀는 외양",Neptune:"흐릿하고 신비로움, 인상이 잘 기억되지 않음",Pluto:"압도적 존재감, 사람들이 어려워함"};
/* ═══ 조심해서 말할 단어 ═══
   지우기 위한 표시가 아니라 '그대로 읽지 말라'는 표시다. 상담사는 근거로 보되,
   내담자에게 옮길 때는 한 번 바꿔서 전달한다. 표시가 너무 많으면 신호가 죽으므로
   센 단어만 담는다. 목록은 이 배열만 고치면 된다. */
const CAREFUL_WORDS=[
"파국","파탄","파산","파괴","무너","붕괴","망가","최악","치명",
"실패","좌절","포기","무능","결함","오작동","약점","한계",
"손해","손실","빚","채무","사기","착취","분쟁","소송",
"배신","단절","이별","이혼","고립","외면","냉대","버림",
"상처","원망","복수","집착","질투","의심","불안","공포","두려","공허",
"중독","도피","위기","경고","질병","사망","죽음","자기 파괴",
"안 된다","못 한다","어렵다","위험",
];
const CAREFUL_RE=new RegExp("("+CAREFUL_WORDS.map(w=>w.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("|")+")","g");
/* 더 긴 단어의 일부로 걸리는 오탐 — 이 안에 든 매치는 표시하지 않는다.
   예: '분위기'의 위기, '오해를 사기 쉽다'의 사기(사다), '복수의 수입'의 복수(여럿) */
const CAREFUL_SKIP=[
"분위기","내외면",
"오해를 사기","반감을 사기","불신을 사기","호감을 사기","사기도 한다",
"복수의 수입","복수 영역","복수의",
"계산된 위험",
];
const CAREFUL_SKIP_RE=new RegExp("("+CAREFUL_SKIP.join("|")+")","g");
