"구두 계약 — 문서 없는 약속. 이 해의 말은 증거가 되지 못하며, 종이 없는 신뢰는 분쟁의 씨앗이 된다.",
"손절 회피 — 이미 죽은 프로젝트·관계를 매몰비용이 아까워 붙드는 일. 버려야 할 것을 쥔 손으로는 새것을 잡지 못한다.",
