    jobNote:"목표가 정해지면 끝까지 밀고 나가는 추진력에서 값이 나온다. 남 밑에 있다가 자기 것으로 독립하는 흐름이 맞고, 기존 사업이라면 확장 시점이다. 다만 여러 개를 동시에 벌이다 속도가 앞서면 무너지니, 속도 조절과 마무리를 받쳐 줄 사람이 필요하다.",
