/* ═══ 4순위: 품위(dignity)와 지배성 체인 ═══ */
const DIGNITY={
Sun:{dom:[4],ex:[0],det:[10],fall:[6]},
Moon:{dom:[3],ex:[1],det:[9],fall:[7]},
Mercury:{dom:[2,5],ex:[5],det:[8,11],fall:[11]},
Venus:{dom:[1,6],ex:[11],det:[7,0],fall:[5]},
Mars:{dom:[0,7],ex:[9],det:[6,1],fall:[3]},
Jupiter:{dom:[8,11],ex:[3],det:[2,5],fall:[9]},
Saturn:{dom:[9,10],ex:[6],det:[3,4],fall:[0]},
};
const DIG_LABEL={dom:"본좌",ex:"고양",det:"손상",fall:"쇠약"};
const DIG_TEXT={
dom:"자기 집에 있는 행성 — 이 행성이 관장하는 기능은 별다른 노력 없이도 힘이 실린다.",
ex:"귀빈으로 모셔진 행성 — 이 기능이 차트에서 가장 우아하게, 최상급으로 발휘된다.",
det:"낯선 땅의 행성 — 이 기능은 정공법이 아니라 우회로로 작동한다. 약점이 아니라 '다르게 쓰는 법'을 배워야 하는 자리다.",
fall:"힘이 꺾인 행성 — 이 기능에 자신감이 붙기까지 시간이 걸린다. 의식적 훈련이 필요하지만, 훈련되면 오히려 섬세한 강점이 된다.",
};
/* ═══ 쇠약(fall) 행성별 처방 — 훈련의 방향 ═══ */
const FALL_ADVICE={
Sun:"결정 전에 ‘남들이 어떻게 볼까’를 한 번 내려놓고 다시 물어보는 연습이 도움이 됩니다. 하루 한 번, 사소한 것이라도 자기 선호를 먼저 말해 보면 중심이 자리 잡기 쉽습니다.",
Moon:"감정을 끝까지 밀어붙이기보다, 중간에서 말이나 글로 꺼내 보는 편이 좋습니다. 신뢰하는 한 사람에게 주 1회 속을 여는 것만으로도 이 깊이가 부담보다 통찰로 남기 쉽습니다.",
Mercury:"논리만으로 정리되지 않는다면 이미지와 비유를 같이 써 보세요. 숫자·계약·일정은 문서와 다른 사람의 확인을 곁들이고, 이야기와 직관적인 설명은 자신의 방식으로 가져가면 됩니다.",
Venus:"애정을 분석하고 평가하는 습관이 거리를 만들 수 있습니다. 완벽하지 않은 호의도 일단 받아 보는 연습이 도움이 됩니다. 꼼꼼한 안목은 관계에서는 벽이 되지만, 실무와 심미, 검증에서는 강점이 될 수 있습니다.",
Mars:"정면으로 부딪히기보다 지키면서 가는 방식이 이 배치에는 더 맞을 수 있습니다. 분노는 바로 터뜨리기보다 하루 묵힌 뒤 표현하고, 운동으로 배출구를 두면 끈기가 힘으로 남기 쉽습니다.",
Jupiter:"낙관을 바로 실행하지 말고 작은 계획으로 바꿔 보세요. 확장은 작게 확인한 뒤 단계를 나누는 편이 오래갑니다.",
Saturn:"규칙을 세우기 전에 몸이 먼저 나가는 자신을 탓할 필요는 없습니다. 즉흥에 짧은 점검 목록 하나만 붙이면, 속도가 흐트러짐이 아니라 추진이 될 수 있습니다.",
};
function dignity(p,s){
  const d=DIGNITY[p];if(!d)return null;
  if(d.dom.includes(s))return"dom";
  if(d.ex.includes(s))return"ex";
  if(d.fall.includes(s))return"fall";
  if(d.det.includes(s))return"det";
  return null;
}
const RULER=["Mars","Venus","Mercury","Moon","Sun","Mercury","Venus","Pluto","Jupiter","Saturn","Uranus","Neptune"];
