const WealthGauge=({level})=>(
  <div className="lb-gauge" style={{marginTop:11}}>
    <div style={{display:"flex",alignItems:"flex-end",gap:4}}>
      {WEALTH_LEVELS.map(([,color,name],i)=>{
        const on=i===level-1;
        return(
          <div key={i} style={{flex:1,textAlign:"center"}}>
            <div style={{height:16+i*7,borderRadius:"4px 4px 13px 13px",background:color,opacity:on?1:0.45,border:on?`2px solid ${T.ink}`:"2px solid transparent",boxShadow:on?"0 3px 10px rgba(62,39,44,0.22)":"none"}}/>
            <p style={{margin:"4px 0 0",fontSize:9.5,fontWeight:on?800:400,color:on?T.ink:T.dim,wordBreak:"keep-all"}}>{name}</p>
          </div>
        );
      })}
    </div>
    <p style={{margin:"8px 0 0",fontSize:11.5,lineHeight:1.65,color:T.dim}}>
      <b style={{color:WEALTH_LEVELS[level-1][1]}}>●</b> <b style={{color:T.ink}}>{level}단계 · {WEALTH_LEVELS[level-1][2]}</b> — {WEALTH_LEVELS[level-1][3]}. (점성술 상징 분류이며 실제 자산 규모·소득 수준을 뜻하지 않음)
    </p>
  </div>
);
const LvGauge=({lv,max=5,color})=>(
  <span style={{display:"inline-flex",gap:2,verticalAlign:"middle",margin:"0 5px"}}>
    {Array.from({length:max},(_,i)=>(
      <span key={i} style={{width:12,height:8,borderRadius:2,background:i<lv?(color||T.bad):"#E6DED4",boxShadow:i<lv?"inset 0 -1px 0 rgba(0,0,0,0.12)":"none"}}/>
    ))}
  </span>
);
const Seal=({n,size=50})=>(
  <div style={{width:size,height:size,borderRadius:"50%",flexShrink:0,border:`1.5px solid ${T.accent}`,color:T.accent,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"var(--fd)",fontSize:size*0.42,fontWeight:"var(--fdw)",background:"#fff"}}>{n}</div>
);
const H=({children})=>{
  const arr=Array.isArray(children)?children:[children];
  const txt=arr.filter(c=>typeof c==="string").join("");
  const m=txt.match(/^\s*(\d+(?:-\d+)?)\s*·\s*/);
  const rest=arr.map((c,i)=>(i===0&&typeof c==="string"&&m)?c.replace(m[0],""):c);
  const c=(m&&SEC_COLOR[m[1]])||T.accent;
  return(
    <h2 className="sec-h" id={m?`sec-${m[1]}`:undefined} style={{borderBottomColor:c}}>
      {m&&<span className="sec-n" style={{color:c}}>{m[1]}</span>}
      <span className="sec-t">{rest}</span>
    </h2>
  );
};
const SECNAV=[["1","나"],["2","해년의수"],["3","원소"],["4","각도"],["5","하우스"],["6","강약"],["7","인생"],["8","조언"],["9","위기"]];
const SecNav=()=>(
  <nav className="secnav noprint lb-stepnav">
    {SECNAV.map(([n,l])=>(
      <button key={n} onClick={()=>{const el=typeof document!=="undefined"&&document.getElementById(`sec-${n}`);if(el)el.scrollIntoView({behavior:"smooth",block:"start"});}}>
        <i style={{background:SEC_COLOR[n]}}/><b>{n}</b>{l}
      </button>
    ))}
  </nav>
);

/* ═══ 개인 계산 ═══ */
function compute(solar,time,cityIdx,lunarOverride,baseYear,timeUnknown,timeMode,winStart,winEnd){
  if(!Number.isInteger(baseYear))baseYear=new Date().getFullYear();
  const[sy,sm,sd]=solar.split("-").map(Number);
  if(!(sy>=1901&&sy<=2049))return null;
  const auto=solarToLunar(sy,sm,sd);
  let lunar=auto;
  if(lunarOverride){
    const{year,month,day}=lunarOverride;
    if(Number.isInteger(year)&&Number.isInteger(month)&&Number.isInteger(day)&&month>=1&&month<=12&&day>=1&&day<=30)lunar=lunarOverride;
  }
  if(!lunar)return null;
  const cons=reduceLayer(sy+sm+sd),pre=reduceSingle(sy+sm+sd),unc=reduceLayer(lunar.year+lunar.month+lunar.day);
  const years=[];for(let y=baseYear;y<baseYear+5;y++)years.push({y,...reduceLayer(y+sm+sd)});
  let astro=null,timeConf=null;
  const[,lat,lon]=CITIES[cityIdx];
  const rawAt=(totalMinutes)=>{
    const loc=addLocalMinutes(sy,sm,sd,totalMinutes);
    const conv=seoulLocalToUtc(loc.y,loc.mo,loc.d,loc.hh,loc.mm);
    if(conv.status!=="valid")return {status:conv.status,loc};
    const J=conv.instants[0]/86400000+2440587.5;
    const am=ascMc(J,lat,lon);
    return{J,asc:am.asc,mc:am.mc,status:"valid",loc};
  };
  const buildAstro=(J,ascLon,mcLon,approx)=>{const planets={};
    for(const p of Object.keys(PL_KR))planets[p]={lon:planetLon(p,J),retro:isRetro(p,J)};
    return{sun:sunLon(J),moon:moonLon(J),asc:ascLon,mc:mcLon,planets,approx:!!approx,J0:J,geoLat:lat,geoLon:lon};};
  const toMin=t=>{const[h,m]=String(t||"").split(":").map(Number);return Number.isFinite(h)?h*60+(m||0):null;};
  const mode=timeMode||(timeUnknown?"unknown":(time?"exact":"unknown"));
  if(mode==="exact"&&time){
    const mins=toMin(time),c=Number.isInteger(mins)?rawAt(mins):{status:"invalid"};
    if(c.status==="valid"){
      astro=buildAstro(c.J,c.asc,c.mc,false);
      timeConf={mode:"exact",reliable:true};
    }else{
      const fallback=rawAt(12*60);
      if(fallback.status==="valid")astro=buildAstro(fallback.J,fallback.asc,fallback.mc,true);
      timeConf={mode:"exact",reliable:false,status:c.status};
    }
  }else if(mode==="window"){
    let a0=toMin(winStart),b0=toMin(winEnd);if(a0==null)a0=0;if(b0==null)b0=a0;if(b0<a0)b0+=1440;
    const ascSeq=[],mcSeq=[];
    const samples=[];
    for(let t=a0;t<=b0;t+=10)samples.push(t);
    if(samples[samples.length-1]!==b0)samples.push(b0);
    for(const t of samples){
      const c=rawAt(t);
      if(c.status==="valid"){
        ascSeq.push({t,sign:signOf(c.asc)});mcSeq.push({t,sign:signOf(c.mc)});
      }
    }
    const runs=seq=>{const o=[];for(const it of seq){const last=o[o.length-1];
      if(!last||last.sign!==it.sign)o.push({sign:it.sign,from:it.t,to:it.t});else last.to=it.t;}return o;};
    const ascC=runs(ascSeq),mcC=runs(mcSeq);
    const mid=Math.floor((a0+b0)/2),c=rawAt(mid);
    // 범위 입력은 상승점·하우스 판정이 완전히 같아도 확정된 출생시각이 아니다.
    if(c.status==="valid")astro=buildAstro(c.J,c.asc,c.mc,true);
    else if(ascSeq.length){const c2=rawAt(ascSeq[0].t);astro=buildAstro(c2.J,c2.asc,c2.mc,true);}
    const bodies=astro?[["Sun",astro.sun],["Moon",astro.moon],...Object.entries(astro.planets).map(([pp,v])=>[pp,v.lon])]:[];
    const houseVar=[];
    if(ascC.length>1)for(const[name,ln]of bodies){const hs=[...new Set(ascC.map(a=>((signOf(ln)-a.sign+12)%12)+1))];if(hs.length>1)houseVar.push({name,houses:hs});}
    timeConf={mode:"window",winStart,winEnd,ascCandidates:ascC,mcCandidates:mcC,houseVar,reliable:false,status:astro?"estimated":"invalid"};
  }else{
    const c=rawAt(12*60);if(c.status==="valid")astro=buildAstro(c.J,c.asc,c.mc,true);
    timeConf={mode:"unknown",reliable:false};
  }
  if(!astro)return null;
  if(astro)years.forEach(yr2=>{const L=allTransits(astro,yr2.y);yr2.transits=L;yr2.transit=L[0]||null;});
  return{sy,sm,sd,lunar,cons,pre,unc,years,astro,timeConf};
}
const wholeHouse=(lon,ascLon)=>((signOf(lon)-signOf(ascLon)+12)%12)+1;

/* ═══ 하우스 점유 헬퍼 ═══ */
function occupantsOf(a,hn){
  const L=[];
  if(wholeHouse(a.sun,a.asc)===hn)L.push("Sun");
  if(wholeHouse(a.moon,a.asc)===hn)L.push("Moon");
  for(const[p,v]of Object.entries(a.planets))if(wholeHouse(v.lon,a.asc)===hn)L.push(p);
  return L;
}
/* ═══ 재물의 그릇 7단계 ═══ */
const WEALTH_LEVELS=[
["클레이","#B5726A","종지","자원을 안정적으로 지키고 지출을 관리하는 주제"],
["러셋","#C2854E","밥그릇","일정한 수입과 생활의 지속성을 중요하게 다루는 주제"],
["메이즈","#BFA046","대접","규칙적인 축적과 계획을 중요하게 다루는 주제"],
["메도우랜드 그린","#7B9B63","항아리","장기적인 자원 운영과 분산을 검토하는 주제"],
["디지털 오션","#5A8AA6","독","여러 수입 경로와 자원 배분을 살펴보는 주제"],
["딥 그린","#4A5E90","곳간","조직과 공동 자원의 관리 책임을 살펴보는 주제"],
["루미너스 블루","#7A5E96","저수지","규모가 큰 자원과 의사결정의 책임을 살펴보는 주제"],
];
/* ═══ 인생 전체 개화 구간 — 목성이 태양·MC·출생 목성에 합으로 닿는 해 (약 12년 주기) ═══ */
function lifePotentialWindows(P){
  const a=P.astro;
  if(!a||a.approx)return[];
  const targets=[[a.sun,"태양 합 — 인생 방향 자체가 커지는 구간"],[a.mc,"커리어 정점 합 — 사회적 자리가 커지는 구간"],[a.planets.Jupiter.lon,"목성 리턴 — 12년 확장 주기의 재시작"]];
  const fromY=P.sy+12;   /* 만 12세 이후부터 인생 전체 스캔 */
  const toY=Math.min(P.sy+75,2099);
  const hits=[];
  for(let y=fromY;y<=toY;y++){
    let bt=null;
    for(let m=1;m<=12;m++){
      const J=julianDay(y,m,1,3);
      const jl=planetLon("Jupiter",J);
      for(const[t,nm]of targets){
        let d=Math.abs(jl-t)%360;if(d>180)d=360-d;
        if(d<=5&&(!bt||d<bt.d))bt={d,nm};
      }
    }
    if(bt)hits.push({y,...bt});
  }
  const groups=[];
  for(const h of hits){
    const g=groups[groups.length-1];
    if(g&&h.y<=g.end+1&&h.nm===g.nm){g.end=h.y;if(h.d<g.d){g.d=h.d;g.peak=h.y;}}
    else groups.push({start:h.y,end:h.y,peak:h.y,d:h.d,nm:h.nm});
  }
  return groups;
}
/* ═══ 재물 회로 판독 — 구조(회로) · 점화 조건 · 전제 조건 ═══ */
function wealthCircuit(P,level){
  const a=P.astro;
  const retroOf=(p)=>!!(a.planets[p]&&a.planets[p].retro);
  const kr=(p)=>KR10[p]+(retroOf(p)?"R":"");
  const o2=occupantsOf(a,2),o8=occupantsOf(a,8);
  const c2=chainOf(a,2),c8=chainOf(a,8);
  const h8=(signOf(a.asc)+7)%12,h2=(signOf(a.asc)+1)%12;
  const jh=wholeHouse(a.planets.Jupiter.lon,a.asc);
  /* ① 회로 — 돈이 어디서 들어와 어디에 쌓이는가 */
  let circuit;
  if(c8.rh===2)
    circuit=`8하우스(남의 돈) 주인 ${KR10[c8.rp]}이 2하우스(내 돈의 방)에 있다 — <b>타인 자본이 내 자산으로 전환되는 회로</b>가 차트에 명시적으로 그려져 있다. 이 상징은 공동자원과 개인자원의 관계를 상담 주제로 살펴보게 한다.`;
  else if(c2.rh===8)
    circuit=`2하우스(내 돈) 주인 ${KR10[c2.rp]}이 8하우스에 있다 — <b>내 돈이 남의 돈과 얽힐 때 비로소 커지는 회로</b>다. 실제 자금 운용 방식은 내담자의 상황을 확인한 뒤 판단해야 한다.`;
  else
    circuit=`8하우스 주인 ${KR10[c8.rp]}은 ${c8.rh}하우스, 2하우스 주인 ${KR10[c2.rp]}은 ${c2.rh}하우스에 있다 — <b>남의 돈은 '${HOUSE_SHORT[c8.rh-1]}'의 무대를 통해 들어오고, 내 수입은 '${HOUSE_SHORT[c2.rh-1]}'의 영역에서 만들어진다.</b>`;
  if(o8.length)circuit+=` 8하우스에 ${o8.map(kr).join("·")}이 앉아 있어 이 회로가 인생에서 실제로 크게 작동한다.`;
  if(o2.length)circuit+=` 2하우스에는 ${o2.map(kr).join("·")}이 있다.`;
  if(o8.some(p=>["Jupiter","Venus"].includes(p))||o2.some(p=>["Jupiter","Venus","Sun","Moon"].includes(p)))
    circuit+=` <b>${level}/7단계 판정의 핵심 근거가 정확히 이 배치다.</b>`;
  /* ② 점화 — 이 회로는 어떻게 켜지는가 */
  const keys=[...new Set([...o8,...o2,"Jupiter"])];
  const retros=keys.filter(retroOf);
  let ignition;
  if(retros.length)
    ignition=`${retros.map(p=>KR10[p]).join("·")}이 <b>역행</b>이라 이 회로는 대기 상태로 태어난다 — 좋은 조건이 알아서 굴러오길 기다리면 평생 잠잔다. <b>본인이 먼저 조건을 확인하고 선택지를 검토하는 주제로 읽을 수 있다</b>. 대출·투자·공동 명의는 차트만으로 권할 수 없으며 계약조건·상환능력·위험을 따로 확인해야 한다. 그리고 8하우스가 ${SIGNS[h8]}라, 남의 돈을 다루는 방식은 <b>${SIGN_MODE[h8]}</b> 형태여야 맞는다 — 뒤에서 얹혀 가는 구조는 이 배치와 어긋난다.`;
  else
    ignition=`재물 축에 역행이 없어 이 회로는 <b>외부의 제안을 살펴보는 주제</b>로 읽을 수 있다 — 정보와 사람에 노출된 상태를 유지하는 것(네트워크·공개 활동)이 곧 점화 조건이다. 다만 들어온 제안을 거르는 검증 절차는 스스로 세워야 한다. 8하우스가 ${SIGNS[h8]}라 남의 돈을 다루는 방식은 <b>${SIGN_MODE[h8]}</b> 형태여야 맞는다.`;
  /* ③ 전제 — 켜기 전에 알고 있어야 할 조건 */
  const pre=[];
  if(o2.includes("Saturn"))pre.push("2하우스(내 돈의 방)에 토성 — 들어온 자금이 성과로 도는 데 시간이 걸린다. <b>초반 6개월~1년의 더딤을 실패 신호로 읽지 않는 것</b>이 이 배치의 전제 조건이다");
  if(o8.includes("Saturn")||o8.includes("Pluto"))pre.push("8하우스에 토성/명왕성 — 남의 돈은 반드시 문서와 절차로 다뤄야 한다. 구두 합의와 지분 미확정 상태를 남기면 이 회로가 자산이 아니라 부채로 뒤집힌다");
  if(o8.includes("Neptune"))pre.push("8하우스에 해왕성 — 조건이 애매한 자금(구두 약속, 명의만 빌려주는 구조)은 반드시 거절하라. 이 자리에서 새는 돈은 회수가 어렵다");
  const jDg=dignity("Jupiter",signOf(a.planets.Jupiter.lon));
  if(jDg==="fall"||jDg==="det")pre.push(`확장의 별이 ${DIG_LABEL[jDg]} — 한 번에 크게 벌이는 확장은 독이다. 작게 검증한 뒤 단계적으로 키우는 순서만 지키면 결과는 같아진다`);
  if(!pre.length)pre.push("뚜렷한 제동 장치가 없다 — 브레이크도 없다는 뜻이니, 확장 한도와 손절 기준을 스스로 정해 두는 것이 이 배치의 유일한 안전장치다");
  return{circuit,ignition,premise:pre.join(". "),jh};
}
function wealthBowl(P){
  const a=P.astro;
  const occ=(hn)=>occupantsOf(a,hn);
  const o2=occ(2),o8=occ(8);
  let plus=0;const why=[];
  /* ── 세대 요소(금성·목성 별자리)는 등급 계산에서 제외한다 ──
     같은 해 출생자 수백만 명이 공유하는 배치라, 가점으로 넣으면 한 세대 전체가 상향 평준화된다.
     서술로만 남기고, 개인 요소가 이미 강할 때에 한해 최대 +1까지만 반영한다. */
  let genBonus=0;const genWhy=[];
  const vS=signOf(a.planets.Venus.lon),vDg=dignity("Venus",vS);
  if(vDg==="ex"||vDg==="dom"){genBonus+=0.5;genWhy.push(`금성(재화의 별)이 ${SIGNS[vS]}에서 ${DIG_LABEL[vDg]} — 돈과 사람을 끌어당기는 기본기가 좋다. 다만 같은 시기 출생자가 공유하는 배치다`);}
  const jS=signOf(a.planets.Jupiter.lon),jDg=dignity("Jupiter",jS);
  if(jDg==="ex"||jDg==="dom"){genBonus+=0.5;genWhy.push(`목성(확장의 별)이 ${SIGNS[jS]}에서 ${DIG_LABEL[jDg]} — 불리는 힘이 실려 있다. 다만 같은 시기 출생자가 공유하는 배치다`);}

  /* ── 개인 요소: 2하우스 주인의 상태가 재물 판정의 핵심 ── */
  const c2=chainOf(a,2);
  const rp=c2.rp, rpLon=(rp==="Sun")?a.sun:(rp==="Moon")?a.moon:(a.planets[rp]?a.planets[rp].lon:null);
  const rpDg=(rpLon!=null)?dignity(rp,signOf(rpLon)):null;
  if(rpDg==="ex"||rpDg==="dom"){plus+=2;why.push(`돈의 방 주인 ${KR10[rp]}이 제 힘을 온전히 쓰는 자리에 있어, 버는 구조 자체가 튼튼하다`);}
  else if(rpDg==="det"||rpDg==="fall"){plus-=1;why.push(`돈의 방 주인 ${KR10[rp]}이 힘을 쓰기 어려운 자리에 있어, 수입이 정공법보다 우회로로 만들어진다`);}
  if([1,2,10,11].includes(c2.rh)){plus+=1.5;why.push(`돈의 방 주인이 ${c2.rh}하우스에 앉아 재물 활동이 인생의 전면에서 작동한다`);}
  else if([4,5,6,7,9].includes(c2.rh)){plus+=0.5;why.push(`돈의 방 주인이 ${c2.rh}하우스에 있어 '${HOUSE_SHORT[c2.rh-1]}' 영역을 통해 수입이 만들어진다`);}
  else if([8,12].includes(c2.rh)){why.push(`돈의 방 주인이 ${c2.rh}하우스에 있어 수입의 경로가 겉으로 잘 드러나지 않고, 남의 돈·보이지 않는 일과 얽히기 쉽다`);}

  /* ── 2·8하우스 점유 ── */
  if(o2.includes("Jupiter")||o2.includes("Venus")){plus+=2;why.push("돈의 방(2하우스)에 길성이 앉아 그릇 자체가 크게 태어났다");}
  if(o2.includes("Saturn")){plus-=0.5;why.push("돈의 방에 토성 — 그릇은 단단하나 늦게 찬다. 젊은 시절의 결핍감이 중년 이후의 축적으로 반전되는 만기(晩期)형 구조다");}
  if(o2.includes("Mars")){plus-=0.5;why.push("돈의 방에 화성 — 들어오는 만큼 나가는 속도도 빨라, 지출을 규칙으로 묶지 않으면 남지 않는다");}
  if(o2.includes("Sun")||o2.includes("Moon")){plus+=1;why.push("돈의 방에 빛(태양·달) — 돈이 인생 주제의 중심에 놓이며, 벌 때와 못 벌 때의 자존감 낙차가 크다");}
  if(o8.includes("Jupiter")||o8.includes("Venus")){plus+=1.5;why.push("큰돈의 방(8하우스)에 길성 — 대출·투자·공동자산 등 타인의 돈을 지렛대로 쓰는 운이 있다");}
  if(o8.includes("Saturn")||o8.includes("Pluto"))why.push("큰돈의 방에 토성/명왕성 — 남의 돈이 얽히는 일(대출·동업·상속)은 반드시 문서와 절차로 다뤄야 탈이 없는 구조다");

  /* 세대 가점은 개인 요소가 이미 플러스일 때만, 그것도 상한 +1까지 붙는다 */
  const personal=plus;
  if(personal>0&&genBonus>0)plus+=Math.min(genBonus,1);
  why.push(...genWhy);

  const level=personal<=-1.5?1:plus<=-0.5?2:plus<=2?3:plus<=3.5?4:plus<=5?5:plus<=6.5?6:7;
  const grade=level>=5?"큰 그릇 · 선천 확장형":level>=3?"중형 그릇 · 관리 확장형":"작은 그릇 · 수성(守成)형";
  const gradeTxt=level>=5
    ?"자원 확장과 관리의 상징이 상대적으로 강조된다. 실제 수입의 상한이나 자산 수준을 예측하지는 않는다."
    :level>=3
    ?"규칙과 계획을 중요하게 다루는 상징이다. 실제 재정 관리 방식은 소득·지출·부채 등을 확인하여 결정한다."
    :"자원을 안정적으로 관리하는 주제를 살펴볼 수 있다. 실제 자산 규모나 경제적 역량을 낮게 평가하는 뜻은 아니다.";
  /* 회로·점화·전제 (모든 등급) + 포텐 시기 (4단계 이상) */
  const wc=wealthCircuit(P,level);
  let potential=`\n\n【회로】\n${wc.circuit}\n\n【점화 조건】\n${wc.ignition}\n\n【전제 조건】\n${wc.premise}.`;
  if(level>=4){
    const wins=lifePotentialWindows(P);
    const nowY=Number.isInteger(P.years?.[0]?.y)?P.years[0].y:new Date().getFullYear();
    const past=wins.filter(g=>g.end<nowY), future=wins.filter(g=>g.end>=nowY);
    const fmt=(g)=>`${g.peak}년 전후(만 ${g.peak-P.sy}세 · ${g.nm.split(" — ")[0]})`;
    let timing;
    if(!wins.length) timing="개화 신호 계산에 필요한 천체 창이 확보되지 않았다 — 출생시간 입력 후 다시 확인하라";
    else{
      const parts=[];
      if(past.length) parts.push(`지나간 구간은 ${past.slice(-3).map(fmt).join(", ")}이었다 — 그때 무엇을 했고 무엇을 놓쳤는지 확인하면, 앞으로의 구간을 쓰는 방식이 분명해진다`);
      parts.push(future.length
        ? `앞으로 올 구간은 ${future.slice(0,3).map(fmt).join(", ")}이다 — 약 12년 주기로 재림하므로 한 구간을 놓쳐도 끝이 아니다`
        : `앞으로의 구간은 계산 범위 밖이다 — 이미 주요 개화 구간을 지나온 상태이니, 지금은 벌리기보다 쌓아 온 것을 굳히는 국면으로 읽는다`);
      parts.push(`확장의 별이 ${wc.jh}하우스에 있으니 '${HOUSE_SHORT[wc.jh-1]}' 영역에 판을 벌이는 결정을 이 구간에 맞추는 것이 그릇을 실제로 채우는 공식이다`);
      timing=parts.join(". ");
    }
    potential+=`\n\n【포텐이 터지는 시기】\n${timing}.`;
  }
  const text=`【${grade} · ${WEALTH_LEVELS[level-1][2]} ${level}/7단계】
${gradeTxt}
무의식층 ${card(P.unc.main)[0]}의 욕구가 재물 활동의 심리적 동기를 이룬다.

【등급 근거】
${why.map(w=>`· ${w}`).join("\n")}${potential}

▸ 등급은 개인 요소(2하우스 주인의 상태와 행선지, 2·8하우스 점유)로 산정한다. 금성·목성의 별자리 품위는 같은 시기 출생자가 공유하는 세대 요소라 등급을 좌우하지 않고, 개인 요소가 이미 플러스일 때 최대 +1까지만 얹는다.
▸ 이 단계는 앱 내부의 상징적 분류이며 실제 소득·자산 규모·신용도·경제적 성공을 측정하거나 예측하지 않는다. 금융 의사결정은 별도의 실제 자료와 전문가 검토를 바탕으로 한다.`;
  return{__wealth:true,level,text};
}


/* ═══ 원소 균형 — 강한 기운·부족한 기운·보충 처방 ═══ */
