"Saturn|asc":"몸이 신호를 보낼 수 있다 — 만성 피로, 치아·관절·면역처럼 오래 쓴 부위에 이상 신호가 오고, 관계망이 자연스럽게 축소되는 경향이 있다.",
"Uranus|sun":"직업 궤도가 예고 없이 끊길 수 있다 — 퇴사·해고·전업 결심이 짧은 기간 안에 굳어지기 쉬운 시기다.",
"Uranus|moon":"터전이 급변할 수 있다 — 계획에 없던 이사, 또는 가족 구성의 변화(독립·합류·별거)로 생활 기반이 흔들리기 쉽다.",
"Uranus|asc":"생활 반경이 물갈이될 수 있다 — 소속과 어울리는 사람이 크게 바뀌고, 이 구간엔 사고·부상 주의가 평소보다 요구된다.",
