function dignityRead(p,s,dg){
  const fn=PLANET_FUNC[p]||"";
  if(dg==="dom")return{strong:true,point:`${fn}이 비교적 자연스럽게 나옵니다. ${PLANET_STRONG[p]||""}`,guide:"약점을 고치는 데만 쓰기보다, 이 기능을 역할의 중심에 두면 힘이 덜 듭니다."};
  if(dg==="ex")return{strong:true,point:`${fn}이 보기 좋게 드러나는 자리입니다. ${PLANET_STRONG[p]||""}`,guide:"직업이나 역할에서 이 면을 앞에 두면, 강점이 더 잘 전달됩니다."};
  if(dg==="det")return{strong:false,point:`${fn}은 흔히 쓰는 방식으로는 잘 풀리지 않을 수 있습니다. ${PLANET_WEAK[p]||""}`,guide:"남과 같은 방법을 그대로 따르기보다, 자신에게 맞는 우회로를 찾으면 이 영역이 개성이 될 수 있습니다."};
  return{strong:false,point:`${fn}에 자신감이 붙기까지 시간이 걸릴 수 있습니다. ${PLANET_WEAK[p]||""}`,guide:FALL_ADVICE[p]||"속도가 느릴 뿐이며, 연습하면 섬세한 강점으로 남을 수 있습니다."};
}
