function clientWealth(P){
  const a=P.astro;if(!a)return "";
  const out=[];
  // 재물의 그릇 등급 (기존 로직 재사용)
  let lv=null;
  try{const wb=(typeof wealthBowl==="function")?wealthBowl(P):null; if(wb&&wb.level)lv=wb.level;}catch(e){}
  if(lv&&CL_BOWL[lv-1]) out.push(`타고난 재물의 그릇으로 보면, ${CL_BOWL[lv-1]}`);
  // 투자 성향 = 화성 별자리
  const maS=signOf(a.planets.Mars.lon);
  out.push(`돈을 굴릴 때의 성향은 이렇습니다. ${CL_INVEST[maS]}`);
  out.push(`그릇의 크기는 태어날 때 정해지지만, 그 안을 채우는 것은 규칙과 실행입니다. 그릇이 크다고 저절로 차지 않고, 작다고 늘 부족한 것도 아닙니다.`);
  return out.join("\n\n");
}
