function clientMerged(P){
  const a=P.astro;if(!a)return "";
  const sunS=signOf(a.sun),moonS=signOf(a.moon);
  const ascS=a.approx?null:signOf(a.asc);
  const faceS=(ascS!=null)?ascS:sunS;
  const same=(faceS%4)===(moonS%4);
  const out=[];
  out.push(`사람들 눈에 이분은 ${CL_OUTER[faceS]}으로 보입니다. ${SIGN_MODE[faceS]} 방식이 몸에 배어 있어, 처음 만나는 자리에서도 그 인상이 먼저 전해집니다.`);
  out.push(`그런데 안쪽은 결이 다릅니다. ${CL_INNER[moonS]}.${CL_GAP[same?1:0]?" "+CL_GAP[1]:""}`);
  if(!same){
    const MIS=[
     `그래서 늘 기운이 넘치는 사람으로 오해받습니다. 참고 기다리는 데 쓰는 힘은 아무도 모릅니다.`,
     `그래서 알아서 잘하는 사람으로 오해받습니다. 혼자 지고 있는 무게는 아무도 묻지 않습니다.`,
     `그래서 별생각 없이 편한 사람으로 오해받습니다. 멈추지 않는 머릿속은 겉으로 티가 나지 않습니다.`,
     `그래서 무던하고 잘 견디는 사람으로 오해받습니다. 안에 쌓이는 감정의 무게는 보이지 않습니다.`,
    ];
    out.push(MIS[moonS%4]);
  }
  else out.push(`겉과 속이 같다는 것은 솔직하고 일관되다는 뜻이지만, 동시에 완충 장치가 적다는 뜻이기도 합니다. 힘들 때 다른 방식으로 숨을 돌릴 여지가 적으니, 의식적으로 결이 다른 활동을 곁에 두시면 훨씬 편안해집니다.`);
  out.push(`남들이 보는 나와 내가 아는 나가 다른 것은 이상한 일이 아니라, 원래 두 결을 함께 지니고 태어났기 때문입니다.`);
  return out.join("\n\n");
}
