/* ═══ 일의 물리적 성격 (제3축) — 손/몸·야외·이동·대면·공공·정적 ═══ */
const WORK_MODE={
hand:{k:"hand",label:"손·몸을 쓰는 일",desc:"머리보다 손끝과 몸의 감각이 결과를 만드는 일 — 만들고 고치고 다루는 기술직·기능직·시술직. 앉아서 서류만 만지는 자리에 두면 이 사람의 재능이 잠든다.",jobs:["기술·기능직(설비·전기·용접·정비)","조리·제과 등 손기술 전문","공예·목공·도예·수선","물리치료사·재활 트레이너","미용·네일·타투 등 시술직","치과·외과 등 손을 쓰는 의료","정원·조경·농업 실무","악기 연주·수리"]},
outdoor:{k:"outdoor",label:"밖에서·해를 보며 하는 일",desc:"실내에 종일 갇히면 기운이 꺼지는 유형 — 현장·야외·자연이 무대일 때 살아난다. 사무실 붙박이 자리는 오래 못 견딘다.",jobs:["건설·토목 현장 관리","조경·산림·농수산","스포츠 지도자·현장 코치","측량·시설 점검","택배·물류 현장","항만·항공 현장직","캠핑·아웃도어 사업","현장 촬영·다큐 제작"]},
mobile:{k:"mobile",label:"돌아다니는 일 (이동·출장)",desc:"한자리에 묶이면 답답해지고, 움직일수록 기회가 붙는 유형 — 외근·출장·현장 순회·해외가 맞는다. 고정된 자리에 앉히면 성과도 흥미도 떨어진다.",jobs:["영업·외근직","현장 서비스 엔지니어","운수·운송·기사","여행 인솔·가이드","해외영업·무역","방문 교육·방문 케어","현장 취재 기자","순회 점검·감사"]},
people:{k:"people",label:"사람을 직접 마주하는 일",desc:"화면·서류가 아니라 사람의 얼굴 앞에서 힘이 나는 유형 — 대면 응대·상담·교육·돌봄. 사람과 단절된 자리는 이 사람을 시들게 한다.",jobs:["상담사·코치","교사·강사","간호·요양·돌봄","서비스·접객 매니저","영업 상담","사회복지사","헤어·뷰티 대면 서비스","이벤트·행사 진행"]},
public:{k:"public",label:"공공·조직 안정형 (공무원·공기업)",desc:"제도와 규정이 분명한 곳에서 안정적으로 오래 일할 때 힘을 내는 유형 — 공직·공공기관·대조직. 성과가 매달 흔들리는 자리는 이 사람을 불안하게 만든다.",jobs:["행정·일반 공무원","경찰·소방·군","교사·공립 교원","공기업·공공기관","세무·회계 공직","시설·안전 관리 공직","보건소·공공의료","우정·철도 등 공공 서비스"]},
desk:{k:"desk",label:"앉아서 파고드는 일 (정적·전문)",desc:"조용히 오래 집중할 때 깊이가 나오는 유형 — 분석·연구·집필·설계. 소란한 대면 현장에 오래 두면 소진된다.",jobs:["연구·분석직","개발·설계","회계·세무 실무","기록·편집·번역","데이터·통계","법무·문서 전문","심사·검토직","집필·기획"]},
};
function workModes(P){
  const a=P.astro;if(!a)return[];
  const approx=a.approx;
  const sc={hand:0,outdoor:0,mobile:0,people:0,public:0,desk:0};
  const ev={hand:[],outdoor:[],mobile:[],people:[],public:[],desk:[]};
  const add=(k,n,why)=>{sc[k]+=n;ev[k].push(why);};
  const EL_OF=s2=>s2%4; // 0불 1흙 2공기 3물
  const mcS=signOf(a.mc),marsS=signOf(a.planets.Mars.lon),meS=signOf(a.planets.Mercury.lon);
  // MC 원소
  if(!approx){const e=EL_OF(mcS);
    if(e===1){add("hand",1.1,`MC ${SIGNS[mcS]}(흙) — 실물·손끝의 결과물`);add("public",0.6,`MC ${SIGNS[mcS]}(흙) — 제도·조직 적성`);}
    if(e===0){add("outdoor",1.0,`MC ${SIGNS[mcS]}(불) — 현장·활동 무대`);add("mobile",0.6,`MC ${SIGNS[mcS]}(불) — 움직이는 일`);}
    if(e===2){add("mobile",1.0,`MC ${SIGNS[mcS]}(공기) — 이동·전달`);add("people",0.6,`MC ${SIGNS[mcS]}(공기) — 소통 대면`);}
    if(e===3){add("people",1.1,`MC ${SIGNS[mcS]}(물) — 정서적 대면`);add("desk",0.5,`MC ${SIGNS[mcS]}(물) — 내향적 몰입`);}
  }
  // 화성 = 몸을 쓰는 방식
  {const e=EL_OF(marsS);
   if(e===1)add("hand",1.2,`화성 ${SIGNS[marsS]}(흙) — 손·몸의 지구력`);
   if(e===0){add("outdoor",1.0,`화성 ${SIGNS[marsS]}(불) — 야외 활동력`);add("hand",0.5,`화성 ${SIGNS[marsS]}(불) — 직접 다루는 힘`);}
   if(e===2)add("mobile",1.0,`화성 ${SIGNS[marsS]}(공기) — 돌아다니는 추진력`);
   if(e===3)add("people",0.8,`화성 ${SIGNS[marsS]}(물) — 사람에게 쏟는 에너지`);}
  // 수성 = 일머리 방향
  {const e=EL_OF(meS);
   if(e===1)add("hand",0.6,`수성 ${SIGNS[meS]}(흙) — 실무·기능 학습형`);
   if(e===2){add("mobile",0.5,`수성 ${SIGNS[meS]}(공기) — 정보 이동형`);add("desk",0.5,`수성 ${SIGNS[meS]}(공기) — 분석형`);}
   if(e===3)add("people",0.5,`수성 ${SIGNS[meS]}(물) — 공감 소통형`);
   if(e===0)add("people",0.4,`수성 ${SIGNS[meS]}(불) — 표현·전달형`);}
  if(!approx){
    // 하우스 점유
    const occ=h=>occupantsOf(a,h);
    for(const pl of occ(6))add("hand",0.7,`${KR10[pl]} 6하우스 — 실무·기술 현장`);
    for(const pl of occ(3))add("mobile",0.8,`${KR10[pl]} 3하우스 — 이동·근거리 활동`);
    for(const pl of occ(9))add("mobile",0.7,`${KR10[pl]} 9하우스 — 원거리·해외 이동`);
    for(const pl of occ(7))add("people",0.8,`${KR10[pl]} 7하우스 — 일대일 대면`);
    for(const pl of occ(11))add("people",0.4,`${KR10[pl]} 11하우스 — 집단 대면`);
    for(const pl of occ(12))add("desk",0.9,`${KR10[pl]} 12하우스 — 비공개·정적 몰입`);
    for(const pl of occ(10))if(pl==="Saturn")add("public",1.2,"토성 10하우스 — 제도·공직 적성");
    for(const pl of occ(4))add("desk",0.4,`${KR10[pl]} 4하우스 — 재택·내부 기반`);
    // 토성 = 안정·제도 지향
    const satH2=wholeHouse(a.planets.Saturn.lon,a.asc);
    if([2,6,10].includes(satH2))add("public",0.9,`토성 ${satH2}하우스 — 안정된 소속에서 성과`);
    // 커리어 방 주인 위치
    const c=chainOf(a,10);
    if([3,9].includes(c.rh))add("mobile",0.9,`10H 주인 ${c.rh}하우스 — 이동으로 커리어가 열림`);
    if(c.rh===6)add("hand",0.8,`10H 주인 6하우스 — 실무·기능으로 커리어가 열림`);
    if(c.rh===7)add("people",0.9,`10H 주인 7하우스 — 대면·파트너십으로 열림`);
    if(c.rh===12)add("desk",0.8,`10H 주인 12하우스 — 조용한 전문으로 열림`);
    if(c.rh===10)add("public",0.7,"10H 주인 제집 — 공적 조직 트랙");
  }
  return Object.values(WORK_MODE).map(m=>({...m,score:sc[m.k],ev:ev[m.k],real:(JOB_REAL[m.k]||[])}))
    .filter(m=>m.score>0).sort((x,y)=>y.score-x.score);
}
function synthesizeThemes(P){
  const a=P.astro;if(!a)return[];
  const asp=natalAspects(a),approx=a.approx;
  const lonOf=(p)=>p==="Sun"?a.sun:p==="Moon"?a.moon:(a.planets[p]?a.planets[p].lon:null);
  const pers=[["Sun",a.sun],["Moon",a.moon],["Mercury",a.planets.Mercury.lon],["Venus",a.planets.Venus.lon],["Mars",a.planets.Mars.lon]];
  if(!approx){pers.push(["Asc",a.asc]);pers.push(["MC",a.mc]);}
  const out=[];
  for(const th of THEMES){
    const ev={aspect:[],sign:[],house:[],angular:[],dignity:[]};let score=0;
    for(const[p1,p2]of th.pairs){const hit=asp.find(r=>(r.a===p1&&r.b===p2)||(r.a===p2&&r.b===p1));
      if(hit){score+=(hit.tone==="h"?1:hit.tone==="c"?0.9:0.5)*(hit.o<=3?1:0.6);ev.aspect.push(`${KR10[hit.a]}–${KR10[hit.b]} ${hit.nm}`);}}
    for(const[nm,ln]of pers)if(th.signs.includes(signOf(ln))){score+=0.5;ev.sign.push(`${nm==="Asc"?"상승":nm==="MC"?"MC":KR10[nm]} ${SIGNS[signOf(ln)]}`);}
    if(!approx)for(const h of th.houses)for(const occ of occupantsOf(a,h)){score+=0.4;ev.house.push(`${KR10[occ]} ${h}H`);}
    if(!approx)for(const pl of th.planets){const ln=lonOf(pl);if(ln==null)continue;
      for(const[anm,al]of[["상승",a.asc],["MC",a.mc]]){let d=Math.abs(ln-al)%360;if(d>180)d=360-d;if(d<=8){score+=0.6;ev.angular.push(`${KR10[pl]} ${anm} 근접`);}}}
    for(const pl of th.planets){const ln=lonOf(pl);if(ln==null)continue;const dg=dignity(pl,signOf(ln));
      if(dg){score+=0.4;ev.dignity.push(`${KR10[pl]} ${dg==="dom"?"본질":dg==="ex"?"고양":dg==="det"?"손상":"쇠약"}`);}}
    const cats=Object.values(ev).filter(x=>x.length).length;
    if(cats>=2)out.push({id:th.id,title:th.title,core:th.core,ev,convergence:cats,score});
  }
  return out.sort((x,y)=>y.score-x.score).slice(0,3);
}
/* ═══ 출생시각 리스크 — 표준시·서머타임 보정이 걸린 구간을 상담사에게 명시한다 ═══
   앱은 koreaOffset()에서 이미 보정하지만, 내담자가 말한 시계 시각과 실제 표준시가
   다른 구간이므로 "왜 다른가"를 상담사가 설명할 수 있어야 한다. */
function timeZoneNote(y,mo,d){
  const t=y*10000+mo*100+d, on=(a,b)=>t>=a&&t<b;
  const off=koreaOffset(y,mo,d);
  if(on(19870510,19871011)||on(19880508,19881009))
    return{lv:"high",label:"서머타임 시행 구간",
      body:`1987~88년 서울올림픽 대비 서머타임 기간이다. 시계가 1시간 앞당겨져 있었으므로 내담자가 기억하는 시각에서 1시간을 뺀 것이 실제 표준시다. 앱은 UTC+${off}로 보정해 계산했다. 이 보정을 놓치면 상승점이 통째로 밀리므로, 첫인상 서술이 내담자 반응과 어긋나면 이 지점을 먼저 의심할 것.`};
  if(on(19540321,19610810))
    return{lv:"high",label:"표준시 UTC+8:30 구간",
      body:`1954년 3월~1961년 8월은 한국 표준시가 동경 127.5도 기준(UTC+8:30)이었다. 현행 UTC+9로 계산하면 상승점이 약 7.5도 밀린다. 앱은 UTC+${off}로 보정했다. 이 시기 출생자는 상승점 두 개를 산출해 내담자의 실제 특성과 대조하는 것이 안전하다.`};
  if(on(19480601,19480913)||on(19490403,19490911)||on(19500401,19500910)||on(19510506,19510909))
    return{lv:"high",label:"초기 서머타임 구간",
      body:`1948~51년 서머타임 시행 기간이다. 앱은 UTC+${off}로 보정했다. 기록과 기억이 엇갈리기 쉬운 시기이므로 출생증명서 확인을 권한다.`};
  if(t<19120101)
    return{lv:"mid",label:"표준시 제정 이전",
      body:`1912년 이전은 표준시 체계가 지금과 달랐다. 앱은 UTC+${off}로 계산했으나 지역 편차가 있을 수 있다.`};
  return null;
}
function TimeConfBanner({conf}){
  if(!conf||conf.mode==="exact")return null;
  const fmt=m=>`${String(Math.floor(m/60)).padStart(2,"0")}:${String(m%60).padStart(2,"0")}`;
  if(conf.mode==="unknown"){
    return(<section style={{background:"#FAF6F2",border:"1px solid #E0D2C8",borderRadius:12,padding:"12px 14px",marginBottom:14}}>
      <p style={{margin:0,fontSize:12.5,lineHeight:1.7,color:"#8C6A55"}}><b>출생시간 미상</b> — 상승궁·하우스·MC 기반 해석은 신뢰할 수 없어 생략·표기됩니다. 아래 결론 중 <b>행성 별자리·애스펙트·원소·수비학</b>만 시간과 무관하게 유효합니다.</p>
      <p style={{margin:"6px 0 0",fontSize:11.5,lineHeight:1.75,color:T.dim}}>
        정오 기준으로 계산했습니다. <b>달은 하루에 최대 15도 이동</b>하므로 경계일이면 별자리가 둘일 수 있습니다. 하우스를 해석하지 않는다는 점을 내담자에게 먼저 밝히는 것이 오히려 신뢰를 만듭니다. 출생시각 역산(렉티피케이션)은 상담 현장에서 즉석으로 시도하지 않습니다 — 검증되지 않은 시각으로 하우스를 읽으면 오독이 누적됩니다.
      </p>
    </section>);
  }
  const asc=conf.ascCandidates||[],reliable=conf.reliable;
  return(<section style={{background:reliable?"#F3F4EF":"#FAF7F0",border:`1px solid ${reliable?"#DDE0D6":"#E4DBC8"}`,borderRadius:12,padding:"12px 14px",marginBottom:14}}>
    <div style={{fontSize:12.5,lineHeight:1.75,color:T.ink}}>
      <p style={{margin:"0 0 6px",fontWeight:700,color:reliable?"#6B7A63":"#8F7A4E"}}>
        {reliable?"상승궁 확정 ✓":`상승궁 후보 ${asc.length}개 — 하우스 해석 잠정`}
        <span style={{fontWeight:400,color:T.dim}}> · 출생시간 {conf.winStart}~{conf.winEnd}</span>
      </p>
      <p style={{margin:"0 0 4px"}}>상승궁: {asc.map(a=>`${SIGNS[a.sign]}(${fmt(a.from)}~${fmt(a.to)})`).join(" 또는 ")}</p>
      {conf.mcCandidates&&conf.mcCandidates.length>1&&<p style={{margin:"0 0 4px"}}>MC(직업 축): {conf.mcCandidates.map(a=>SIGNS[a.sign]).join(" 또는 ")} — 직업 해석도 잠정</p>}
      {conf.houseVar&&conf.houseVar.length>0&&<p style={{margin:"4px 0 0",color:T.dim}}>시간에 따라 하우스가 달라지는 천체: {conf.houseVar.map(h=>`${KR10[h.name]}(${h.houses.join("/")}H)`).join(", ")}.</p>}
      {reliable&&<p style={{margin:"4px 0 0",color:T.dim}}>이 시간대 전체에서 상승궁이 한 별자리라, 하우스 배치는 확정입니다.</p>}
    </div>
  </section>);
}
function PersonInput({p,setP,label}){
  const[sy,sm,sd]=p.solar.split("-").map(Number);
  const auto=solarToLunar(sy,sm,sd);
  const lunar=p.lunarEdit||auto;
  // 변경: 입력폼 카드에 전용 클래스를 부여해 380px 모바일에서도 한 열과 48px 입력 높이를 유지한다.
  return(
    <section className="lb-form-card" style={{background:T.panel,border:`1px solid ${T.line}`,borderRadius:14,padding:16,marginBottom:12,boxSizing:"border-box",maxWidth:"100%",boxShadow:"0 1px 4px rgba(76,85,120,0.08)"}}>
      <p style={{fontSize:12,letterSpacing:"0.15em",color:T.accent,margin:"0 0 10px",fontWeight:700}}>{label}</p>
      <div className="pi-grid lb-form-grid" style={{display:"grid",gridTemplateColumns:"minmax(0,1fr) minmax(0,1fr)",gap:10}}>
        <div style={{minWidth:0}}><label style={{fontSize:11.5,color:T.dim}}>이름</label>
          <input value={p.name} onChange={e=>setP({...p,name:e.target.value})} placeholder="선택" style={{minWidth:0,maxWidth:"100%"}}/></div>
        <div style={{minWidth:0}}><label style={{fontSize:11.5,color:T.dim}}>양력 생년월일</label>
          <input type="date" value={p.solar} min="1901-01-01" max="2049-12-31" onChange={e=>setP({...p,solar:e.target.value,lunarEdit:null})} style={{minWidth:0,maxWidth:"100%"}}/></div>
        <div style={{gridColumn:"1 / -1",minWidth:0}}>
          <label style={{fontSize:11.5,color:T.dim}}>출생시간 (KST)</label>
          <div style={{display:"flex",gap:6,margin:"4px 0 8px"}}>
            {[["exact","정확"],["window","대략"],["unknown","모름"]].map(([m,lb])=>{const on=(p.timeMode||"exact")===m;return(
              <button key={m} type="button" onClick={()=>setP({...p,timeMode:m,timeUnknown:m==="unknown"})} style={{flex:1,padding:"6px 0",fontSize:12,cursor:"pointer",borderRadius:8,fontFamily:"inherit",border:`1px solid ${on?T.accent:T.line}`,background:on?T.tint2:"transparent",color:on?T.accent:T.dim,fontWeight:on?700:400}}>{lb}</button>
            );})}
          </div>
          {(p.timeMode||"exact")==="exact"&&(
            <input type="time" value={p.time} onChange={e=>setP({...p,time:e.target.value})} style={{minWidth:0,maxWidth:"100%"}}/>
          )}
          {p.timeMode==="window"&&(
            <div>
              <div style={{display:"flex",flexWrap:"wrap",gap:4,marginBottom:8}}>
                {[["자시","23:00","01:00"],["축시","01:00","03:00"],["인시","03:00","05:00"],["묘시","05:00","07:00"],["진시","07:00","09:00"],["사시","09:00","11:00"],["오시","11:00","13:00"],["미시","13:00","15:00"],["신시","15:00","17:00"],["유시","17:00","19:00"],["술시","19:00","21:00"],["해시","21:00","23:00"]].map(([nm,a,b])=>{const on=p.winStart===a&&p.winEnd===b;return(
                  <button key={nm} type="button" onClick={()=>setP({...p,winStart:a,winEnd:b})} style={{padding:"4px 7px",fontSize:11,cursor:"pointer",borderRadius:6,fontFamily:"inherit",border:`1px solid ${on?T.accent:T.line}`,background:on?T.tint2:"transparent",color:on?T.accent:T.dim}}>{nm}<span style={{opacity:.55,fontSize:9.5}}> {a.slice(0,2)}–{b.slice(0,2)}</span></button>
                );})}
              </div>
              <div style={{display:"flex",alignItems:"center",gap:6}}>
                <input type="time" value={p.winStart||"17:00"} onChange={e=>setP({...p,winStart:e.target.value})} style={{flex:1}}/>
                <span style={{color:T.dim,fontSize:12}}>~</span>
                <input type="time" value={p.winEnd||"19:00"} onChange={e=>setP({...p,winEnd:e.target.value})} style={{flex:1}}/>
              </div>
              <p style={{fontSize:10.5,color:T.dim,margin:"6px 0 0"}}>대략적인 시간대를 고르거나 직접 범위를 넣으세요 — 상승궁 후보가 자동 계산됩니다.</p>
            </div>
          )}
          {p.timeMode==="unknown"&&(
            <p style={{fontSize:11.5,color:T.dim,margin:"2px 0 0"}}>상승궁·하우스 분석은 생략되고, 시간과 무관한 해석만 제공됩니다.</p>
          )}
        </div>
        <div style={{minWidth:0}}><label style={{fontSize:11.5,color:T.dim}}>출생지</label>
          <select value={p.city} onChange={e=>setP({...p,city:Number(e.target.value)})} style={{minWidth:0,maxWidth:"100%"}}>
            {REGIONS.map(rg=>(
              <optgroup key={rg} label={rg}>
                {CITIES.map((c,i)=>c[3]===rg?<option key={i} value={i}>{c[0]}</option>:null)}
              </optgroup>
            ))}
          </select></div>
        
      </div>
      <div style={{marginTop:10}}>
        <label style={{fontSize:11.5,color:T.dim}}>음력 {lunar?.isLeap?"윤달 ":""}{p.lunarEdit?"(수정됨)":"(자동)"}</label>
        <div style={{display:"flex",gap:6}}>
          {["year","month","day"].map((k,i)=>(
            <input key={k} type="number" aria-label={["음력 년","음력 월","음력 일"][i]} value={lunar&&Number.isFinite(lunar[k])?lunar[k]:""}
              onChange={e=>setP({...p,lunarEdit:{...(lunar||{}),[k]:Number(e.target.value)}})}/>
          ))}
        </div>
        {p.lunarEdit&&<button style={{background:"none",border:"none",color:T.accent,fontSize:11.5,cursor:"pointer",padding:"4px 0"}} onClick={()=>setP({...p,lunarEdit:null})}>자동값으로 되돌리기</button>}
      </div>
    </section>
  );
}

/* ═══ 저장소 키 & 안전 래퍼 ═══ */
const STORE_KEY="saved-readings-v1";
const storageOK=()=>typeof window!=="undefined"&&window.storage&&typeof window.storage.set==="function"&&typeof window.storage.get==="function";
async function storeGet(k){
  if(!storageOK())return{ok:false,reason:"unsupported",value:null};
  try{
    const r=await window.storage.get(k,false);
    return{ok:true,value:r&&r.value!=null?r.value:null};
  }catch(e){return{ok:false,reason:"missing",value:null,err:e?.message};}
}
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
async function storeSet(k,v){
  if(!storageOK())return{ok:false,reason:"unsupported"};
  let lastErr=null;
  for(let i=0;i<3;i++){
    try{
      const r=await window.storage.set(k,v,false);
      if(r&&r.value===v)return{ok:true};
      lastErr="저장 API가 값을 확인해 주지 않음";
    }catch(e){lastErr=e?.message||String(e);}
    await sleep(250*(i+1));
  }
  return{ok:false,reason:"error",err:lastErr};
}

export default function App(){
  const[coupleMode,setCoupleMode]=useState(false);
  const[pa,setPa]=useState({name:"",solar:"1991-02-16",time:"05:08",city:CITY_IDX("김해"),lunarEdit:null,timeUnknown:false,timeMode:"exact",winStart:"17:00",winEnd:"19:00",married:false,gender:"",job:""});
  const[pb,setPb]=useState({name:"",solar:"1991-02-16",time:"12:00",city:CITY_IDX("창원"),lunarEdit:null,timeUnknown:false,timeMode:"exact",winStart:"17:00",winEnd:"19:00",married:false,gender:"",job:""});
  const[baseYear,setBaseYear]=useState(2026);
  /* 화면 레벨 — "client"(내담자용) / "mid"(중급자용) / "pro"(상급자용)
     clientMode는 기존 12곳의 배선을 그대로 쓰기 위해 파생값으로 남긴다. */
  const[level,setLevel]=useState("pro");
  /* 상담 시트 — 상담 '중'에 보는 한 화면. 준비용 리포트와 별개의 뷰다 */
  const[sheetView,setSheetView]=useState(false);
  /* v77 상담 목적 선택은 유지, 상담 체크/메모는 인쇄용 체크리스트로 대체 */
  const[consultFocus,setConsultFocus]=useState("career");

  const clientMode=level==="client";
  const isPro=level==="pro";
  const isMid=level==="mid";
  /* 요약 보기 — 긴 반복 블록(연도 5개·하우스 12개)을 접어 스크롤을 줄인다 */
  const[compact,setCompact]=useState(true);
  const[advice,setAdvice]=useState(null);
  const[advErr,setAdvErr]=useState(null);
  const[loading,setLoading]=useState(false);
  const[fromCache,setFromCache]=useState(false);
  const[saved,setSaved]=useState([]);
  const[showSaved,setShowSaved]=useState(false);
  const[storeMsg,setStoreMsg]=useState(null);
  const[jobFit,setJobFit]=useState(null);
  const[jobFitErr,setJobFitErr]=useState(null);
  const[jobFitLoading,setJobFitLoading]=useState(false);

  useEffect(()=>{
    (async()=>{
      const r=await storeGet(STORE_KEY);
      if(r.ok&&r.value){try{setSaved(JSON.parse(r.value));}catch{}}
      if(!r.ok&&r.reason==="unsupported")setStoreMsg("⚠ 이 실행 환경은 영구 저장 API(window.storage)를 지원하지 않는다 — Claude 아티팩트로 열어야 저장이 동작한다. 지금은 임시 세션 저장만 가능하다.");
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  },[]);

  async function persist(list){
    setSaved(list);
    return await storeSet(STORE_KEY,JSON.stringify(list));
  }
  async function saveCurrent(){
    setStoreMsg("저장 중…");
    const label=coupleMode?`${pa.name||"A"} × ${pb.name||"B"}`:(pa.name||pa.solar);
    const item={id:Date.now(),at:new Date().toISOString().slice(0,16).replace("T"," "),label,pa,pb,coupleMode,baseYear};
    const nextList=[item,...saved].slice(0,50);
    const r=await persist(nextList);
    if(r.ok){setStoreMsg(`저장됨 ✓ — 아래 '저장된 리딩(${nextList.length})'에서 언제든 다시 열 수 있다.`);setShowSaved(true);}
    else if(r.reason==="unsupported")setStoreMsg("⚠ 이 환경은 영구 저장 API를 지원하지 않는다 — Claude 아티팩트(claude.ai)에서 열어야 저장이 유지된다. 목록엔 이번 세션 동안만 임시로 남는다.");
    else setStoreMsg(`저장 실패 — ${r.err||"원인 불명의 오류"}. 목록엔 임시 반영됐다. 잠시 후 '현재 리딩 저장'을 다시 눌러 달라.`);
  }
  function loadItem(it){
    setPa(it.pa);setPb(it.pb);setCoupleMode(it.coupleMode);setBaseYear(it.baseYear);
    setAdvice(null);setAdvErr(null);setShowSaved(false);setStoreMsg(null);setFromCache(false);
  }
  async function delItem(id){
    const r=await persist(saved.filter(s=>s.id!==id));
    if(!r.ok)setStoreMsg(r.reason==="unsupported"?"⚠ 영구 저장 미지원 환경 — 삭제는 이번 세션에만 반영된다.":`삭제 동기화 실패 — ${r.err||"원인 불명"}. 목록엔 반영됐으나 다시 열면 되살아날 수 있다.`);
  }

  const Araw=useMemo(()=>compute(pa.solar,pa.time,pa.city,pa.lunarEdit,baseYear,pa.timeUnknown,pa.timeMode,pa.winStart,pa.winEnd),[pa,baseYear]);
  const B=useMemo(()=>coupleMode?compute(pb.solar,pb.time,pb.city,pb.lunarEdit,baseYear,pb.timeUnknown,pb.timeMode,pb.winStart,pb.winEnd):null,[pb,baseYear,coupleMode]);
  // v87: 별도 진단 패널. 기존 분석 결과는 정밀 엔진 연결 전까지 근사 계산값이다.
  const [swissCheck,setSwissCheck]=useState({state:"idle",data:null,error:""});
  const swissJd=Araw?.astro?.J0;
  useEffect(()=>{
    if(!Number.isFinite(swissJd)){setSwissCheck({state:"idle",data:null,error:""});return;}
    const controller=new AbortController();
    setSwissCheck({state:"loading",data:null,error:""});
    getSwissPositions(swissJd,{signal:controller.signal})
      .then(data=>{if(!controller.signal.aborted)setSwissCheck({state:"ok",data,error:""});})
      .catch(err=>{if(!controller.signal.aborted)setSwissCheck({state:"error",data:null,error:err.message||String(err)});});
    return()=>controller.abort();
  },[swissJd]);
  // v92: 검증된 Swiss 출생 행성값을 본문 전체가 참조하는 A.astro에 통합한다.
  // 로딩/오류 시 기존 근사 데이터는 유지하지만 아래 화면에 그 출처를 명시한다.
  // ASC·MC는 아래 Swiss 하우스 응답이 출생 JD·좌표와 일치할 때만 교체한다.
  const swissMatched = swissCheck.state==="ok" && Number.isFinite(swissJd)
    && Math.abs((swissCheck.data?.jdUt??NaN)-swissJd)<=1e-6;
  // v92 4차: 출생시간 확정 차트에 대해서만 Swiss ASC·MC를 요청한다.
  // 요청 식별값에 JD와 위도·경도를 모두 사용하여 이전 출생지의 응답을 차단한다.
  const houseJd=Araw?.astro&&!Araw.astro.approx?Araw.astro.J0:null;
  const houseLat=Araw?.astro&&!Araw.astro.approx?Araw.astro.geoLat:null;
  const houseLon=Araw?.astro&&!Araw.astro.approx?Araw.astro.geoLon:null;
  const [swissHouse,setSwissHouse]=useState({state:"idle",data:null,error:""});
  useEffect(()=>{
    if(!Number.isFinite(houseJd)||!Number.isFinite(houseLat)||!Number.isFinite(houseLon)){
      setSwissHouse({state:"idle",data:null,error:""});return;
    }
    const ctrl=new AbortController();
    let timer=0;
    const attempt=()=>{
      setSwissHouse({state:"loading",data:null,error:""});
      getSwissHouses(houseJd,houseLat,houseLon,{signal:ctrl.signal})
        .then(data=>{if(!ctrl.signal.aborted)setSwissHouse({state:"ok",data,error:""});})
        .catch(err=>{
          if(ctrl.signal.aborted)return;
          const msg=err.message||String(err);
          if(/busy|429/i.test(msg)){timer=setTimeout(attempt,700);return;}
          setSwissHouse({state:"error",data:null,error:msg});
        });
    };
    attempt();
    return()=>{ctrl.abort();clearTimeout(timer);};
  },[houseJd,houseLat,houseLon]);
  const swissHouseMatched=swissHouse.state==="ok"&&Number.isFinite(houseJd)
    &&Math.abs((swissHouse.data?.jdUt??NaN)-houseJd)<=1e-6
    &&Math.abs((swissHouse.data?.latitude??NaN)-houseLat)<=1e-5
    &&Math.abs((swissHouse.data?.longitude??NaN)-houseLon)<=1e-5;
  const A=useMemo(()=>{
    if(!Araw)return Araw;
    const withPlanets=swissMatched?mergeSwissNatal(Araw,swissCheck.data):Araw;
    return swissHouseMatched?mergeSwissHouses(withPlanets,swissHouse.data):withPlanets;
  },[Araw,swissMatched,swissCheck.data,swissHouseMatched,swissHouse.data]);
  // v89: 월별 Swiss 트랜짓을 5년치 일괄 로딩한다. 실패할 때 근사 트랜짓을 대체 표시하지 않는다.
  const [swissYears,setSwissYears]=useState({state:"idle",data:null,error:""});
  useEffect(()=>{
    if(!Number.isFinite(swissJd)||swissCheck.state!=="ok"){
      setSwissYears({state:"idle",data:null,error:""});return;
    }
    const ctrl=new AbortController();
    setSwissYears({state:"loading",data:null,error:""});
    getSwissTransitYears(baseYear,{signal:ctrl.signal})
      .then(data=>{if(!ctrl.signal.aborted)setSwissYears({state:"ok",data,error:""});})
      .catch(err=>{if(!ctrl.signal.aborted)setSwissYears({state:"error",data:null,error:err.message||String(err)});});
    return()=>ctrl.abort();
  },[swissJd,swissCheck.state,baseYear]);
  const swissYearRows=useMemo(()=>{
    if(!A)return [];
    // Transit points here use Swiss natal Sun/Moon/Venus; ASC/MC are deliberately excluded.
    const natal=swissMatched?swissCheck.data?.bodies:null;
    const points=natal?{sun:natal.Sun.longitude,moon:natal.Moon.longitude,ven:natal.Venus.longitude}:null;
    return A.years.map((yr,i)=>{
      const found=new Map();
      if(points&&swissYears.state==="ok"&&swissYears.data?.years[i]?.year===yr.y){
        for(const sample of swissYears.data.years[i].months){
          for(const planet of TR_PLANETS){
            const tl=sample.bodies[planet].longitude;
            for(const [pt,nl] of Object.entries(points)){
              let d=Math.abs(tl-nl)%360;if(d>180)d=360-d;
              for(const[ang,nm,orb,tone]of ASPECTS){
                const o=Math.abs(d-ang);
                if(o<=orb){
                  const key=`${planet}|${pt}|${nm}`;
                  if(!found.has(key)||o<found.get(key).orb)found.set(key,{planet,pt,aspect:nm,tone,orb:o,m:sample.month});
                }
              }
            }
          }
        }
      }
      const transits=[...found.values()].sort((a,b)=>a.orb-b.orb);
      return {...yr,transits,transit:transits[0]||null};
    });
  },[A,swissCheck,swissYears]);
  // v88 1단계: Swiss 출생 시점의 천체 위치만 독립적으로 구성한다.
  // 기존 상담 본문·해년수·솔라리턴의 근사 계산과 섞어서 사용하지 않는다.
  const swissNatal=useMemo(()=>{
    if(swissCheck.state!=="ok")return null;
    const bodies=SWISS_BODIES.map(body=>({body,...swissCheck.data.bodies[body]}));
    const aspects=[];
    for(let i=0;i<bodies.length;i++)for(let j=i+1;j<bodies.length;j++){
      const left=bodies[i],right=bodies[j];
      const distance=angularDifference(left.longitude,right.longitude);
      for(const[degree,label,orb]of [[0,"합",5],[180,"대립",5],[90,"스퀘어",5],[120,"트라인",4],[60,"섹스타일",3]]){
        const delta=Math.abs(distance-degree);
        if(delta<=orb){aspects.push({left:left.body,right:right.body,label,orb:delta});break;}
      }
    }
    aspects.sort((a,b)=>a.orb-b.orb);
    return{bodies,aspects};
  },[swissCheck]);


  const adviceKey=()=>`advice:${pa.solar}:${pa.timeUnknown?"x":pa.time}:${pa.city}:${baseYear}:${pa.married?"m":"s"}:${pa.gender||"x"}`;
  async function makeAdvice(force){
    if(!A||!A.years[0])return;
    setLoading(true);setAdvice(null);setAdvErr(null);setFromCache(false);
    if(force!==true){
      const hit=await storeGet(adviceKey());
      if(hit.ok&&hit.value){setAdvice(hit.value);setFromCache(true);setLoading(false);return;}
    }
    const yr=A.years[0];
    const gC=GROUP_OF[A.cons.main===22?0:A.cons.main],gU=GROUP_OF[A.unc.main===22?0:A.unc.main];
    const[mtype,mech,mres]=MATRIX[gC][gU];
    const aspLine=asp.slice(0,4).map(r=>{const tx=aspectText(r);return`${KR10[r.a]}${ASPECT_SYM[r.nm]}${KR10[r.b]}(${tx?tx.theme:""}, 오차${r.o.toFixed(1)}°)`;}).join(", ")||"주요 각도 없음";
    let digLine="해당 없음",chainLine="출생시간 미상으로 생략",astroLine="출생시간 미입력";
    if(A.astro){
      const rows=[["Sun",A.astro.sun],["Moon",A.astro.moon],...Object.entries(A.astro.planets).filter(([p])=>DIGNITY[p]).map(([p,v])=>[p,v.lon])];
      const sp=rows.map(([p,l])=>({p,s:signOf(l),dg:dignity(p,signOf(l))})).filter(r=>r.dg);
      if(sp.length)digLine=sp.map(r=>`${KR10[r.p]} ${SIGNS[r.s]}[${DIG_LABEL[r.dg]}]`).join(", ");
      if(!A.astro.approx)chainLine=CHAIN_TARGETS.map(([hn,label])=>{const c=chainOf(A.astro,hn);return`${hn}H(${label})→${KR10[c.rp]}→${c.rh}H(${HOUSE_SHORT[c.rh-1]})`;}).join(", ");
      astroLine=`태양 ${SIGNS[signOf(A.astro.sun)]}${A.astro.approx?" (출생시간 미상 — 정오 기준, 달·상승 참고용)":`, 달 ${SIGNS[signOf(A.astro.moon)]}, 상승 ${SIGNS[signOf(A.astro.asc)]}, MC ${SIGNS[signOf(A.astro.mc)]}`}. 올해 트랜짓: ${transitLine(yr.transit,card(yr.main)[0],workCtx(pa.job,baseYear-A.sy))}`;
    }
    const prompt=`너는 수비학·타로·점성학 통합 해석가다. 아래 원자료만 근거로 답하고, 원자료에 없는 사실은 지어내지 마라.
[프로필] ${baseYear-A.sy}세 기준, ${pa.married?"기혼":"미혼"}${pa.job?`, 현재 직업: ${pa.job}`:", 직업 미입력(무직·비고용 상태로 가정 — 직장 전제의 사건·조언 금지)"}
[3층] 의식 ${A.cons.main} ${card(A.cons.main)[0]}(${GROUP_NAMES[gC]} 계열·${ELEMS[cardElem(A.cons.main)]}) / 전의식 ${A.pre.main} ${card(A.pre.main)[0]}(${ELEMS[cardElem(A.pre.main)]}) / 무의식 ${A.unc.main} ${card(A.unc.main)[0]}(${GROUP_NAMES[gU]} 계열·${ELEMS[cardElem(A.unc.main)]})
[의식×무의식 ${mtype}] ${mech} → ${mres}
[${baseYear}년 해년의수] ${yr.main} ${card(yr.main)[0]}
[올해 절대 금지] ${YEAR_FORBID[yr.main===22?0:yr.main]}
[점성학] ${astroLine}
[핵심 애스펙트] ${aspLine}
[품위] ${digLine}
[지배성 체인] ${chainLine}
[요청] ① ${baseYear}년 가장 강력하게 일어날 사건의 방향 한 가지 ② 그 사건 앞에서 이 사람 특유의 ${mtype} 패턴이 어떻게 작동할지 ③ 그에 맞춘 구체적 행동 지침 한 가지. 각 판단의 근거를 위 원자료와 직접 연결해 쓰되, 본문에는 점성학 전문용어(행성명·각도명)를 노출하지 말고 사건과 행동 중심으로 쓰라. 문체 "-이다/-한다", 7~9문장, 본문만.`;
    try{
      const res=await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:1000,messages:[{role:"user",content:prompt}]}),
      });
      if(!res.ok)throw new Error(`HTTP ${res.status}`);
      const data=await res.json();
      const text=(data.content||[]).filter(b=>b.type==="text").map(b=>b.text).join("\n").trim();
      if(!text)throw new Error("빈 응답");
      setAdvice(text);
      await storeSet(adviceKey(),text);
    }catch(e){
      setAdvErr(`AI 연결 실패(${e.message}) — 규칙 기반 해석으로 대체함`);
      setAdvice(`${baseYear}년은 ${card(yr.main)[0]}(${yr.main})의 해이다. ${yr.transit?transitLine(yr.transit,card(yr.main)[0],workCtx(pa.job,baseYear-A.sy)):""} 의식(${card(A.cons.main)[0]})×무의식(${card(A.unc.main)[0]})은 ${mtype} 구조다 — ${mres} 이 패턴을 전제로, 큰 결정은 무의식의 욕구와 같은 방향일 때 실행하는 것이 맞다.`);
    }finally{setLoading(false);}
  }
const jobFitKey=()=>`jobfit:${pa.solar}:${pa.timeUnknown?"x":pa.time}:${pa.city}:${(pa.job||"").trim()}`;
  async function makeJobFit(force){
    if(!A?.astro||!(pa.job||"").trim())return;
    setJobFitLoading(true);setJobFit(null);setJobFitErr(null);
    if(force!==true){
      const hit=await storeGet(jobFitKey());
      if(hit.ok&&hit.value){setJobFit(hit.value);setJobFitLoading(false);return;}
    }
    const a=A.astro;
    const eb=elementBalance(a);
    const meS=signOf(a.planets.Mercury.lon);
    const gC=GROUP_OF[A.cons.main===22?0:A.cons.main],gU=GROUP_OF[A.unc.main===22?0:A.unc.main];
    const[mtype,,mres]=MATRIX[gC][gU];
    let coordLines;
    if(!a.approx){
      const mcS=signOf(a.mc);
      const c10=chainOf(a,10);
      const satH=wholeHouse(a.planets.Saturn.lon,a.asc);
      const h6=(signOf(a.asc)+5)%12;
      coordLines=`[적성 분야] MC ${SIGNS[mcS]} — ${CAREER[mcS]} / 구체 후보: ${CAREER_JOBS[mcS].join(", ")}
[일의 형태] 커리어 방 주인이 ${c10.rh}하우스 — '${WORK_CHANNEL[c10.rh-1]}' 형태로 일할 때 성과와 돈이 붙는 구조
[대기만성 구간] 토성 ${satH}하우스(${HOUSE_SHORT[satH-1]}) — 이 영역과 겹치는 일은 성과가 늦게 온다
[일상·과로 신호] 6하우스 ${SIGNS[h6]} — ${BODY[h6]} 계통이 먼저 반응`;
    }else{
      coordLines=`[출생시간 미상] MC·하우스 없이 태양·수성·원소 균형만으로 제한적 판단 — 결론의 확신도를 낮추고 그 사실을 명시하라
[태양] ${SIGNS[signOf(a.sun)]} — ${SIGN_TEXT[signOf(a.sun)]}`;
    }
    const prompt=`너는 수비학·타로·점성학 통합 직업 상담가다. 아래 원자료만 근거로 답하고, 원자료에 없는 사실은 지어내지 마라.
[현재 직업] ${pa.job.trim()}
${coordLines}
[학습·소통 무기] 수성 ${SIGNS[meS]} — ${SIGN_MODE[meS]} 방식으로 일하고 배울 때 강함
[원소 균형] 강한 기운 ${ELEMS[eb.hi]}(${ELEM_STRONG[eb.hi].split(".")[0]}) / 부족한 기운 ${ELEMS[eb.lo]}(${ELEM_LACK[eb.lo].split("—")[0].trim()})
[3층 성격] 의식 ${card(A.cons.main)[0]} / 무의식 ${card(A.unc.main)[0]} — ${mtype} 구조: ${mres.split("—")[0].trim()}
[요청] ① 첫 문장에서 "이 직업은 맞는 방향이다 / 부분적으로 맞는다 / 맞지 않는 방향이다" 중 하나로 결론부터 명시하라 ② 그 판단의 이유를 위 원자료의 좌표(적성 분야·일의 형태·성격 구조·원소)와 직접 연결해 2~3가지로 설명하라 — 맞으면 어떤 좌표와 겹치는지, 안 맞으면 어떤 좌표와 어긋나는지를 구체적으로 ③ 맞지 않거나 부분적인 경우, 직업명을 바꾸지 않고 '일하는 형태'만 조정해 맞출 수 있는 현실적 방법 한 가지를 제시하라. 본문에는 점성학 전문용어(행성명·하우스 번호·각도명)를 노출하지 말고 일과 성향의 언어로 쓰라. 문체 "-이다/-한다", 6~8문장, 본문만.`;
    try{
      const res=await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:1000,messages:[{role:"user",content:prompt}]}),
      });
      if(!res.ok)throw new Error(`HTTP ${res.status}`);
      const data=await res.json();
      const text=(data.content||[]).filter(b=>b.type==="text").map(b=>b.text).join("\n").trim();
      if(!text)throw new Error("빈 응답");
      setJobFit(text);
      await storeSet(jobFitKey(),text);
    }catch(e){
      setJobFitErr(`AI 연결 실패(${e.message}) — 수동 대조용 좌표로 대체함`);
      setJobFit(a.approx
        ?`출생시간 미상이라 자동 대조가 제한된다. 태양 ${SIGNS[signOf(a.sun)]}의 방식(${SIGN_MODE[signOf(a.sun)]})과 '${pa.job.trim()}'의 일하는 방식이 겹치는지를 기준으로 보면 된다.`
        :`수동 대조 좌표 — '${pa.job.trim()}'이 ① 적성 분야(${CAREER[signOf(a.mc)]})와 겹치는가 ② '${WORK_CHANNEL[chainOf(a,10).rh-1]}' 형태로 굴릴 수 있는가, 이 두 가지가 모두 예이면 맞는 방향, 하나만 예이면 부분 일치(형태 조정 필요), 둘 다 아니면 어긋난 방향이다.`);
    }finally{setJobFitLoading(false);}
  }
  /* 3층 + 점성학 융합 */
  // v81: 상담 문장에서 반복되는 도입부를 제거하고 실제로 읽기 쉬운 문장으로 표시한다.
  const layerPlain=(value)=>String(value||"")
    .replaceAll("구현된다", "드러난다")
    .replaceAll("수동성이 공존한다", "생각이 많아 행동을 미루는 모습도 나타날 수 있다")
    .replaceAll("탁월하다", "돋보인다")
    .replaceAll("이면이 공존한다", "모습도 나타날 수 있다")
    .replaceAll("공존한다", "함께 나타날 수 있다")
    .replaceAll("지닌다", "가지고 있다");
  // v81: 긴 문장에서 읽을 부분만 색을 달리한다. 문장을 변경하거나 데이터 값을 바꾸지 않는다.
  const layerEmphasis=(value)=>{
    const keys=["직관","통찰","실행력","책임감","독립성","공감","분석력","창의","안정","변화","성취","조화","선택","인내","집중력","자유","두려움","불안","갈등","고립","회피","집착","완벽주의","과신","실망","소진","부담"];
    const pattern=new RegExp(`(${keys.join("|")})`,"g");
    return layerPlain(value).split(pattern).map((part,i)=>{
      if(!keys.includes(part))return part;
      const caution=["두려움","불안","갈등","고립","회피","집착","완벽주의","과신","실망","소진","부담"].includes(part);
      return <strong key={i} style={{fontWeight:750,color:caution?"#A65350":"#426D91"}}>{part}</strong>;
    });
  };
  /* ═══ 기본 좌표 — 상담 노트 첫 줄에 적는 것: 수비학 3층 + 태양궁 ═══ */
  /* ═══ 빅3 — 수비학 3층과 짝을 이루는 점성술 3축 ═══ */
  /* ═══ 판독 순서 — 상승점을 기준으로 한 상담사 체크리스트 ═══ */
  const ReadOrder=({P})=>{
    const a=P.astro; if(!a||a.approx)return null;
    const ascS=signOf(a.asc), cr=RULER[ascS];
    const crL=cr==="Sun"?a.sun:cr==="Moon"?a.moon:a.planets[cr].lon;
    const crH=wholeHouse(crL,a.asc), crS=signOf(crL);
    const crAsp=natalAspects(a).filter(r=>r.a===cr||r.b===cr).sort((x,y)=>x.o-y.o).slice(0,3);
    // v83: 계산된 어스펙트를 상담용 언어로 정리하되 원래 각도·오차는 유지한다.
    const rulerAspectView=crAsp.length ? (
      <div style={{display:"flex",flexDirection:"column",gap:10}}>
        {crAsp.map((r,i)=>{
          const other=r.a===cr?r.b:r.a;
          const info=aspectText(r);
          const meaning=info?.body || `${KR10[other]}의 상징과 차트 룰러의 성향을 함께 검토한다.`;
          const sentences=meaning.split(/(?<=[.!?。])\s+/).filter(Boolean);
          const concise=sentences.slice(0,2).join(" ");
          const isHard=r.tone==="h" || r.tone==="q";
          const isSoft=r.tone==="s";
          const heading=isHard?"조정할 부분":isSoft?"도움이 되는 부분":"함께 나타나는 성향";
          return <div key={`${r.a}-${r.b}-${i}`} style={{paddingBottom:i===crAsp.length-1?0:9,borderBottom:i===crAsp.length-1?"none":`1px solid ${T.line}`}}>
            <div style={{fontSize:15,fontWeight:800,color:T.ink,marginBottom:3}}>{KR10[cr]} × {KR10[other]} · {r.nm} <span style={{fontWeight:500,fontSize:12,color:T.dim}}>(오차 {r.o.toFixed(1)}°)</span></div>
            <div style={{fontSize:13,fontWeight:750,color:isHard?"#A65350":"#426D91",marginBottom:3}}>{heading}</div>
            <div style={{fontSize:14.5,lineHeight:1.65,color:T.ink}}>{concise}</div>
          </div>;
        })}
        <div style={{fontSize:13.5,lineHeight:1.6,color:T.dim}}>상담 핵심 · 위 성향이 실제 결정·행동에 나타나는지, 도움이 되는 조건과 어려운 상황을 구분해 확인한다. 선택된 최대 3개 각도에 대한 해석이다.</div>
      </div>
    ) : "선정한 주요 각도가 없다. 갈등이나 강점이 없다는 뜻은 아니며, 다른 차트 요소와 실제 경험을 함께 확인한다.";
    // v83: 세 별자리 원소의 개수만으로 성향의 일치·갈등을 단정하지 않는다.
    const sunS=signOf(a.sun), moonS=signOf(a.moon);
    const bigThreeView=(
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        <div><strong style={{color:"#426D91"}}>남에게 보이는 모습 · 상승궁 {SIGNS[ascS]}</strong><div>{ASC_TYPE[ascS].reflex}</div></div>
        <div><strong style={{color:"#426D91"}}>내가 중요하게 여기는 것 · 태양 {SIGNS[sunS]}</strong><div>{SIGN_MODE[sunS]} 방식을 중요하게 여기는 것으로 해석한다.</div></div>
        <div><strong style={{color:"#426D91"}}>마음이 편해지는 방식 · 달 {SIGNS[moonS]}</strong><div>{PS84.Moon[moonS].op}</div></div>
        <div style={{background:T.tint,borderRadius:8,padding:"9px 11px",fontSize:14.5,lineHeight:1.6}}><strong>세 가지를 연결하면</strong> · 처음 보이는 태도, 스스로 중요하게 생각하는 방식, 감정을 다루는 방식이 각각 다르게 나타날 수 있다. 가까운 관계와 일하는 상황에서 어느 모습이 두드러지는지 비교한다.</div>
      </div>
    );
    const steps=[
      ["상승점 사인",`${SIGNS[ascS]} — ${ASC_TYPE[ascS].lens}`],
      ["차트 룰러의 하우스",`${KR10[cr]} → ${crH}하우스(${HOUSE_SHORT[crH-1]}) — 인생의 주 무대. 이 단계가 정보량이 가장 많다`],
      ["차트 룰러의 사인",`${SIGNS[crS]} — ${PS84[cr]?PS84[cr][crS].op:"그 무대를 다루는 방식"}`],
      ["나를 움직이는 힘과 걸림돌",rulerAspectView],
      ["상승점에 붙은 행성",(()=>{const c=BODY10.filter(k=>{const L=k==="Sun"?a.sun:k==="Moon"?a.moon:a.planets[k].lon;
        return ((L-a.asc)%360+360)%360<=10||((a.asc-L)%360+360)%360<=5;});
        return c.length?`${c.map(k=>KR10[k]).join("·")} — 첫인상을 덮어쓴다`:"없음 — 상승점 사인이 그대로 첫인상이 된다";})()],
      ["겉모습과 속마음의 차이",bigThreeView],
      ["하강점 상황",`${ASC_TYPE[ascS].dscSign}자리 — ${ASC_TYPE[ascS].dsc}`],
    ];
    /* v77: 기존 계산 근거는 그대로 두고 상담사에게 필요한 질문 축만 덧붙인다. */
    const readGuides=[
      ["어떻게 보이는가", "처음 만난 사람이 묘사하는 인상과 낯선 상황의 자동 반응을 확인한다."],
      ["삶의 주제는 어디인가", "이 하우스의 주제가 실제 생활에서 얼마나 중요한지 확인한다. 정해진 운명으로 단정하지 않는다."],
      ["그 주제를 어떤 방식으로 다루는가", "차트 룰러의 사인을 앞 단계의 하우스와 연결해 한 문장으로 정리한다."],
      ["어떤 행동이 편하고 무엇이 부담인가", "도움이 되는 부분과 조정할 부분을 실제 행동에 연결해 확인한다. 각도만으로 사건이나 성격을 확정하지 않는다."],
      ["첫인상을 바꾸는 요소가 있는가", "상승점 가까이 있는 행성의 의미를 함께 읽되, 실제 인상과는 구분한다."],
      ["남이 보는 나·내가 원하는 나·마음의 반응", "세 모습이 다른 상황에서 어떻게 나타나는지 확인한다. 앞 단계의 별자리 설명을 그대로 반복하지 않는다."],
      ["관계에서 어떤 균형을 찾는가", "하강점의 상징과 실제 관계 경험을 나란히 놓고, 반복되는 상호작용을 확인한다."],
    ];
    return(
      <details open data-card style={{background:"#fff",border:`1px solid ${T.line}`,borderRadius:14,padding:"14px 14px",marginBottom:12,textAlign:"left",width:"100%",boxSizing:"border-box"}}>
        <summary style={{cursor:"pointer",fontSize:19,fontWeight:800,color:T.accent,listStyle:"none",textAlign:"left",lineHeight:1.45,paddingBottom:6}}>
          상담 전 핵심 판독 — 7단계
          <span style={{fontSize:13,fontWeight:500,color:T.dim,marginLeft:9}}>접기 · 펼치기</span>
        </summary>
        <p style={{margin:"6px 0 12px",fontSize:14,lineHeight:1.6,color:T.dim,textAlign:"left",maxWidth:"none"}}>
          7단계는 상담 준비를 위한 <b>판독 순서</b>다. 아래 결과는 상징적 해석이며 실제 경험과 함께 확인한다. 출생시각이 불확실하면 상승점·하우스 기반 결론은 보류한다.
        </p>
        <div style={{display:"flex",flexDirection:"column",gap:9,textAlign:"left"}}>
          {steps.map(([k,v],i)=>(
            <section key={k} style={{padding:"12px 13px",border:`1px solid ${T.line}`,borderLeft:`3px solid ${T.accent}`,background:"#fff",borderRadius:10,textAlign:"left",boxSizing:"border-box"}}>
              <div style={{display:"flex",gap:9,alignItems:"flex-start",textAlign:"left",marginBottom:8}}>
                <span style={{display:"inline-flex",alignItems:"center",justifyContent:"center",minWidth:32,height:32,padding:"0 5px",background:T.tint,borderRadius:7,color:T.accent,fontWeight:800,fontSize:15,boxSizing:"border-box"}}>{i+1}</span>
                <div style={{flex:1,minWidth:0,textAlign:"left"}}>
                  <div style={{fontSize:16,fontWeight:800,lineHeight:1.4,color:T.ink,textAlign:"left"}}>{k}</div>
                  <div style={{fontSize:13.5,color:T.accent,lineHeight:1.45,marginTop:2,textAlign:"left"}}>{readGuides[i][0]}</div>
                </div>
              </div>
              <div style={{borderTop:`1px solid ${T.line}`,paddingTop:9,textAlign:"left"}}>
                <div style={{fontSize:12,fontWeight:800,letterSpacing:"0.03em",color:T.accent,marginBottom:4,textAlign:"left"}}>차트 판독 결과</div>
                <p style={{margin:"0 0 9px",fontSize:15,lineHeight:1.55,color:T.ink,textAlign:"left",overflowWrap:"anywhere"}}>{v}</p>
                <div style={{background:T.tint,borderRadius:8,padding:"9px 11px",textAlign:"left"}}>
                  <div style={{fontSize:12,fontWeight:800,color:T.accent,marginBottom:4,textAlign:"left"}}>상담에서 확인할 내용</div>
                  <p style={{margin:0,fontSize:14.5,lineHeight:1.55,color:T.ink,textAlign:"left"}}>{readGuides[i][1]}</p>
                </div>
              </div>
            </section>
          ))}
        </div>
        <div style={{marginTop:14,padding:"12px 5px",borderTop:`1px solid ${T.line}`,textAlign:"left"}}>
          <div style={{fontSize:15,fontWeight:800,color:T.ink,marginBottom:9,textAlign:"left"}}>상담사 참고 메모</div>
          <p style={{margin:"0 0 12px",fontSize:14,lineHeight:1.85,color:T.dim,textAlign:"left"}}>첫인상과 자동 반응은 내담자의 실제 경험과 대조하는 출발점이다. 해석이 다르면 표현의 적합성·상황 차이·출생 정보의 정확성을 함께 검토한다.</p>
          <p style={{margin:"0 0 8px",fontSize:14,lineHeight:1.85,color:T.ink,textAlign:"left"}}><b style={{color:T.bad}}>피할 말</b> · “상승점은 가면이고 진짜는 태양이다” — 내담자가 자기 행동을 부정하게 된다.</p>
          <p style={{margin:0,fontSize:14,lineHeight:1.85,color:T.ink,textAlign:"left"}}><b style={{color:T.good}}>권장 표현</b> · “상승점은 세상과 만나는 문입니다. 가짜가 아니라, 모든 것이 이 문을 통과합니다.”</p>
        </div>
      </details>
    );
  };

  /* ═══ 상담 시트 — 상담 '중'에 보는 한 화면. 준비용 리포트와 다른 물건이다 ═══ */
  /* 조심해서 말할 단어를 빨갛게 — 내담자용 화면에서는 표시하지 않는다 */
  const Careful=({t})=>{
    if(!t||typeof t!=="string")return t||null;
    if(clientMode)return t;   /* 내담자에게 보여주는 화면에는 표시하지 않는다 */
    /* 오탐 구간을 먼저 확보해 두고, 그 안에 든 매치는 건너뛴다 */
    const skip=[];let sm;
    CAREFUL_SKIP_RE.lastIndex=0;
    while((sm=CAREFUL_SKIP_RE.exec(t))!==null)skip.push([sm.index,sm.index+sm[0].length]);
    const inSkip=(a,b)=>skip.some(([x,y])=>a>=x&&b<=y);
    const out=[];let last=0,m;
    CAREFUL_RE.lastIndex=0;
    while((m=CAREFUL_RE.exec(t))!==null){
      const a=m.index,b=m.index+m[0].length;
      if(inSkip(a,b))continue;
      if(a>last)out.push(t.slice(last,a));
      out.push(<b key={a} style={{color:"#C0392B"}}>{m[0]}</b>);
      last=b;
    }
    if(last<t.length)out.push(t.slice(last));
    return <>{out}</>;
  };

  const ConsultSheet=({P,year,currentJob})=>{
    const a=P.astro;
    const yr=P.years.find(y=>y.y===year)||P.years[0];
    const ascS=a&&!a.approx?signOf(a.asc):null;
    const cr=ascS!=null?RULER[ascS]:null;
    const crL=cr?(cr==="Sun"?a.sun:cr==="Moon"?a.moon:a.planets[cr].lon):null;
    const crH=cr?wholeHouse(crL,a.asc):null;
    /* 해년의수 5년 — 카드 번호·이름·키워드·원소만. 흐름 판정은 준비용 리포트에서 본다 */
    const yrs=P.years.slice(0,5);
    /* v75: 상승·룰러·해년의수는 바로 아래 기존 블록에 있으므로 다시 나열하지 않는다. */
    const gCons=GROUP_OF[P.cons.main===22?0:P.cons.main];
    const gUnc=GROUP_OF[P.unc.main===22?0:P.unc.main];
    const [matrixType,matrixMechanism,matrixAdvice]=MATRIX[gCons][gUnc];
    /* v76: 직업 상담에서 우선 확인할 정보. 점수는 상대적인 내부 분류치다. */
    const careerModes=a?workModes(P):[];
    const careerTop=careerModes.slice(0,2);
    const mcSign=a&&!a.approx?signOf(a.mc):null;
    const careerChain=a&&!a.approx?chainOf(a,10):null;

    const Line=({lb,children,c})=>(
      <p style={{margin:"0 0 6px",fontSize:12.5,lineHeight:1.7,display:"flex",gap:7}}>
        <b style={{color:c||T.accent,minWidth:52,flexShrink:0,fontSize:11}}>{lb}</b>
        <span style={{color:T.ink}}>{children}</span>
      </p>
    );
    return(
      <div>
        <div data-card style={{background:"#fff",border:`1.5px solid ${T.accent}`,borderRadius:12,padding:"12px 15px",marginBottom:10}}>
          <p style={{margin:"0 0 8px",fontSize:12.5,fontWeight:700,color:T.accent}}>상담 목적에 맞춘 핵심 정보</p>
          <div style={{display:"flex",gap:7,flexWrap:"wrap"}}>
            {[["career","직업 상담 우선"],["general","일반 상담"]].map(([v,label])=>(
              <button type="button" key={v} onClick={()=>setConsultFocus(v)} style={{cursor:"pointer",border:`1px solid ${consultFocus===v?T.accent:T.line}`,background:consultFocus===v?T.tint:"#fff",color:consultFocus===v?T.accent:T.dim,borderRadius:7,padding:"7px 10px",fontWeight:consultFocus===v?700:400,fontSize:12}}>{label}{consultFocus===v?" ✓":""}</button>
            ))}
          </div>
          <p style={{margin:"8px 0 0",fontSize:11,color:T.dim}}>{consultFocus==="career"?"직업·업무 방식 → 성격의 연결 → 차트 근거 → 현실 조건 순으로 안내한다.":"기존 성격·행성·연도 정보를 먼저 보고, 직업 자료는 별도로 확인한다."}</p>
        </div>
        {consultFocus==="career"&&(
          <div data-card style={{background:T.panel,border:`1.5px solid ${T.accent}`,borderRadius:12,padding:"14px 15px",marginBottom:10}}>
            <p style={{margin:"0 0 9px",fontSize:13,fontWeight:800,color:T.accent}}>직업 상담 핵심 — 먼저 전달할 내용</p>
            <Line lb="현재 직업">{currentJob?.trim()||"미입력"} <span style={{color:T.dim}}>— 실제 업무와 근무 환경은 내담자에게 확인</span></Line>
            <Line lb="직업 분야">{mcSign!=null?<>MC {SIGNS[mcSign]} · {CAREER[mcSign]}</>:"출생시각이 불확실하여 MC 기반 분야 해석 보류"}</Line>
            <Line lb="일의 구조">{careerChain?<>10하우스 주인 → {careerChain.rh}하우스 · {JOB_TAG[careerChain.rh-1]}</>:"출생시각이 불확실하여 하우스 기반 구조 해석 보류"}</Line>
            <p style={{margin:"11px 0 6px",fontSize:12,fontWeight:700,color:T.accent}}>일하는 방식 — 내부 점수 상위 {careerTop.length}개</p>
            {careerTop.length?careerTop.map((m,i)=>(
              <details key={m.k} style={{margin:"0 0 6px",padding:"8px 10px",background:"#fff",border:`1px solid ${T.line}`,borderRadius:8}}>
                <summary style={{cursor:"pointer",fontSize:12.5,color:T.ink}}><b>{i+1}. {m.label}</b> <span style={{fontSize:10.5,color:T.dim}}>상대점수 {m.score.toFixed(1)} · 근거 {m.ev.length}개 · 펼쳐보기</span></summary>
                <p style={{fontSize:11.5,lineHeight:1.7,margin:"7px 0",color:T.dim}}><Careful t={m.desc}/></p>
                {m.ev.map((ev,j)=><p key={j} style={{margin:"3px 0",fontSize:11,color:T.dim}}>· {ev}</p>)}
                <p style={{fontSize:11,margin:"6px 0 0",color:T.dim}}>관련 직무 예시: {m.jobs.slice(0,4).join(" · ")}</p>
              </details>
            )):<p style={{fontSize:12,color:T.dim}}>유효한 직업 방식 분석 근거가 부족하다.</p>}
            <p style={{margin:"8px 0 6px",fontSize:11.5,lineHeight:1.75,color:T.ink}}><b>성격과 연결:</b> 의식 {GROUP_NAMES[gCons]} · 무의식 {GROUP_NAMES[gUnc]} — <b>{matrixType}</b>. {matrixMechanism}</p>
            <div style={{borderTop:`1px solid ${T.line}`,paddingTop:8,marginTop:8}}>
              <p style={{margin:"0 0 5px",fontSize:11.5,fontWeight:700,color:T.accent}}>상담사가 현실에서 확인할 것</p>
              <p style={{fontSize:11.5,lineHeight:1.75,margin:0}}>현재 하는 일의 실제 업무 비중, 선호하는 근무 방식, 피로를 느끼는 조건, 소득·안정·성장 목표를 확인한다. 상위 두 방식은 병행하거나 결합할 수 있으며, 서로 모순이라고 단정하지 않는다.</p>
            </div>
            <p style={{fontSize:10.5,lineHeight:1.65,color:T.dim,margin:"9px 0 0"}}>점수는 앱 내부 점성술 규칙으로 산출한 비교값이다. 직업 적성·성공률이나 실제 능력의 검증된 측정값이 아니다.</p>
          </div>
        )}
        <details key={consultFocus} open={consultFocus!=="career"} style={{marginBottom:10}}>
          <summary style={{cursor:"pointer",padding:"9px 12px",background:T.tint,border:`1px solid ${T.line}`,borderRadius:9,fontSize:12.5,fontWeight:700,color:T.accent}}>기존 상세 근거 · 수비학 세 층 · 원소 · 빅3 · 차트 룰러 · 해년의수 {consultFocus==="career"?"(필요할 때 펼치기)":""}</summary>
        <CoreSeal P={P}/>
        {a&&(()=>{
          /* 원소 균형 — 그림만. 해석 문장은 준비용 리포트 3번 섹션에 있다 */
          const eb=elementBalance(a);
          return(
            <div data-card style={{background:"#fff",border:`1px solid ${T.line}`,borderRadius:12,padding:"11px 15px 9px",marginBottom:10}}>
              <div style={{display:"flex",gap:6}}>
                {ELEMS.map((nm,i)=>{
                  const pct=Math.round(eb.tot[i]/eb.sum*100);
                  const on=i===eb.hi&&!eb.flat, off=i===eb.lo&&!eb.flat;
                  return(
                    <div key={nm} style={{flex:1,textAlign:"center"}}>
                      <div style={{height:40,display:"flex",alignItems:"flex-end"}}>
                        <div style={{width:"100%",height:`${Math.max(8,Math.min(100,pct*2.2))}%`,background:ELEM_COLOR[i],opacity:on?1:off?0.25:0.55,borderRadius:"4px 4px 0 0"}}/>
                      </div>
                      <p style={{margin:"3px 0 0",fontSize:10.5,fontWeight:on||off?800:400,color:on?ELEM_COLOR[i]:off?T.bad:T.dim}}>{nm} {pct}%</p>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })()}
        {(()=>{
          /* 요약 — 한 덩어리로 붙이지 않고 층별로 끊는다. 아치 세 칸과 같은 순서다 */
          const num=(r)=>`${r.main}${r.trace!=null?`(${r.trace})`:""}`;
          const rows=[
            {lb:"의식", c:TIER_C[0], n:num(P.cons), nm:card(P.cons.main)[0],
             tx:`남들 앞에 ${card(P.cons.main)[1]}의 얼굴로 선다.${a?` ${SIGN_MODE[signOf(a.sun)]} 쪽이다.`:""}`},
            {lb:"전의식", c:TIER_C[1], n:num(P.pre), nm:card(P.pre.main)[0],
             tx:`갑자기 자극을 받으면 ${card(P.pre.main)[1]} 반응이 먼저 튀어나온다.`},
            {lb:"무의식", c:TIER_C[2], n:num(P.unc), nm:card(P.unc.main)[0],
             tx:`가장 깊은 곳에서 ${eulReul(card(P.unc.main)[1])} 원한다.${a?` ${SIGNS[signOf(a.moon)]}의 온도다.`:""}`},
          ];
          return(
            <div data-card style={{background:T.panel,border:`1.5px solid ${T.accent}`,borderRadius:12,padding:"12px 15px",marginBottom:10}}>
              <p style={{margin:"0 0 7px",fontSize:11,fontWeight:700,color:T.accent,letterSpacing:"0.05em"}}>요약 — 세 개의 층</p>
              {rows.map(r=>(
                <div key={r.lb} style={{marginBottom:7,paddingLeft:9,borderLeft:`3px solid ${r.c[1]}`}}>
                  <p style={{margin:0,fontSize:12.5,lineHeight:1.5}}>
                    <span style={{fontSize:10.5,color:T.dim}}>{r.lb}</span>{" "}
                    <b style={{fontFamily:"var(--fd)",fontSize:14,color:r.c[1]}}>{r.n} {r.nm}</b>
                  </p>
                  <p style={{margin:"1px 0 0",fontSize:11.5,lineHeight:1.7,color:T.ink}}><Careful t={r.tx}/></p>
                </div>
              ))}
            </div>
          );
        })()}
        {(()=>{
          const er=empressRadius(P);
          if(!er||!er.level)return null;
          const col=er.level==="좁음"?T.bad:er.level==="넓음"?T.good:T.accent;
          return(
            <p style={{margin:"0 0 10px",padding:"8px 13px",background:"#fff",border:`1px solid ${col}`,borderRadius:10,fontSize:12,lineHeight:1.65}}>
              <b style={{color:col}}>여황제(3) 돌봄 반경 — {er.level}</b>
              <span style={{color:T.dim,fontSize:10.5}}>{"  "}{er.layers.join("·")}층{er.n>1?` · ${er.n}개 중복`:""}</span>
              {er.reasons.length>0&&<><br/><span style={{color:T.dim,fontSize:11}}><Careful t={er.reasons[0].t}/></span></>}
            </p>
          );
        })()}
        <div data-card style={{background:"#fff",border:`1px solid ${T.line}`,borderRadius:12,padding:"13px 15px",marginBottom:10}}>
          {a&&(()=>{
            /* 빅3 — 세 축을 각각 한 줄로. 긴 서술은 준비용 리포트에 있으므로 첫 문장만 쓴다 */
            const one=(t)=>{const m=t.split(/(?<=다)\.\s/)[0];return m.endsWith(".")?m:m+".";};
            const rows=[
              ascS!=null?["상승","보이는 얼굴",SIGNS[ascS],one(ASC_TYPE[ascS].look)]:null,
              ["태양","증명하는 방식",SIGNS[signOf(a.sun)],one(SIGN_CORE[signOf(a.sun)].sun)],
              ["달","안심하는 조건",SIGNS[signOf(a.moon)],one(SIGN_CORE[signOf(a.moon)].moon)],
            ].filter(Boolean);
            return(
              <div style={{marginBottom:8}}>
                {rows.map(([ax,role,sg,txt],i)=>(
                  <p key={ax} style={{margin:i?"3px 0 0":"0",fontSize:12.5,lineHeight:1.65,display:"flex",gap:7}}>
                    <b style={{color:T.accent,minWidth:52,flexShrink:0,fontSize:11}}>{i?"":"빅3"}</b>
                    <span style={{color:T.ink}}>
                      <b>{ax} {sg}</b>
                      <span style={{color:T.dim,fontSize:10.5}}> {role}</span>
                      <br/><span style={{color:T.dim,fontSize:11.5}}><Careful t={txt}/></span>
                    </span>
                  </p>
                ))}
              </div>
            );
          })()}
          {crH&&(
            <Line lb="차트 룰러">
              {KR10[cr]} → <b style={{color:T.accent}}>{crH}하우스 {HOUSE_SHORT[crH-1]}</b>
              <span style={{color:T.dim}}> — 점성술적으로 이 하우스의 주제를 우선 살펴볼 수 있다. 실제 삶에서 중요한 영역인지는 내담자와 확인한다.</span>
            </Line>
          )}
          <div style={{marginTop:2}}>
            <p style={{margin:"0 0 4px",fontSize:12.5,lineHeight:1.65,display:"flex",gap:7}}>
              <b style={{color:T.accent,minWidth:52,flexShrink:0,fontSize:11}}>해년의수</b>
              <span style={{color:T.dim,fontSize:11}}>{yrs[0].y}~{yrs[yrs.length-1].y}년</span>
            </p>
            {yrs.map(v=>{
              const on=v.y===year;
              return(
                <p key={v.y} style={{margin:"0 0 2px 59px",fontSize:12,lineHeight:1.6,display:"flex",gap:6}}>
                  <b style={{minWidth:34,flexShrink:0,color:on?T.accent:T.dim,fontSize:11.5}}>{v.y}</b>
                  <b style={{minWidth:16,flexShrink:0,fontFamily:"var(--fd)",fontSize:13,color:on?T.accent:T.ink}}>{v.main}</b>
                  <span style={{color:on?T.ink:T.dim,fontWeight:on?700:400}}>{card(v.main)[0]}</span>
                  <span style={{color:T.dim}}>· {card(v.main)[1]}</span>
                  <span style={{color:ELEM_COLOR[cardElem(v.main)],fontSize:10.5}}>{ELEMS[cardElem(v.main)]}</span>
                </p>
              );
            })}
          </div>
        </div>

        </details>

        {consultFocus!=="career"&&<div data-card style={{background:T.tint,border:`1px solid ${T.line}`,borderRadius:12,padding:"13px 15px",marginBottom:10}}>
          <p style={{margin:"0 0 7px",fontSize:11,fontWeight:700,color:T.accent}}>성격 통합 핵심 — 중복 없이 한 번만 설명</p>
          <p style={{margin:"0 0 5px",fontSize:12.5,lineHeight:1.65}}><b>{matrixType}</b> · 의식 {GROUP_NAMES[gCons]} / 무의식 {GROUP_NAMES[gUnc]}</p>
          <p style={{margin:"0 0 5px",fontSize:12,lineHeight:1.7}}><Careful t={matrixMechanism}/></p>
          <p style={{margin:0,fontSize:11.5,lineHeight:1.7,color:T.dim}}>상담 확인: <Careful t={matrixAdvice}/></p>
        </div>}

      </div>
    );
  };

  const Big3=({P})=>{
    const a=P.astro; if(!a)return null;
    const ascS=a.approx?null:signOf(a.asc);
    /* 상승점에 붙은 행성 — 1하우스 방향 10도, 12하우스 방향 5도 이내면 사인을 덮어쓴다 */
    const conj=[];
    if(!a.approx){
      for(const k of BODY10){
        const L=k==="Sun"?a.sun:k==="Moon"?a.moon:a.planets[k].lon;
        const fwd=((L-a.asc)%360+360)%360;          /* 0~ : 1하우스 방향 */
        const back=((a.asc-L)%360+360)%360;         /* 0~ : 12하우스 방향 */
        if(fwd<=10)conj.push({k,side:"1하우스",deg:fwd});
        else if(back<=5)conj.push({k,side:"12하우스",deg:back});
      }
    }
    const cr=ascS!=null?RULER[ascS]:null;            /* 차트 룰러 */
    const crH=cr?wholeHouse(cr==="Sun"?a.sun:cr==="Moon"?a.moon:a.planets[cr].lon,a.asc):null;
    const crS=cr?signOf(cr==="Sun"?a.sun:cr==="Moon"?a.moon:a.planets[cr].lon):null;
    const sunS=signOf(a.sun),moonS=signOf(a.moon);
    const els=[ascS,sunS,moonS].filter(x=>x!=null).map(x=>x%4);
    const spread=new Set(els).size;

    const PSrow=(key,s)=>{const d=PS84[key]&&PS84[key][s];if(!d)return null;
      return(<p style={{margin:"4px 0 0",fontSize:14,lineHeight:1.7,color:T.ink}}>
        <b style={{color:T.ink}}>작동</b> {d.op} <b style={{color:T.ink}}>{d.k2}</b> {d.v2} <b style={{color:T.bad}}>{d.k3}</b> {d.v3}
      </p>);};

    return(
      <div style={{marginTop:10}}>
        <p style={{margin:"0 0 7px",fontSize:13,color:T.dim,lineHeight:1.6}}>
          상승점은 <b>첫인상</b>, 태양은 <b>중요하게 여기는 방향</b>, 달은 <b>마음이 편안해지는 조건</b>을 보여준다.
        </p>

        {ascS!=null&&(
          <div data-card style={{background:"#fff",border:`1px solid ${T.line}`,borderRadius:11,padding:"12px 13px",marginBottom:6}}>
            <p style={{margin:0,fontSize:15,lineHeight:1.5}}>
              <b style={{fontFamily:"var(--fd)",fontSize:18,color:T.accent}}>상승점 · {SIGNS[ascS]}</b>
              <span style={{fontSize:12.5,color:T.dim}}>{"  "}남에게 보이는 얼굴</span>
              <span style={{fontSize:12.5,color:ELEM_COLOR[ascS%4],fontWeight:700}}>{"  "}{ELEMS[ascS%4]}</span>
            </p>
            <p style={{margin:"5px 0 0",fontSize:14.5,lineHeight:1.7,color:T.ink}}>
              <b>첫인상</b> {ASC_TYPE[ascS].look}<br/>
              <b>자동 반응</b> {ASC_TYPE[ascS].reflex}<br/>
              <b>렌즈</b> {ASC_TYPE[ascS].lens}
            </p>
            {conj.length>0&&(
              <p style={{margin:"6px 0 0",fontSize:13.5,lineHeight:1.7,color:T.dim,paddingLeft:9,borderLeft:`2px solid ${T.accent}`}}>
                <b style={{color:T.accent}}>사인을 덮어쓰는 행성</b> — {conj.map(c=>`${KR10[c.k]}가 ${c.side} 방향 ${c.deg.toFixed(1)}° (${ASC_CONJ[c.k]})`).join(" / ")}. 첫인상에 영향을 더할 수 있다.
                {conj.some(c=>c.side==="12하우스")&&<> <b>12하우스 쪽의 특징은 스스로 알아차리기 어려울 수 있다</b> — "남들은 그렇게 보는데 나는 몰랐다"는 반응이 나온다.</>}
              </p>
            )}
            <p style={{margin:"6px 0 0",fontSize:13.5,lineHeight:1.7,color:T.dim}}>
              <b style={{color:T.ink}}>차트 룰러</b> {KR10[cr]} · {SIGNS[crS]} · {crH}하우스 — <b style={{color:T.accent}}>{crH}하우스({HOUSE_SHORT[crH-1]})</b>와 관련된 주제를 우선 살펴본다. 실제로 중요한 영역인지는 상담에서 확인한다.
              <br/><b style={{color:T.ink}}>하강점 {ASC_TYPE[ascS].dscSign}자리</b> {ASC_TYPE[ascS].dsc}
            </p>
          </div>
        )}
        {a.approx&&(
          <p style={{margin:"0 0 6px",fontSize:13.5,color:T.accent,lineHeight:1.7}}>
            출생시간을 모르면 상승점을 산출할 수 없어 이 축은 생략된다. 상승점은 4분마다 1도씩 움직여 시간 오차에 가장 민감한 지점이다.
          </p>
        )}

        {[["태양","존재를 증명하는 방식",sunS,"sun","Sun"],["달","안심하는 조건",moonS,"moon","Moon"]].map(([nm,role,s,axis,key])=>(
          <div key={nm} data-card style={{background:"#fff",border:`1px solid ${T.line}`,borderRadius:11,padding:"12px 13px",marginBottom:6}}>
            <p style={{margin:0,fontSize:15,lineHeight:1.5}}>
              <b style={{fontFamily:"var(--fd)",fontSize:18,color:T.accent}}>{nm} · {SIGNS[s]}</b>
              <span style={{fontSize:12.5,color:T.dim}}>{"  "}{role}</span>
              <span style={{fontSize:12.5,color:ELEM_COLOR[s%4],fontWeight:700}}>{"  "}{ELEMS[s%4]}</span>
              {dignity(key,s)&&<span style={{fontSize:10.5,color:T.accent,fontWeight:700}}>{"  "}{DIG_LABEL[dignity(key,s)]}</span>}
            </p>
            <p style={{margin:"5px 0 0",fontSize:14.5,lineHeight:1.7,color:T.ink}}>{SIGN_CORE[s][axis]}</p>
            {PSrow(key,s)}
          </div>
        ))}

        {ascS!=null&&(
          <p style={{margin:"6px 0 0",fontSize:13.5,lineHeight:1.7,color:T.dim,paddingLeft:10,borderLeft:`2px solid ${T.line}`}}>
            <b style={{color:T.ink}}>상승점과 중천점의 차이</b> — 상승점은 <b>첫인상</b>, 중천점(MC)은 <b>사회적 역할</b>과 관련된다. 상승점은 개인적 접점과 첫인상, MC는 공적 이미지와 커리어 방향을 맡는다. 이 차트의 MC는 {SIGNS[signOf(a.mc)]}다.
          </p>
        )}
        <p style={{margin:"7px 0 0",fontSize:13.5,lineHeight:1.7,color:T.dim,paddingLeft:10,borderLeft:`2px solid ${T.bad}`}}>
          <b style={{color:T.bad}}>가장 크게 걸리는 지점</b> — {SIGN_CORE[sunS].edge}
        </p>
        <p style={{margin:"6px 0 0",fontSize:13.5,lineHeight:1.7,color:T.dim,paddingLeft:10,borderLeft:`2px solid ${T.accent}`}}>
          <b style={{color:T.accent}}>세 축의 관계</b> — {
            spread===1?`세 축이 모두 ${ELEMS[els[0]]}의 결이다. 보이는 얼굴과 속이 일치해 오해를 덜 사지만, 그만큼 편중이 심해 이 결의 과제가 인생 전면에 반복해서 나타난다.`
            :spread===els.length?`세 축의 결이 모두 다르다(${els.map(e=>ELEMS[e]).join("·")}). 겉과 속, 방향과 안전감이 따로 놀아 스스로도 자기를 설명하기 어렵다 — 상황마다 다른 사람처럼 보이는 것이 결함이 아니라 구조다.`
            :`두 축이 같은 결을 공유하고 하나가 어긋난다. 어긋난 축이 이 사람의 사각지대이자, 상담에서 가장 말할 거리가 많은 자리다.`
          }
        </p>
      </div>
    );
  };

  const CoreSeal=({P})=>{
    const tiers=[["의식",P.cons],["전의식",P.pre],["무의식",P.unc]];
    /* 층별 색 — 낮(사회적 얼굴) → 반응의 경계면 → 음력이 비추는 심층 */
    const sun=P.astro?signOf(P.astro.sun):null;
    const moon=P.astro?signOf(P.astro.moon):null;
    const asc=(P.astro&&!P.astro.approx)?signOf(P.astro.asc):null;
    const pad=n=>String(n).padStart(2,"0");
    return(
      <div style={{display:"flex",gap:15,alignItems:"stretch",background:T.panel,border:`1.5px solid ${T.accent}`,borderRadius:14,padding:"15px 16px",marginBottom:14,breakInside:"avoid",pageBreakInside:"avoid"}}>
        <div style={{width:110,flexShrink:0,border:`1.5px solid ${T.ink}`,borderRadius:"55px 55px 10px 10px",overflow:"hidden",background:"#fff"}}>
          {tiers.map(([lb,r],i)=>(
            <div key={lb} style={{background:TIER_C[i][0],borderTop:i?`1.5px solid ${T.ink}`:"none",padding:i===0?"15px 0 7px":"7px 0 8px",textAlign:"center"}}>
              <p style={{margin:0,fontSize:8.5,letterSpacing:"0.14em",color:TIER_C[i][1],lineHeight:1.2}}>{lb}</p>
              <p style={{margin:"1px 0 0",fontFamily:"var(--fd)",fontSize:i===0?27:24,lineHeight:1.1,color:TIER_C[i][1]}}>
                {r.main}{r.trace!=null&&<span style={{fontSize:13,color:T.dim}}>({r.trace})</span>}
              </p>
            </div>
          ))}
        </div>
        <div style={{flex:1,minWidth:0,display:"flex",flexDirection:"column",justifyContent:"center"}}>
          <p style={{margin:0,fontSize:9.5,letterSpacing:"0.16em",color:T.dim}}>태양궁</p>
          <p style={{margin:"2px 0 0",fontFamily:"var(--fd)",fontSize:29,lineHeight:1.15,color:T.accent}}>{sun!=null?SIGNS[sun]:"—"}</p>
          {(moon!=null||asc!=null)&&(
            <p style={{margin:"5px 0 0",fontSize:11.5,color:T.dim,lineHeight:1.6}}>
              {moon!=null&&<>달 {SIGNS[moon]}</>}{asc!=null&&<> · 상승점 {SIGNS[asc]}</>}
            </p>
          )}
          <p style={{margin:"8px 0 0",fontSize:11,color:T.dim,lineHeight:1.6,borderTop:`1px solid ${T.line}`,paddingTop:7}}>
            양력 {P.sy}.{pad(P.sm)}.{pad(P.sd)} · 음력 {P.lunar.year}.{P.lunar.isLeap?"윤":""}{pad(P.lunar.month)}.{pad(P.lunar.day)}
          </p>
          <p style={{margin:"4px 0 0",fontSize:11.5,lineHeight:1.7,color:T.ink}}>
            {tiers.map(([lb,r],i)=>(
              <span key={lb}>{i?<span style={{color:T.dim}}> · </span>:null}<b style={{color:T.accent}}>{r.main}</b> {card(r.main)[0]}</span>
            ))}
          </p>
        </div>
      </div>
    );
  };

  const LayerBlock=({P})=>{
    const approx=P.astro?.approx;
    const fusion=P.astro?[
      ["태양",signOf(P.astro.sun)],
      approx?["수성",signOf(P.astro.planets.Mercury.lon)]:["상승점",signOf(P.astro.asc)],
      ["달",signOf(P.astro.moon)],
    ]:null;
    const rows=[
      ["의식층 · 양력",P.cons,0],
      ["전의식층 · 양력",P.pre,1],
      ["무의식층 · 음력",P.unc,2],
    ];
    return rows.map(([title,r,i])=>(
      <div key={title} data-card style={{background:T.strata[i],border:`1px solid ${T.line}`,borderRadius:12,padding:"13px 14px",marginBottom:9,textAlign:"left"}}>
        <p style={{margin:"0 0 7px",fontSize:13,fontWeight:750,color:T.dim,textAlign:"left"}}>{title} · 계산 {r.steps}</p>
        <div style={{display:"flex",gap:12,alignItems:"center",marginBottom:11,textAlign:"left"}}>
          <Seal n={r.main} size={44}/>
          <div style={{minWidth:0,flex:1}}>
            <p style={{margin:0,fontSize:19,fontWeight:800,lineHeight:1.45,color:T.ink,textAlign:"left"}}>
              <span style={{color:T.accent}}>{card(r.main)[0]}</span>
              <span style={{fontSize:17,color:ELEM_COLOR[cardElem(r.main)],fontWeight:750}}> ({ELEMS[cardElem(r.main)]})</span>
              {fusion&&<span style={{fontSize:15,color:T.ink,fontWeight:650}}> ｜ {fusion[i][0]} {SIGNS[fusion[i][1]]}{approx&&i===2?" (±오차)":""}</span>}
            </p>
            {r.trace!=null&&<p style={{margin:"3px 0 0",fontSize:13,color:T.dim}}>내포 카드: {card(r.trace)[0]}</p>}
          </div>
        </div>
        <p style={{margin:0,fontSize:15,lineHeight:1.7,color:T.ink,textAlign:"left"}}>{layerEmphasis(card(r.main)[2])}</p>
        {fusion&&(
          <div style={{marginTop:10,borderTop:`1px solid ${T.line}`,paddingTop:10,textAlign:"left"}}>
            <p style={{margin:"0 0 5px",fontSize:14.5,fontWeight:800,color:T.accent,textAlign:"left"}}>{fusion[i][0]} {SIGNS[fusion[i][1]]} · 성향이 드러나는 방식</p>
            <p style={{margin:0,fontSize:14.5,lineHeight:1.72,color:T.ink,textAlign:"left"}}>
              {layerEmphasis(`${SIGN_MODE[fusion[i][1]]} 성향이 나타난다. ${SIGN_TEXT[fusion[i][1]].split("그러나")[0].trim()}`)}
            </p>
          </div>
        )}
      </div>
    ));
  };

  /* 하우스 12궁 */
  /* ═══ 천체도 — 홀사인 12궁 원판 ═══
     ASC를 화면 왼쪽(9시)에 고정하고 반시계로 돈다. 홀사인이므로 하우스 경계 = 사인 경계.
     외행성 색은 outerActivation() 판정을 그대로 따른다 — 보라=개인화, 회색=세대 배경. */
  const ChartWheel=({astro})=>{
    if(!astro||astro.approx)return null;
    const SGL=["♈","♉","♊","♋","♌","♍","♎","♏","♐","♑","♒","♓"];
    const SKS=["양","황소","쌍둥이","게","사자","처녀","천칭","전갈","사수","염소","물병","물고기"];
    const HKS=["자아","재물","소통","가정","창작","실무","관계","공유","확장","커리어","연대","내면"];
    const lonOf=(k)=>k==="Sun"?astro.sun:k==="Moon"?astro.moon:astro.planets[k].lon;
    const isRet=(k)=>k!=="Sun"&&k!=="Moon"&&astro.planets[k].retro;
    const n360=(l)=>((l%360)+360)%360;
    const dm=(l)=>`${Math.floor(n360(l)%30)}°`;

    const S=440,C=220,R1=196,R2=186,R3=154,R4=142,R5=118,HUB=22;
    const rad=(l)=>(180+n360(l-astro.asc))*Math.PI/180;
    const X=(l,r)=>(C+r*Math.cos(rad(l))).toFixed(1);
    const Y=(l,r)=>(C-r*Math.sin(rad(l))).toFixed(1);
    const tan=(l)=>{let a=-((180+n360(l-astro.asc))+90);a=((a+180)%360+360)%360-180;if(Math.abs(a)>90)a+=180;return a.toFixed(1);};

    const ascS=signOf(astro.asc);
    const parts=[];
    /* 사인 띠 */
    for(let k=0;k<12;k++){
      const s=(ascS+k)%12,a=s*30,b=a+30,mid=a+15;
      parts.push(<path key={`s${k}`} d={`M${X(a,R2)},${Y(a,R2)} A${R2},${R2} 0 0 0 ${X(b,R2)},${Y(b,R2)} L${X(b,R3)},${Y(b,R3)} A${R3},${R3} 0 0 1 ${X(a,R3)},${Y(a,R3)} Z`}
        fill={WHEEL_ELEM[s%4]} fillOpacity="0.15" stroke={T.line} strokeWidth="0.8"/>);
      parts.push(<text key={`sg${k}`} x={X(mid,R3+21)} y={Y(mid,R3+21)} textAnchor="middle" dominantBaseline="central"
        fontSize="17" fontWeight="700" fill={WHEEL_ELEM[s%4]} transform={`rotate(${tan(mid)},${X(mid,R3+21)},${Y(mid,R3+21)})`}>{SGL[s]}</text>);
      parts.push(<text key={`sk${k}`} x={X(mid,R3+8)} y={Y(mid,R3+8)} textAnchor="middle" dominantBaseline="central"
        fontSize="8.5" fill={T.ink} transform={`rotate(${tan(mid)},${X(mid,R3+8)},${Y(mid,R3+8)})`}>{SKS[s]}</text>);
    }
    /* 눈금 */
    for(let d=0;d<360;d+=5)
      parts.push(<line key={`t${d}`} x1={X(d,R3)} y1={Y(d,R3)} x2={X(d,R3+(d%30===0?0:d%10===0?8:5))} y2={Y(d,R3+(d%30===0?0:d%10===0?8:5))}
        stroke={T.line} strokeWidth="0.7"/>);
    /* 하우스 띠 */
    parts.push(<circle key="hb" cx={C} cy={C} r={R4} fill={T.tint} fillOpacity="0.5" stroke={T.line} strokeWidth="1"/>);
    parts.push(<circle key="ib" cx={C} cy={C} r={R5} fill="#fff" stroke={T.line} strokeWidth="1"/>);
    for(let h=0;h<12;h++){
      const c=n360(ascS*30+h*30),mid=n360(c+15),ang=[0,3,6,9].includes(h);
      parts.push(<line key={`hl${h}`} x1={X(c,R5)} y1={Y(c,R5)} x2={X(c,R3)} y2={Y(c,R3)} stroke={T.ink} strokeWidth={ang?1.6:0.9} strokeOpacity={ang?0.85:0.3}/>);
      parts.push(<line key={`hi${h}`} x1={X(c,HUB)} y1={Y(c,HUB)} x2={X(c,R5)} y2={Y(c,R5)} stroke={T.ink} strokeWidth={ang?1:0.7} strokeOpacity={ang?0.35:0.16}/>);
      parts.push(<text key={`hn${h}`} x={X(mid,(R4+R5)/2+6)} y={Y(mid,(R4+R5)/2+6)} textAnchor="middle" dominantBaseline="central"
        fontSize="12" fontWeight="700" fill={T.dim} transform={`rotate(${tan(mid)},${X(mid,(R4+R5)/2+6)},${Y(mid,(R4+R5)/2+6)})`}>{h+1}</text>);
      parts.push(<text key={`hk${h}`} x={X(mid,(R4+R5)/2-7)} y={Y(mid,(R4+R5)/2-7)} textAnchor="middle" dominantBaseline="central"
        fontSize="7.5" fill={T.dim} transform={`rotate(${tan(mid)},${X(mid,(R4+R5)/2-7)},${Y(mid,(R4+R5)/2-7)})`}>{HKS[h]}</text>);
    }
    /* 네 축 — 홀사인에서 MC·IC는 커스프와 어긋나므로 점선으로 실제 위치에 그린다 */
    [["ASC",astro.asc,false],["DSC",n360(astro.asc+180),false],["MC",astro.mc,true],["IC",n360(astro.mc+180),true]].forEach(([nm,l,dash])=>{
      parts.push(<line key={`ax${nm}`} x1={X(l,R5)} y1={Y(l,R5)} x2={X(l,R2)} y2={Y(l,R2)} stroke={T.ink} strokeWidth="1.4" strokeDasharray={dash?"6 4":undefined}/>);
      parts.push(<text key={`al${nm}`} x={X(l,R1+16)} y={Y(l,R1+16)} textAnchor="middle" dominantBaseline="central" fontSize="11" fontWeight="700" fill={T.ink}>{nm}</text>);
    });
    /* 어스펙트 — 4번 섹션과 같은 natalAspects를 쓴다 */
    natalAspects(astro).forEach((r,i)=>{
      if(r.nm==="합")return;
      parts.push(<line key={`ap${i}`} x1={X(lonOf(r.a),R5)} y1={Y(lonOf(r.a),R5)} x2={X(lonOf(r.b),R5)} y2={Y(lonOf(r.b),R5)}
        stroke={r.tone==="h"?WHEEL_HARD:WHEEL_SOFT} strokeWidth={r.o<2?1.6:1} strokeOpacity={r.o<2?0.75:0.4}/>);
    });
    /* 행성 — 동그라미 없이 글리프, 후광은 별도 텍스트로 깐다 */
    parts.push(<circle key="hub" cx={C} cy={C} r={HUB} fill={T.sheet} stroke={T.line} strokeWidth="1"/>);
    /* 겹침 회피 — 각도로 벌리고, 실제 황경은 지시선이 가리킨다.
       필요 간격은 고정값이 아니라 그 화면 위치에서 가로 라벨이 실제로 먹는 접선 폭으로 계산한다.
       원판 좌우(3·9시)에서는 가로 라벨이 접선을 거의 안 먹으므로 밀집 구간을 억지로 벌리지 않는다. */
    const PR=R5-28, MIN_ABS=8;
    const labW=(k)=>12+2+KR10[k].length*6.8+(isRet(k)?8:0);
    const tanExt=(absAngle,k)=>{
      const phi=(180+n360(absAngle))*Math.PI/180;
      const px=Math.abs(labW(k)*Math.sin(phi))+Math.abs(17*Math.cos(phi));
      return px/(2*Math.PI*PR/360);
    };
    const placed=(()=>{
      let a=BODY10.map(k=>({k,L:lonOf(k),d:n360(lonOf(k)-astro.asc)})).sort((x,y)=>x.d-y.d);
      let gi=0,gmax=-1;
      for(let i=0;i<a.length;i++){const g=n360(a[(i+1)%a.length].d-a[i].d);if(g>gmax){gmax=g;gi=(i+1)%a.length;}}
      a=a.slice(gi).concat(a.slice(0,gi));
      const base=a[0].d;
      /* 필요 간격은 '원래 위치' 기준으로 한 번만 구해 상수로 고정한다.
         현재 위치로 매번 다시 재면 밀 때마다 기준이 흔들려 수렴하지 않는다. */
      a.forEach(q=>{q.o=n360(q.d-base);q.d=q.o;q.ext=tanExt(base+q.o,q.k);});
      const need=(p2,q2)=>Math.max(MIN_ABS,(p2.ext+q2.ext)/2+2);
      for(let rep=0;rep<3;rep++){
        for(let i=1;i<a.length;i++){const nd=need(a[i-1],a[i]);if(a[i].d-a[i-1].d<nd)a[i].d=a[i-1].d+nd;}
        let i=0;
        while(i<a.length){
          let j=i; while(j+1<a.length&&a[j+1].d-a[j].d<need(a[j],a[j+1])+0.01) j++;
          if(j>i){
            const want=a.slice(i,j+1).reduce((t,q)=>t+q.o,0)/(j-i+1);
            const have=a.slice(i,j+1).reduce((t,q)=>t+q.d,0)/(j-i+1);
            const lo=(i>0?a[i-1].d+need(a[i-1],a[i]):-1e9)-a[i].d;
            const hi=(j<a.length-1?a[j+1].d-need(a[j],a[j+1]):1e9)-a[j].d;
            const sh=Math.max(lo,Math.min(hi,want-have));
            for(let m=i;m<=j;m++)a[m].d+=sh;
          }
          i=j+1;
        }
      }
      /* 되돌림으로 위치가 바뀌면 필요 간격도 다시 계산되어 0.5도 이내가 남는다 — 마지막에 확정한다 */
      for(let i=1;i<a.length;i++){const nd=need(a[i-1],a[i]);if(a[i].d-a[i-1].d<nd)a[i].d=a[i-1].d+nd;}
      return a.map(q=>({k:q.k,L:q.L,dl:astro.asc+base+q.d,r:PR}));
    })();
    /* 후광을 전부 먼저 깔고 본체를 얹는다 — 이웃의 후광이 앞 글리프를 지우는 것을 막는다 */
    const halo=[],body=[];
    placed.forEach(({L,dl,r,k})=>{
      const act=outerActivation(astro,k,wholeHouse(L,astro.asc)-1);
      const col=(act&&!act.active)?T.dim:WHEEL_PC[k];   /* 세대 배경만 회색 처리 */
      const gx=Number(X(dl,r)),gy=Number(Y(dl,r));
      body.push(<line key={`pl${k}`} x1={X(L,R5)} y1={Y(L,R5)} x2={X(dl,r+9)} y2={Y(dl,r+9)} stroke={col} strokeWidth="1" strokeOpacity="0.5"/>);
      /* 기호는 얇게 왼쪽, 이름은 오른쪽, 도수는 아래 */
      [{x:gx-1,y:gy,anc:"end",fs:13,fw:400,txt:PL_SYM[k],sw:3,fill:col},
       {x:gx+2,y:gy,anc:"start",fs:6.8,fw:700,txt:KR10[k]+(isRet(k)?" R":""),sw:2.4,fill:col},
       {x:gx,y:gy+11,anc:"middle",fs:6,fw:400,txt:dm(L),sw:2.2,fill:T.dim}].forEach((it,n)=>{
        halo.push(<text key={`ph${k}${n}`} x={it.x} y={it.y} textAnchor={it.anc} dominantBaseline="central" fontSize={it.fs} fontWeight={it.fw} fill="none" stroke="#fff" strokeWidth={it.sw} strokeLinejoin="round">{it.txt}</text>);
        body.push(<text key={`pb${k}${n}`} x={it.x} y={it.y} textAnchor={it.anc} dominantBaseline="central" fontSize={it.fs} fontWeight={it.fw} fill={it.fill}>{it.txt}</text>);
      });
    });
    parts.push(...halo,...body);

    const dms=(l)=>{const v=n360(l)%30;const d=Math.floor(v);let m=Math.round((v-d)*60);let dd=d;if(m===60){m=0;dd=d+1;}return `${dd}°${String(m).padStart(2,"0")}'`;};
    const rows=[...BODY10.map(k=>{
      const L=lonOf(k),act=outerActivation(astro,k,wholeHouse(L,astro.asc)-1);
      return{sym:PL_SYM[k],nm:KR10[k],s:signOf(L),deg:dms(L),h:wholeHouse(L,astro.asc),
             r:isRet(k),col:(act&&!act.active)?T.dim:WHEEL_PC[k],bg:!!(act&&!act.active)};
    }),
    {sym:"AC",nm:"상승점",s:signOf(astro.asc),deg:dms(astro.asc),h:1,r:false,col:T.ink,bg:false},
    {sym:"MC",nm:"중천점",s:signOf(astro.mc),deg:dms(astro.mc),h:wholeHouse(astro.mc,astro.asc),r:false,col:T.ink,bg:false}];

    return(
      <div style={{marginBottom:12}}>
        <svg viewBox={`-14 -14 ${S+28} ${S+28}`} style={{width:"100%",height:"auto",display:"block"}} xmlns="http://www.w3.org/2000/svg">{parts}</svg>
        <div style={{display:"grid",gridTemplateColumns:"minmax(0,1fr) minmax(0,1fr)",gap:"0 10px",marginTop:8,padding:"9px 11px",background:"#fff",border:`1px solid ${T.line}`,borderRadius:10}}>
          {rows.map(r=>(
            <p key={r.nm} style={{margin:"0 0 3px",fontSize:10.5,lineHeight:1.55,color:T.dim,display:"flex",gap:4,alignItems:"baseline",opacity:r.bg?0.65:1}}>
              <b style={{color:r.col,fontSize:12,minWidth:15}}>{r.sym}</b>
              <span style={{color:T.ink,minWidth:30}}>{r.nm}</span>
              <span>{SIGNS[r.s].replace("자리","")} {r.deg}</span>
              {r.r&&<b style={{color:T.bad}}>R</b>}
              <span style={{marginLeft:"auto",color:T.accent,fontWeight:700}}>{r.h}H</span>
            </p>
          ))}
        </div>

      </div>
    );
  };

  // 하우스 전용 화면 문장 정리: 원본 데이터와 계산 결과는 변경하지 않는다.
  const housePlain=(value)=>String(value??"")
    .replace(/판을 엎는다/g,"기존 방식을 크게 바꾸려 한다")
    .replace(/규정당하면 죽는다/g,"남이 정한 틀에 갇히는 것을 강하게 거부한다")
    .replace(/분위기로 존재한다/g,"말보다 분위기와 태도로 자신을 드러낸다")
    .replace(/잔고가 줄면 인격이 줄어드는 느낌/g,"잔고가 줄면 자신의 가치까지 낮아진 것처럼 느낄 수 있다")
    .replace(/정체성 붕괴/g,"자신이 누구인지 혼란스러워질 수 있다");
  const HOUSE_PICK_LABELS=["자아","돈·소유","소통·학습","가정","창작·연애","일상·건강","관계·계약","공유자산","철학·확장","직업·명예","친구·공동체","내면·휴식"];
  const HOUSE_BLUE="#135FD1",HOUSE_RED="#B42318",HOUSE_GREEN="#087C56",HOUSE_INK="#303846";
  const HouseGrid=({astro})=>{
    const [selectedHouse,setSelectedHouse]=useState(0);
    const [showAllHouses,setShowAllHouses]=useState(false);
    const ascS=signOf(astro.asc);
    const occupants=(hIdx)=>{
      const list=[];
      if(wholeHouse(astro.sun,astro.asc)===hIdx+1)list.push({key:"Sun",kr:"태양",retro:false,lon:astro.sun});
      if(wholeHouse(astro.moon,astro.asc)===hIdx+1)list.push({key:"Moon",kr:"달",retro:false,lon:astro.moon});
      for(const[p,v]of Object.entries(astro.planets))
        if(wholeHouse(v.lon,astro.asc)===hIdx+1)list.push({key:p,kr:PL_KR[p]+(v.retro?"R":""),retro:v.retro,lon:v.lon});
      return list;
    };
    return(
      <>
        <div className="lb-house-selector" style={{marginBottom:12,textAlign:"left"}}>
          <p style={{margin:"0 0 8px",fontSize:14,fontWeight:800,color:HOUSE_INK}}>살펴볼 하우스 선택</p>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(125px,1fr))",gap:7}}>
            {HOUSE_PICK_LABELS.map((name,i)=>(
              <button key={i} type="button" aria-pressed={!showAllHouses&&selectedHouse===i}
                onClick={()=>{setSelectedHouse(i);setShowAllHouses(false);}}
                style={{minHeight:44,borderRadius:9,padding:"8px 10px",textAlign:"left",cursor:"pointer",fontWeight:750,fontSize:12.5,
                  background:!showAllHouses&&selectedHouse===i?HOUSE_BLUE:"#fff",
                  color:!showAllHouses&&selectedHouse===i?"#fff":HOUSE_INK,
                  border:`1px solid ${!showAllHouses&&selectedHouse===i?HOUSE_BLUE:"#CED5E0"}`}}>
                {i+1}하우스 ({name})
              </button>
            ))}
          </div>
          <button type="button" onClick={()=>setShowAllHouses(v=>!v)}
            style={{marginTop:9,minHeight:44,padding:"8px 14px",cursor:"pointer",borderRadius:9,
              border:`1px solid ${HOUSE_BLUE}`,color:HOUSE_BLUE,background:"#fff",fontWeight:800}}>
            {showAllHouses?"선택한 하우스만 보기":"12하우스 전체 보기"}
          </button>
        </div>
        {HOUSES.map(([kw,desc,energy],i)=>{
          const occ=occupants(i);
          const hot=occ.length>0;
          const s=(ascS+i)%12;
          const shadowRaw=(SIGN_TEXT[s].split("그러나")[1]||"").split("또한")[0];
          const shadow=shadowRaw?shadowRaw.replace(/^[\s,]+/,"").trim():null;
          const ch=chainOf(astro,i+1);
          const same=ch&&ch.rh===i+1;
          const act={};for(const o of occ)act[o.key]=outerActivation(astro,o.key,i);
          const isBg=(o)=>act[o.key]&&!act[o.key].active;          /* 세대 배경으로만 다룰 행성 */
          const tone=(o)=>act[o.key]?(act[o.key].active?OUTER_ON:T.dim):T.accent;
          const retros=occ.filter(o=>o.retro&&RETRO_BY_PLANET[o.key]&&!isBg(o));
          return(
            <div key={i} className="lb-house-panel" data-card style={{display:showAllHouses||selectedHouse===i?"block":"none",background:"#fff",border:`1px solid ${hot?"#91B8EF":"#DCE3EC"}`,borderRadius:12,padding:"14px 15px",marginBottom:9,textAlign:"left"}}>
              <div style={{margin:0,fontFamily:"var(--fd)",fontSize:17,fontWeight:850,color:HOUSE_INK,lineHeight:1.5,textAlign:"left"}}>
                {i+1}하우스 · {kw}
                <span style={{fontFamily:"var(--fb)",fontSize:11.5,color:T.dim,fontWeight:400}}>
                  {" ("}{SIGNS[s]}
                  {hot&&<> / {occ.map((o,n)=>(
                    <b key={o.key} style={{color:tone(o)}}>{n?" · ":""}{o.kr}{isBg(o)?"(배경)":""}</b>
                  ))}</>}
                  {ch&&<> / 주인: {KR10[ch.rp]} → {same?"제집":`${ch.rh}하우스`}</>}{")"}

                </span>
              </div>
              <p style={{margin:"4px 0 0",fontSize:12,lineHeight:1.65,color:T.dim}}>{desc}</p>

              {occ.map(o=>{
                const a=act[o.key],bg=isBg(o),L=PH120[o.key]&&PH120[o.key][i];
                return(
                <div key={o.key} style={{margin:"11px 0 0",padding:"10px 12px",background:"#F7F9FC",borderRadius:8,borderLeft:`3px solid ${HOUSE_BLUE}`,textAlign:"left"}}>
                  <p style={{margin:0,fontSize:bg?11.5:12.5,lineHeight:1.75,color:bg?T.dim:T.ink}}>
                    <b style={{color:tone(o)}}>{bg?`${KR10[o.key]} — 세대 배경`:((o.retro&&PLANET_TAG_R[o.key])||PLANET_TAG[o.key])}</b>

                    {" — "}<Careful t={housePlain(PH_DIRECT[o.key][i])}/>
                    {bg&&<span style={{fontSize:11,color:T.dim}}> — 같은 세대에서 널리 나타나는 배경적 성향으로 참고한다.</span>}
                  </p>
                  {L&&(
                    <div style={{marginTop:10,display:"grid",gap:9,textAlign:"left"}}>
                      <div style={{borderLeft:`3px solid ${HOUSE_BLUE}`,paddingLeft:10}}>
                        <div style={{fontSize:13,fontWeight:850,color:HOUSE_BLUE,marginBottom:3}}>사건 · 생활에서 나타나는 일</div>
                        <div style={{fontSize:13.5,lineHeight:1.75,color:HOUSE_INK}}><Careful t={housePlain(L.ev)}/></div>
                      </div>
                      {!bg&&<>
                        <div style={{borderLeft:`3px solid ${HOUSE_INK}`,paddingLeft:10}}>
                          <div style={{fontSize:13,fontWeight:850,color:HOUSE_INK,marginBottom:3}}>심리 · 마음속에서 중요하게 여기는 것</div>
                          <div style={{fontSize:13.5,lineHeight:1.75,color:HOUSE_INK}}><Careful t={housePlain(L.psy)}/></div>
                        </div>
                        <div style={{borderLeft:`3px solid ${HOUSE_RED}`,paddingLeft:10}}>
                          <div style={{fontSize:13,fontWeight:850,color:HOUSE_RED,marginBottom:3}}>주의할 점 · 지나쳤을 때 나타나는 어려움</div>
                          <div style={{fontSize:13.5,lineHeight:1.75,color:HOUSE_INK}}><Careful t={housePlain(L.mal)}/></div>
                        </div>
                      </>}
                    </div>
                  )}
                  {!bg&&PS84[o.key]&&PS84[o.key][s]&&(
                    <p style={{margin:"4px 0 0",fontSize:11.5,lineHeight:1.8,color:T.dim}}>
                      <b style={{color:T.accent}}>방식({SIGNS[s]})</b> {PS84[o.key][s].op} <b style={{color:T.ink}}>{PS84[o.key][s].k2}</b> {PS84[o.key][s].v2}
                    </p>
                  )}
                  {bg&&OUTER_GEN[o.key]&&OUTER_GEN[o.key][s]&&(
                    <p style={{margin:"4px 0 0",fontSize:11,lineHeight:1.75,color:T.dim}}>
                      <b>세대 주제</b> {OUTER_GEN[o.key][s].era} 출생 세대가 공유하는 배경 — {OUTER_GEN[o.key][s].theme}
                    </p>
                  )}
                </div>);
              })}

              <p style={{margin:"8px 0 0",fontSize:12,lineHeight:1.7,color:T.dim,paddingLeft:10,borderLeft:`2px solid ${T.good}`}}>
                <b style={{color:HOUSE_BLUE}}>이 하우스의 강점</b> — 이 방의 일은 <b style={{color:T.ink}}>{SIGN_MODE[s]}</b> 방식으로 풀린다({SIGNS[s]}).
                {retros.map(o=>` ${o.kr.replace("R","")} 역행 — ${RETRO_BY_PLANET[o.key].gift}`).join("")}
              </p>

              {(shadow||retros.length>0)&&(
                <p style={{margin:"8px 0 0",fontSize:12,lineHeight:1.7,color:T.dim,paddingLeft:10,borderLeft:`2px solid ${T.bad}`}}>
                  <b style={{color:HOUSE_RED}}>반복되기 쉬운 어려움</b> —
                  {shadow&&<> {shadow} 같은 어려움이 '{kw}' 영역에서 반복되는지 살펴본다.</>}
                  {retros.map(o=>` ${o.kr.replace("R","")} 역행의 대가 — ${RETRO_BY_PLANET[o.key].cost}`).join("")}
                  {retros.length>0&&<> <b style={{color:T.accent}}>→ 운용</b>{retros.map(o=>` ${RETRO_BY_PLANET[o.key].use}`).join("")}</>}
                  {!clientMode&&occ.some(o=>o.key==="Pluto"&&!isBg(o))&&<> <b style={{color:T.bad}}>주의할 패턴</b> — {PLUTO_ELEM[signOf(astro.planets.Pluto.lon)%4]}</>}
                </p>
              )}

              {ch&&(
                <p style={{margin:"8px 0 0",fontSize:12,lineHeight:1.7,color:T.dim,paddingLeft:10,borderLeft:`2px solid ${T.ink}`}}>
                  <b style={{color:T.ink}}>{same?"조절하는 방법 — 제집":`조절하는 방법 → ${ch.rh}하우스(${HOUSE_SHORT[ch.rh-1]})`}</b> — {same
                    ? `이 방의 주인 ${KR10[ch.rp]}이 제집에 있다. 이 무대의 일은 스스로 통제되며 외부 조건에 덜 흔들린다 — 남 탓할 자리가 없다는 뜻이기도 하다.`
                    : <>'{kw}' 문제는 이 방 안에서 씨름해서는 풀리지 않는다. {KEY_ACTION[ch.rh-1]}</>}
                  {!hot&&` 행성이 들지 않아 이 무대는 조용히 흐르지만, 사라진 것이 아니라 주인을 통해 작동한다.`}
                </p>
              )}
            </div>
          );
        })}
        {(()=>{
          const rs=Object.entries(astro.planets).filter(([,v])=>v.retro).map(([p,v])=>`${PL_KR[p]}(${wholeHouse(v.lon,astro.asc)}하우스)`);
          if(!rs.length)return null;
          return(
            <p style={{margin:"4px 0 0",fontSize:11.5,lineHeight:1.7,color:T.dim,background:"#fff",border:`1px solid ${T.line}`,borderRadius:10,padding:"10px 12px"}}>
              <b style={{color:T.accent}}>역행(R) 안내 — {rs.join(" · ")}</b><span dangerouslySetInnerHTML={{__html:RETRO_NOTE_DIRECT}}/>
            </p>
          );
        })()}
        <div style={{marginTop:8,padding:"11px 13px",background:T.tint,border:`1px solid ${T.line}`,borderRadius:10}}>
          <p style={{margin:0,fontSize:11.5,fontWeight:700,color:T.ink}}>자주 혼동되는 무대 구분</p>
          <p style={{margin:"5px 0 0",fontSize:11,lineHeight:1.85,color:T.dim}}>
            {[["2 vs 8","내가 번 돈 / 남에게서 오는 돈(상속·투자·배우자·부채)"],
              ["3 vs 9","정보와 사실 / 의미와 체계. 근거리 / 원거리"],
              ["5 vs 11","나의 표현·개인적 애정 / 집단의 목표·동료"],
              ["6 vs 10","직무와 일과 / 사회적 지위와 평판"],
              ["4 vs 12","기억되는 뿌리 / 기억되지 않는 무의식"],
              ["7 vs 8","계약된 관계 / 융합된 관계"]].map(([a,b],n)=>(
              <span key={a}>{n?<br/>:null}<b style={{color:T.accent}}>{a}하우스</b> — {b}</span>
            ))}
          </p>
        </div>
      </>
    );
  };

  const la=A?lifeAreas(A,pa.married,baseYear,pa.gender):null;
  const ctxA=A?workCtx(pa.job,baseYear-A.sy):"work";
  const asp=A?.astro?natalAspects(A.astro):[];
  const [v91AspectTab,setV91AspectTab]=useState("core");
  const v91Aspects=useMemo(()=>swissCheck.state==="ok"?swissConsultationAspects(swissCheck.data?.bodies):[],[swissCheck]);
  const v91Ranked=useMemo(()=>[...v91Aspects].sort((a,b)=>v91AspectRank(b)-v91AspectRank(a)),[v91Aspects]);
  const syn=(coupleMode&&A?.astro&&B?.astro)?synAspects(A.astro,B.astro):[];
  const relNum=(coupleMode&&A&&B)?reduceLayer(A.sy+A.sm+A.sd+B.sy+B.sm+B.sd):null;

  return(
    <div className="frame lb-app-shell" style={{minHeight:"100vh",background:T.bg,color:T.ink,padding:"14px 13px 30px",boxSizing:"border-box",fontFamily:"var(--fb)"}}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Song+Myung&family=Gothic+A1:wght@400;500;700&display=swap');

        /* ── 폰트 교체 지점 — 이 세 줄만 바꾸면 앱 전체 서체가 바뀐다 ──
           --fd  큰 카테고리(섹션 제목·카드 헤드·숫자)   --fdw  그 서체의 굵기
           --fb  본문 전체
           Song Myung은 400 한 가지 굵기만 있는 서체다. --fdw를 700으로 올리면
           브라우저가 인위적으로 굵히면서 획이 뭉개지므로 400을 유지할 것. */
        :root{
          --fd:'Song Myung',serif;
          --fdw:400;
          --fb:'Gothic A1','Apple SD Gothic Neo',sans-serif;
        }
        input,select{background:#fff;border:1px solid ${T.line};color:${T.ink};border-radius:4px;padding:10px 11px;font-size:14px;width:100%;font-family:inherit;box-sizing:border-box;margin-top:5px;}
        /* 어떤 블록도 시트 폭을 넘지 못하게 — 카드가 바탕 밖으로 삐져나오는 것을 막는다 */
        .sheet *{box-sizing:border-box;}
        .sheet section,.sheet [data-card]{max-width:100%;}
        .sheet img,.sheet svg{max-width:100%;height:auto;}
        /* iOS의 date·time 입력칸은 고유 최소 너비가 커서 부모를 밀어낸다 — 줄어들 수 있게 푼다 */
        .sheet input,.sheet select{min-width:0;max-width:100%;}
        /* 접이식 카드 — 기본 삼각형 마커를 없애고 오른쪽에 +/− 표시를 붙인다 */
        .sheet summary{position:relative;padding-right:16px;}
        .sheet summary::-webkit-details-marker{display:none;}
        .sheet summary::marker{content:"";}
        .sheet details>summary::after{content:"+";position:absolute;right:0;top:0;color:${T.dim};font-weight:700;}
        .sheet details[open]>summary::after{content:"−";}
        @media print{.sheet details{display:block;} .sheet details>*{display:revert;}}
        .pi-grid>*{min-width:0;}
        input:focus,select:focus{outline:2px solid ${T.accent};outline-offset:1px;}
        input[type=checkbox]{width:auto;}
        button.go{background:${T.ink};color:#fff;border:none;border-radius:4px;padding:14px 0;width:100%;font-size:15px;font-weight:700;letter-spacing:0.04em;cursor:pointer;}
        button.ghost{background:transparent;color:${T.dim};border:1px solid ${T.line};border-radius:999px;padding:8px 14px;font-size:12.5px;cursor:pointer;}
        button.ghost.on{border-color:${T.ink};background:${T.ink};color:#fff;font-weight:700;}
        button.mini{background:none;border:1px solid ${T.line};border-radius:999px;padding:5px 12px;font-size:12px;cursor:pointer;color:${T.dim};}
        button:disabled{opacity:.5;cursor:default;}

        /* 섹션 헤더 — 큰 세리프 숫자 + 얇은 규칙선 */
        .sec-h{display:flex;align-items:baseline;gap:11px;margin:40px 0 14px;padding-bottom:9px;border-bottom:1px solid ${T.ink}22;scroll-margin-top:58px;}
        .sec-n{font-family:var(--fd);font-size:33px;line-height:.9;font-weight:var(--fdw);color:${T.accent};letter-spacing:-0.03em;flex-shrink:0;}
        .sec-t{font-family:var(--fd);font-size:17.5px;font-weight:var(--fdw);color:${T.ink};letter-spacing:-0.01em;line-height:1.4;}

        /* 카드 — 박스에서 좌측 룰 블록으로 */
        [data-card]{border-top:0 !important;border-right:0 !important;border-bottom:0 !important;border-left-width:3px !important;border-radius:0 3px 3px 0 !important;box-shadow:none !important;padding:12px 14px !important;margin-bottom:9px !important;}

        /* 섹션 내비게이션 */
        .secnav{position:sticky;top:0;z-index:20;display:flex;gap:5px;overflow-x:auto;padding:9px 18px;margin:0 -18px 20px;background:${T.ink};border-radius:0;scrollbar-width:none;}
        .secnav::-webkit-scrollbar{display:none;}
        .secnav button{flex:0 0 auto;display:inline-flex;align-items:center;gap:5px;background:transparent;border:1px solid #ffffff2e;color:#ffffffcc;border-radius:999px;padding:5px 11px;font-size:11.5px;cursor:pointer;white-space:nowrap;font-family:inherit;}
        .secnav button:hover{background:#ffffff1a;color:#fff;}
        .secnav b{font-family:var(--fd);font-weight:var(--fdw);font-size:12.5px;color:#fff;}
        .secnav i{width:7px;height:7px;border-radius:999px;display:inline-block;}

        /* 섹션별 카드 컬러 — 앞선 규칙을 뒤 규칙이 덮어 섹션 경계가 만들어진다 */
        ${SEC_LIST.map(([n,c])=>`#sec-${n} ~ [data-card]:not([data-tone]),#sec-${n} ~ * [data-card]:not([data-tone]){border-left-color:${c} !important;}`).join("\n        ")}

        .totop{position:fixed;right:16px;bottom:18px;z-index:30;width:42px;height:42px;border-radius:999px;border:1px solid #ffffff40;background:${T.ink};color:#fff;font-size:17px;cursor:pointer;box-shadow:0 4px 14px rgba(10,18,38,.35);}
        @media print{
          @page{size:A4;margin:14mm 12mm;}
          html,body{background:#fff !important;}
          *{-webkit-print-color-adjust:exact !important;print-color-adjust:exact !important;}
          .noprint,.secnav,.totop{display:none !important;}
          .frame{background:#fff !important;padding:0 !important;}
          .sheet{background:#fff !important;box-shadow:none !important;border-radius:0 !important;
                 max-width:none !important;width:100% !important;margin:0 !important;padding:0 !important;}
          /* 카드·섹션이 페이지 경계에서 잘리지 않게 */
          [data-card],section,details{break-inside:avoid;page-break-inside:avoid;}
          h2,h3,p{orphans:3;widows:3;}
          /* 섹션 제목은 새 페이지 상단에서 시작 (첫 섹션 제외) */
          h2.sec-h{break-before:page;page-break-before:always;break-after:avoid;page-break-after:avoid;}
          h2.sec-h:first-of-type{break-before:auto;page-break-before:auto;}
          /* 접이식 내용은 인쇄 시 모두 펼침 (open 속성 없이 CSS로) */
          details.basis>summary{display:none !important;}
          details.basis>div{display:block !important;}
          details.basis{display:block !important;border-left:2px solid #ddd;padding-left:8px;}
          details:not([open])>*:not(summary){display:revert !important;}
          /* 읽기 폭 제한 해제 — 종이 폭 활용 */
          [style*="34em"]{max-width:none !important;}
          /* 인쇄용 머리글 */
          .printhead{display:block !important;}
        }
        .printhead{display:none;}
        @media (prefers-reduced-motion:no-preference){.pulse{animation:pulse 1.4s ease-in-out infinite;}@keyframes pulse{0%,100%{opacity:.5}50%{opacity:1}}}
      `}</style>

      <div className="sheet lb-sheet" style={{maxWidth:500,width:"100%",boxSizing:"border-box",margin:"0 auto",background:T.sheet,borderRadius:18,boxShadow:"0 10px 34px rgba(10,18,38,0.30)",padding:"26px 15px 60px"}}>
        <div className="printhead" style={{borderBottom:`1px solid ${T.line}`,paddingBottom:6,marginBottom:10,fontSize:10,color:T.dim,letterSpacing:"0.1em"}}>
          三層 · LIFE BLUEPRINT{pa.name?` — ${pa.name}`:""} · {pa.solar}{pa.timeMode==="unknown"?" (출생시간 미상)":pa.timeMode==="window"?` (${pa.winStart}~${pa.winEnd})`:` ${pa.time}`} · {CITIES[pa.city][0]}
        </div>
        {/* 변경: 헤더를 편집물처럼 왼쪽 정렬하고 명확한 글자 위계를 적용한다. */}
        <header className="lb-header text-left" style={{marginBottom:16,paddingBottom:14,borderBottom:`2px solid ${T.ink}`}}>
          <div style={{display:"flex",alignItems:"baseline",justifyContent:"space-between",gap:10}}>
            <p style={{fontSize:9.5,letterSpacing:"0.34em",color:T.dim,margin:0,fontWeight:700}}>三層 · LIFE BLUEPRINT</p>
            <p style={{fontSize:9.5,letterSpacing:"0.2em",color:T.dim,margin:0}}>v10</p>
          </div>
          <h1 style={{fontFamily:"var(--fd)",fontSize:34,margin:"10px 0 6px",fontWeight:"var(--fdw)",letterSpacing:"-0.02em",lineHeight:1.1}}>인생설계도</h1>
          <p style={{color:T.dim,fontSize:12,margin:0,letterSpacing:"0.02em"}}>수비학 <span style={{color:T.accent}}>×</span> 타로 <span style={{color:T.accent}}>×</span> 점성학 자동계산 · 상담사 전용</p>
        </header>
        {/* 변경: 어두운 내비게이션을 부드러운 밝은 단계 바와 44px 터치 타깃으로 변경한다. */}
        {A&&<details className="noprint" style={{border:`1px solid ${T.line}`,borderRadius:10,marginBottom:10,padding:"9px 11px",background:"#F5F8F5"}}>
          <summary style={{cursor:"pointer",fontSize:14,fontWeight:700,minHeight:44,display:"flex",alignItems:"center",textAlign:"left"}}>Swiss 출생차트 · 천체 위치와 주요 어스펙트</summary>
          <div style={{fontSize:12,lineHeight:1.6,padding:"6px 0 5px"}}>
            <p style={{margin:"0 0 8px",color:T.dim}}>이 영역은 Swiss Ephemeris에서 받은 출생 시점의 태양·달·행성 위치를 사용한다. 기존 상담 본문·진행법·솔라리턴은 여전히 근사 계산을 사용한다. 해년의수는 별도 Swiss 월별 트랜짓을 불러온다.</p>
            {swissCheck.state==="loading"&&<p>로컬 천문 계산 중…</p>}
            {swissCheck.state==="error"&&<p role="alert" style={{color:T.bad}}>Swiss 계산 연결 실패: {swissCheck.error}. 이 영역의 정밀 결과는 표시하지 않는다. 로컬 서버를 확인한다.</p>}
            {swissCheck.state==="idle"&&<p>출생 정보를 입력하면 계산 결과를 확인할 수 있다.</p>}
            {swissNatal&&<>
              <p style={{margin:"0 0 8px",color:T.dim}}>기준 시각: {swissCheck.data.isoUtc} · JD(UT): {swissCheck.data.jdUt.toFixed(8)}{A.astro.approx?" · 출생시간 미확정(대표 시각, 확정값 아님)":""}</p>
              <div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:12,textAlign:"left"}}>
                <thead><tr><th style={{padding:6}}>천체</th><th>별자리</th><th>별자리 안의 위치</th><th>방향</th></tr></thead>
                <tbody>{swissNatal.bodies.map(r=><tr key={r.body} style={{borderTop:`1px solid ${T.line}`}}>
                  <td style={{padding:6,fontWeight:650}}>{KR10[r.body]}</td>
                  <td>{SIGNS[signOf(r.longitude)]}</td>
                  <td>{(r.longitude%30).toFixed(3)}°</td>
                  <td style={{color:r.speed<0?T.bad:T.dim}}>{r.speed<0?"역행":r.speed>0?"순행":"정지 부근"}</td>
                </tr>)}</tbody>
              </table></div>
              <div style={{marginTop:12}}><p style={{fontWeight:700,margin:"0 0 5px"}}>주요 어스펙트 (천체 간 황경 기준)</p>
                {swissNatal.aspects.length?swissNatal.aspects.slice(0,12).map((r,i)=><p key={`${r.left}-${r.right}-${i}`} style={{margin:"3px 0"}}>{KR10[r.left]} · {KR10[r.right]} — {r.label} (오브 {r.orb.toFixed(2)}°)</p>):<p>표시 기준에 해당하는 주요 어스펙트가 없다.</p>}
                {swissNatal.aspects.length>12&&<p style={{color:T.dim}}>총 {swissNatal.aspects.length}개 중 오브가 작은 12개 표시</p>}
              </div>
              <p style={{margin:"10px 0 0",color:T.dim}}>ASC·MC·하우스는 이 정밀 계산 표에 포함하지 않는다. 천문력 파일 사용 여부는 독립 검증 전이다. 상징적 해석의 과학적 예측력을 의미하지 않는다.</p>
            </>}
          </div>
        </details>}
        {A&&<SecNav/>}
        {A&&(
          <button className="totop noprint" onClick={()=>{if(typeof window!=="undefined")window.scrollTo({top:0,behavior:"smooth"});}} aria-label="맨 위로">↑</button>
        )}
        {/* 변경: 기능 탭은 좌우 스크롤 가능한 명확한 선택 상태로 표시한다. */}
        <div className="noprint lb-primary-tabs" style={{display:"flex",gap:8,marginBottom:14,flexWrap:"wrap"}}>
          <button className={`ghost ${!coupleMode?"on":""}`} onClick={()=>setCoupleMode(false)}>개인 리딩</button>
          <button className={`ghost ${coupleMode?"on":""}`} onClick={()=>{setLevel(l=>l==="client"?"pro":l);setCoupleMode(true);}}>궁합 비교</button>
          <button className={`ghost ${showSaved?"on":""}`} onClick={()=>setShowSaved(!showSaved)}>저장된 리딩 ({saved.length})</button>
          <button className="ghost" style={{marginLeft:"auto"}} onClick={()=>{if(typeof window!=="undefined")window.print();}} title="브라우저 인쇄 창에서 &quot;대상: PDF로 저장&quot;을 선택하세요">인쇄 / PDF</button>
        </div>

        {showSaved&&(
          <section className="noprint" style={{background:T.panel,border:`1px solid ${T.line}`,borderRadius:14,padding:14,marginBottom:14}}>
            <p style={{fontSize:12,letterSpacing:"0.12em",color:T.accent,margin:"0 0 8px",fontWeight:700}}>저장된 리딩 · 최대 50건 <span style={{fontWeight:400,color:T.dim,letterSpacing:0}}>· 영구 저장 {storageOK()?"지원됨 ✓":"미지원 — 이 환경에서는 세션 내에서만 유지"}</span></p>
            {saved.length===0?(
              <p style={{fontSize:12.5,color:T.dim,margin:0}}>아직 저장된 리딩이 없다. 정보를 입력한 뒤 '현재 리딩 저장'을 누르면 여기에 쌓인다.</p>
            ):saved.map(it=>(
              <div key={it.id} style={{display:"flex",alignItems:"center",gap:8,padding:"7px 0",borderTop:`1px solid ${T.line}`}}>
                <div style={{flex:1,minWidth:0}}>
                  <p style={{margin:0,fontSize:13,fontWeight:700,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                    {it.coupleMode?"👥 ":""}{it.label}
                  </p>
                  <p style={{margin:0,fontSize:10.5,color:T.dim}}>{it.at} · 기준 {it.baseYear}년</p>
                </div>
                <button className="mini" onClick={()=>loadItem(it)}>불러오기</button>
                <button className="mini" style={{color:T.accent,borderColor:T.tint2}} onClick={()=>delItem(it.id)}>삭제</button>
              </div>
            ))}
          </section>
        )}

        <div className="noprint">
          <PersonInput p={pa} setP={setPa} label={coupleMode?"PERSON A":"내담자"}/>
          {coupleMode&&<PersonInput p={pb} setP={setPb} label="PERSON B"/>}
          <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap",marginBottom:10}}>
            <label style={{fontSize:12,color:T.dim,whiteSpace:"nowrap"}}>해년의수 기준</label>
            <input type="number" value={baseYear} onChange={e=>{setBaseYear(Number(e.target.value));setAdvice(null);}} style={{width:92,marginTop:0}}/>
            <button className="ghost" style={{whiteSpace:"nowrap",marginLeft:"auto"}} onClick={saveCurrent}>저장</button>
          </div>
          {!coupleMode&&(
            <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap",marginBottom:10}}>
              <label style={{fontSize:12,color:T.dim,whiteSpace:"nowrap"}}>보기 레벨</label>
              {[["client","내담자용"],["mid","중급자용"],["pro","상급자용"]].map(([v,lb])=>(
                <button key={v} className="ghost" onClick={()=>setLevel(v)}
                  style={{whiteSpace:"nowrap",borderColor:level===v?T.accent:undefined,color:level===v?T.accent:undefined,fontWeight:level===v?700:400,background:level===v?T.tint:undefined}}>
                  {lb}{level===v?" ✓":""}
                </button>
              ))}
              <button className="ghost" onClick={()=>setCompact(c=>!c)}
                style={{whiteSpace:"nowrap",marginLeft:"auto",borderColor:compact?T.accent:undefined,color:compact?T.accent:undefined,fontWeight:compact?700:400}}>
                {compact?"요약 보기 ✓":"전체 펼치기"}
              </button>
            </div>
          )}
          {!coupleMode&&(
            <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap",marginBottom:10}}>
              <label style={{fontSize:12,color:T.dim,whiteSpace:"nowrap"}}>화면</label>
              {[[false,"준비용 리포트"],[true,"상담 시트"]].map(([v,lb])=>(
                <button key={String(v)} className="ghost" onClick={()=>setSheetView(v)}
                  style={{whiteSpace:"nowrap",borderColor:sheetView===v?T.accent:undefined,color:sheetView===v?T.accent:undefined,fontWeight:sheetView===v?700:400,background:sheetView===v?T.tint:undefined}}>
                  {lb}{sheetView===v?" ✓":""}
                </button>
              ))}
            </div>
          )}
          {storeMsg&&<p style={{fontSize:11.5,color:T.accent,margin:"0 0 8px"}}>{storeMsg}</p>}
        </div>

        {isMid&&(
          <section className="noprint" style={{background:"#F7F5F0",border:`1px dashed ${T.accent}`,borderRadius:12,padding:"10px 13px",marginBottom:12}}>
            <p style={{margin:0,fontSize:12,lineHeight:1.7,color:T.ink}}>
              <b style={{color:T.accent}}>중급자용 — 배선 완료, 아직 숨김 없음</b> — 현재는 상급자용과 화면이 같습니다. 어떤 항목을 감출지 정한 뒤 단계적으로 적용합니다.
            </p>
          </section>
        )}
        {clientMode&&(
          <section className="noprint" style={{background:T.tint,border:`1px solid ${T.accent}`,borderRadius:12,padding:"10px 13px",marginBottom:12}}>
            <p style={{margin:0,fontSize:12,lineHeight:1.7,color:T.ink}}>
              <b style={{color:T.accent}}>내담자용 보기</b> — 위기 구간·경고등·근거 계산 등 <b>상담사가 소화해서 전달할 내용</b>은 숨겨집니다. 상담사용으로 돌아가려면 위에서 중급자용 또는 상급자용을 누르세요.
            </p>
          </section>
        )}
        {A&&!coupleMode&&sheetView&&(
          <ConsultSheet P={A} year={baseYear} currentJob={pa.job}/>
        )}
        {A&&!coupleMode&&!sheetView&&clientMode&&(
          <ClientSummary P={A} baseYear={baseYear} married={pa.married}/>
        )}

        {A&&!coupleMode&&!sheetView&&!clientMode&&(
          <>
            <TimeConfBanner conf={A.timeConf}/>
            {(()=>{const tz=timeZoneNote(A.sy,A.sm,A.sd);if(!tz||clientMode)return null;
              return(<section style={{background:tz.lv==="high"?"#FBF3EC":"#F7F5F0",border:`1px solid ${tz.lv==="high"?"#E0CBB4":T.line}`,borderRadius:12,padding:"12px 14px",marginBottom:14}}>
                <p style={{margin:0,fontSize:12.5,fontWeight:700,color:"#8C6A55"}}>출생시각 보정 — {tz.label}</p>
                <p style={{margin:"5px 0 0",fontSize:11.5,lineHeight:1.75,color:T.dim}}>{tz.body}</p>
              </section>);})()}
            <CoreSeal P={A}/>
            {!clientMode&&<ReadOrder P={A}/>}
            {clientMode&&(
              <p style={{fontSize:12,lineHeight:1.8,color:T.ink,background:T.panel,border:`1px solid ${T.line}`,borderRadius:12,padding:"12px 14px",marginBottom:14}}>
                이 자료는 태어난 순간의 하늘과 수(數)를 상징 체계로 읽어 낸 <b>삶의 지도</b>입니다.
                정해진 운명을 알려 주는 것이 아니라, 타고난 결과 그 결이 잘 쓰일 자리를 비추는 참고 자료입니다.
                읽다가 <b>지금의 나와 다르게 느껴지는 부분</b>이 있다면 그것도 중요한 정보이니, 상담 중에 편히 말씀해 주세요.
              </p>
            )}
            <div className="lb-sec-copy" style={{textAlign:"left"}}>
            <H>1 · 나는 누구인가 — 세 개의 층</H>
            {A.astro?.approx&&(
              <p style={{fontSize:11.5,color:T.accent,margin:"0 0 10px"}}>
                ⚠ 출생시간 미상 — 정오 기준 계산. 상승점·MC·하우스는 생략되고, 달의 별자리는 ±6° 오차가 있을 수 있다.
              </p>
            )}
            <LayerBlock P={A}/>
            <Big3 P={A}/>
            {(()=>{
              const er=empressRadius(A);
              if(!er)return null;
              const col=er.level==="좁음"?T.bad:er.level==="넓음"?T.good:T.accent;
              return(
                <div data-card style={{background:"#fff",border:`1.5px solid ${col}`,borderRadius:12,padding:"12px 15px",marginTop:10}}>
                  <p style={{margin:0,fontSize:15,lineHeight:1.55}}>
                    <b style={{fontFamily:"var(--fd)",fontSize:18,color:col}}>여황제(3)의 돌봄 반경 — {er.level||"판정 보류"}</b>
                    <span style={{fontSize:12.5,color:T.dim}}>{"  "}{er.layers.join("·")}층에 3번{er.n>1?` · ${er.n}개 층 중복`:""}</span>
                  </p>
                  <p style={{margin:"5px 0 0",fontSize:14,lineHeight:1.7,color:T.ink}}>
                    3번 카드는 <b style={{color:"#426D91"}}>돌보고 키우는 성향</b>을 뜻한다. 어디까지 돌보는지는 별자리 해석과 함께 살펴본다.
                    {er.n>1&&<> <b style={{color:T.bad}}>3번이 {er.n}개 층에 겹쳤다</b> — 이 앱의 분류 기준에서는 돌봄 범위를 조금 좁게 판정한다.</>}
                  </p>
                  {er.noAstro?(
                    <p style={{margin:"6px 0 0",fontSize:13,color:T.accent}}>출생 정보가 없어 반경은 산출하지 못했다.</p>
                  ):(
                    <>
                      {er.reasons.map((r,i)=>(
                        <p key={i} style={{margin:"4px 0 0",fontSize:14,lineHeight:1.7,color:T.ink,paddingLeft:9,borderLeft:`2px solid ${r.v<0?T.bad:T.good}`}}>
                          <b style={{color:r.v<0?T.bad:T.good}}>{r.v<0?"좁힘":"넓힘"}</b> <Careful t={r.t}/>
                        </p>
                      ))}
                      {!er.reasons.length&&<p style={{margin:"6px 0 0",fontSize:13,color:T.dim}}>반경을 좁히거나 넓히는 뚜렷한 신호가 없다 — 상황에 따라 달라지는 유형이다.</p>}
                      <p style={{margin:"7px 0 0",paddingTop:6,borderTop:`1px solid ${T.line}`,fontSize:15,lineHeight:1.65,color:T.dim}}>
                        {er.level==="좁음"
                          ?"가까운 사람에게는 정성을 쏟지만 그 밖의 사람에게는 관심을 두기 어려울 수 있다. 실제 돌봄의 범위를 확인한다."
                          :er.level==="넓음"
                          ?"가까운 사람을 넘어 여러 사람을 챙길 수 있다. 자신의 시간과 체력도 함께 돌보는지 확인한다."
                          :"상황과 상대에 따라 돌봄의 범위가 달라질 수 있다. 어느 때 달라지는지 확인한다."}
                        {" "}이 분류는 사람의 좋고 나쁨을 판단하지 않는다.
                      </p>
                    </>
                  )}
                </div>
              );
            })()}
            <div data-card style={{background:T.tint,border:`1.5px solid ${T.accent}`,borderRadius:12,padding:"12px 14px",marginTop:10,textAlign:"left"}}>
              <p style={{margin:0,fontSize:13,letterSpacing:"0.03em",color:T.dim,fontWeight:700}}>종합 정의 — 세 층 × 별자리</p>
              <p style={{margin:"5px 0 0",fontSize:15,lineHeight:1.7,textAlign:"left"}}>{personaSummary(A)}</p>
            </div>
            </div>

            <div className="lb-v89-year"><div className="lb-v89-heading"><H>2 · 해년의수 — {baseYear}년부터 5년 (Swiss 트랜짓 참고)</H></div>
            <p style={{fontSize:13.5,color:T.dim,margin:"0 0 10px",lineHeight:1.7}}>
              해년의수는 해마다 주목할 <b>변화의 주제</b>를 살펴보는 상징적 해석이다. 각 연도에서 <b style={{color:"#175CD3"}}>주요 흐름</b>과 <b style={{color:"#B42318"}}>주의할 점</b>을 먼저 확인한다. 전환 시기는 개인에 따라 다르게 느껴질 수 있다.
            </p>
            <p className="lb-v89-status" role="status">{swissYears.state==="loading"?"Swiss 트랜짓 계산 중 — 연도 카드의 점성학 해석은 잠시 보류한다.":swissYears.state==="error"?`Swiss 트랜짓 연결 오류: ${swissYears.error === "Not found" ? "구버전 로컬 서버가 실행 중입니다. v89 브리지로 교체하고 서버를 재시작하세요." : swissYears.error} — 수비학 카드 내용만 표시한다.`:swissYears.state==="ok"?"Swiss Ephemeris 월별 트랜짓 적용 · 태양·달·금성 기준 · 매월 1일 표본(정확한 형성일 아님)":"Swiss 트랜짓 준비 중 — 수비학 카드 내용만 표시한다."}</p>
            <div className="lb-v89-five-year" style={{display:"grid",gridTemplateColumns:"repeat(5,minmax(0,1fr))",gap:5,marginBottom:12}}>
              {A.years.map(yr=>{
                const on=yr.y===baseYear;
                return(
                <div key={yr.y} style={{background:on?T.tint:"#fff",border:`1px solid ${on?T.accent:T.line}`,borderTop:`3px solid ${ELEM_COLOR[cardElem(yr.main)]}`,borderRadius:8,padding:"9px 4px",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:3,width:"100%",height:"100%",boxSizing:"border-box",textAlign:"center"}}>
                  <span style={{fontSize:12.5,color:T.dim,lineHeight:1.2,letterSpacing:"-0.02em",textAlign:"center",width:"100%"}}>{yr.y}</span>
                  <span style={{fontFamily:"var(--fd)",fontSize:20,fontWeight:"var(--fdw)",lineHeight:1.05,color:on?T.accent:T.ink,textAlign:"center",width:"100%"}}>{yr.main}</span>
                  <span style={{fontSize:12.5,color:T.dim,wordBreak:"keep-all",overflowWrap:"break-word",lineHeight:1.3,minHeight:"2.6em",display:"grid",alignContent:"center",textAlign:"center",width:"100%",padding:"0 1px"}}>{card(yr.main)[0]}</span>
                </div>);
              })}
            </div>
            {annotateYears(swissYearRows).map(yr=>{
              const tt=yearTone(yr);
              const ce=swissYears.state==="ok"?counterEventOf(yr,ctxA):null;
              const pg=A.astro&&!A.astro.approx?progInfo(A,yr.y):null;
              const sr=A.astro&&!A.astro.approx?solarReturn(A,yr.y):null;
              const prevC=card(reduceLayer((yr.y-1)+A.sm+A.sd).main)[0];
              const nextC=card(reduceLayer((yr.y+1)+A.sm+A.sd).main)[0];
              return(
                <details key={yr.y} open={!compact||yr.y===baseYear} data-card data-tone="1" style={{background:"#fff",border:`1px solid ${T.line}`,borderLeft:`4px solid ${tt.color}`,borderRadius:10,padding:"12px 14px",marginBottom:8,textAlign:"left"}}>
                  <summary style={{cursor:"pointer",listStyle:"none",margin:0,fontSize:15,lineHeight:1.65}}>
                    <b style={{color:T.accent}}>{yr.y} · {card(yr.main)[0]}</b> <b style={{color:ELEM_COLOR[cardElem(yr.main)],fontSize:11}}>({ELEMS[cardElem(yr.main)]})</b> — {YEAR_SENT[yr.main===22?0:yr.main]}
                    {compact&&yr.y!==baseYear&&<span style={{fontSize:12.5,color:T.dim}}> · 펼치기</span>}
                  </summary>

                  {swissYears.state==="ok"&&<p style={{margin:"9px 0 0",fontSize:13,lineHeight:1.6}}>
                    <b style={{color:tt.color}}>{tt.label}</b>{tt.char&&<span style={{color:T.dim}}> · {tt.char}</span>}{tt.heavy&&<span style={{color:T.bad}}> · 강한 마찰 신호</span>}{tt.boon&&<span style={{color:T.good}}> · 강한 순풍 신호</span>}
                  </p>}
                  <p style={{margin:"3px 0 0",fontSize:14,lineHeight:1.7}}>
                    <b style={{color:"#175CD3"}}>주요 흐름</b> — {swissYears.state==="ok"?strongEventOf(yr,ctxA):YEAR_STRONG[yr.main===22?0:yr.main]}
                    {ce&&<span style={{color:ce.hard?T.bad:ce.tone==="c"?T.ink:T.good}}> · 함께 {ce.hard?"마찰":ce.tone==="c"?"직격":"순풍"}: {ce.ev}</span>}
                  </p>

                  {CARD_TOPIC[yr.main===22?0:yr.main]&&(()=>{const t=CARD_TOPIC[yr.main===22?0:yr.main];return(
                    <p style={{margin:"7px 0 0",fontSize:14,lineHeight:1.7,color:T.dim,paddingLeft:9,borderLeft:`2px solid ${T.line}`}}>
                      <b style={{color:T.ink}}>이 해의 영역별 기조</b>
                      {t.jobs&&<><br/><b>일</b> — {t.jobNote}</>}
                      {t.money&&<><br/><b>돈</b> — {t.money}</>}
                      {t.love&&<><br/><b>관계</b> — {t.love}</>}
                      {t.health&&<><br/><b>몸</b> — {t.health}</>}
                    </p>);})()}


                  <p style={{margin:"7px 0 0",fontSize:14,lineHeight:1.7,background:"#F2EBE0",borderRadius:8,padding:"6px 10px"}}>
                    <b style={{color:"#B42318"}}>주의할 점</b> — {YEAR_FORBID[yr.main===22?0:yr.main]}
                  </p>

                  <details style={{marginTop:10,border:`1px solid ${T.line}`,borderRadius:9,background:"#FAF9F6",overflow:"hidden"}}>
                    <summary style={{cursor:"pointer",padding:"12px 13px",minHeight:44,boxSizing:"border-box",fontSize:14,fontWeight:700,color:T.accent,textAlign:"left"}}>
                      점성학 계산 근거 · 상세 해석 ▾
                    </summary>
                    <div style={{borderTop:`1px solid ${T.line}`,padding:"10px 13px 13px",display:"grid",gap:11,fontSize:13.5,lineHeight:1.7,textAlign:"left"}}>
                      <div>
                        <b>① 해년수와 타로 카드</b>
                        <p style={{margin:"4px 0 0"}}>해년수 {yr.main} · {card(yr.main)[0]} · {ELEMS[cardElem(yr.main)]} 원소</p>
                        <p style={{margin:"4px 0 0",color:T.dim}}>카드의 주제: {YEAR_SENT[yr.main===22?0:yr.main]}</p>
                      </div>
                      <div style={{borderTop:`1px solid ${T.line}`,paddingTop:9}}>
                        <b>② Swiss 주요 트랜짓 · 어스펙트</b>
                        {swissYears.state!=="ok"?<p style={{margin:"4px 0 0",color:"#B42318",fontWeight:700}}>Swiss 계산값이 없어 트랜짓을 표시하지 않는다.</p>:yr.pri?(
                          <>
                            <p style={{margin:"4px 0 0",fontWeight:600}}>{PL_KR[yr.pri.planet]} {ASPECT_SYM[yr.pri.aspect]} 출생 {PT_MEAN[yr.pri.pt]}</p>
                            <p style={{margin:"3px 0 0",color:T.dim}}>{yr.pri.aspect} · 오브 {yr.pri.orb.toFixed(1)}° · 매월 1일 표본 중 최소 오브 {yr.pri.m}월 (정확한 형성일 아님)</p>
                            <p style={{margin:"5px 0 0"}}>{TR_MEAN[yr.pri.planet]}의 주제를 {PT_MEAN[yr.pri.pt]} 영역과 함께 살펴본다. 이는 사건 발생을 확정하는 정보가 아니다.</p>
                            {yr.sec&&<p style={{margin:"5px 0 0",color:T.dim}}>추가 참고: {PL_KR[yr.sec.planet]} {ASPECT_SYM[yr.sec.aspect]} 출생 {PT_MEAN[yr.sec.pt]} · 오브 {yr.sec.orb.toFixed(1)}°</p>}
                          </>
                        ):<p style={{margin:"4px 0 0",color:T.dim}}>{!A.astro?"출생차트 정보가 없어 트랜짓을 계산하지 않았다.":"이 해에 선택된 주요 트랜짓이 없다."} 해년수 카드의 주제를 중심으로 읽는다.</p>}
                      </div>
                      {(pg||sr)&&<div style={{borderTop:`1px solid ${T.line}`,paddingTop:9}}>
                        <b>③ 진행법 · 솔라리턴 (기존 근사 계산, Swiss 미적용)</b>
                        {pg&&<p style={{margin:"4px 0 0"}}>진행 달: {SIGNS[pg.sign]}{Number.isFinite(pg.house)?` · ${pg.house}하우스 (${HOUSE_SHORT[pg.house-1]})`:""}{pg.move?` · ${pg.move.m}월 ${pg.move.from}→${pg.move.to}하우스 이동`:""}</p>}
                        {pg?.sunShift&&<p style={{margin:"4px 0 0"}}>진행 태양 별자리 변화: {SIGNS[pg.sunShift.from]} → {SIGNS[pg.sunShift.to]}</p>}
                        {sr&&Number.isInteger(sr.ascSign)&&<p style={{margin:"4px 0 0"}}>솔라리턴 상승궁: {SIGNS[sr.ascSign]} · {SIGN_MODE[sr.ascSign]}{Number.isFinite(sr.natalHouse)?` · 출생차트 ${sr.natalHouse}하우스 (${HOUSE_SHORT[sr.natalHouse-1]})`:""}</p>}
                        {sr&&!Number.isInteger(sr.ascSign)&&<p style={{margin:"4px 0 0",color:T.dim}}>솔라리턴 상승궁·하우스는 출생시간 정보가 충분할 때 표시한다.</p>}
                      </div>}
                      <div style={{borderTop:`1px solid ${T.line}`,paddingTop:9}}>
                        <b>④ 순풍 · 마찰의 판정 근거 {swissYears.state==="ok"?"(Swiss 트랜짓 반영)":"(카드 기준만)"}</b>
                        <p style={{margin:"4px 0 0"}}>{tt.label} · 자체 가중치 지표 순풍 {tt.pct} : 마찰 {100-tt.pct}</p>
                        <p style={{margin:"4px 0 0",color:T.dim}}>카드 가중치, 트랜짓 행성·어스펙트·오브를 합산한 내부 비교값이다. 실제 사건의 발생 확률은 아니다.</p>
                        {(tt.heavy||tt.boon)&&<p style={{margin:"4px 0 0"}}>{tt.heavy?"강한 마찰 신호: 핵심 지점에 가까운 긴장 접촉이 있다. ":""}{tt.boon?"강한 순풍 신호: 핵심 지점에 가까운 목성 접촉이 있다.":""}</p>}
                      </div>
                      <div style={{borderTop:`1px solid ${T.line}`,paddingTop:9}}>
                        <b>⑤ 해석을 연결한 이유</b>
                        <p style={{margin:"4px 0 0"}}>해년수 {yr.main}의 {card(yr.main)[0]} 카드 주제{yr.pri?`와 ${PL_KR[yr.pri.planet]}의 ${TR_MEAN[yr.pri.planet]} 주제`:""}{pg&&Number.isFinite(pg.house)?`, 진행 달의 ${pg.house}하우스 (${HOUSE_SHORT[pg.house-1]})`:""}를 함께 참고한다. 위의 ‘주요 흐름’과 ‘주의할 점’을 상담에서 점검할 때 사용하는 상징적 근거이다.</p>
                        <p style={{margin:"5px 0 0",color:T.dim}}>연초·연말 참고: 1~3월에는 이전 카드 ‘{prevC}’, 10~12월에는 다음 카드 ‘{nextC}’의 주제도 함께 살펴본다. 실제 사건 발생 월을 뜻하지 않는다.</p>
                      </div>
                      <p style={{margin:0,padding:"9px 10px",background:T.tint,borderRadius:7,fontSize:12.5,color:T.dim}}>수비학·타로·점성학의 상징을 연결한 상담용 해석이다. 계산값과 해석은 구분해 읽으며, 특정 사건의 발생 여부·시기·확률을 입증하는 자료는 아니다.</p>
                    </div>
                  </details>
                </details>
              );
            })}
            <p style={{fontSize:12.5,color:T.dim,margin:"4px 0 10px",lineHeight:1.6}}>순풍·마찰은 앱 내부의 상징적 비교 지표이며 실제 사건 발생 확률이 아니다. 연도별 계산 근거는 각 카드에서 펼쳐 확인할 수 있다.</p>

            </div>
            <div className="lb-sec-copy" style={{textAlign:"left"}}>
            <p role="status" style={{fontSize:12,lineHeight:1.7,color:A?.astro?.angleSource==="swiss-houses"||swissMatched?"#175CD3":"#B42318",textAlign:"left",margin:"4px 0 12px"}}>
              {swissMatched
                ? `v92 · 행성 10개: Swiss / ASC·MC·홀사인: ${A?.astro?.angleSource==="swiss-houses"?"Swiss 정밀 계산":A.astro?.approx?"출생시간 미상 — 확정 불가":swissHouse.state==="error"?`Swiss 연결 실패(${swissHouse.error}) — 임시 근사 표시`:"Swiss 확인 대기 — 임시 근사 표시"} / 일부 연도별 보조 계산: 기존 근사 방식`
                : `v92 · Swiss 출생값 ${swissCheck.state==="error"?`연결 오류(${swissCheck.error})`:"확인 대기"} — 현재 행성 해석은 기존 근사 계산으로 표시됨. ASC·MC는 ${A?.astro?.angleSource==="swiss-houses"?"Swiss 정밀 계산":swissHouse.state==="error"?`연결 실패(${swissHouse.error}) — 임시 근사`:"미확인 또는 근사 계산"}.`}
            </p>
            <H>3 · 원소 균형</H>
            {A.astro?(
              <>
                {(()=>{
                  const eb=elementBalance(A.astro);
                  return(
                    <div data-card style={{background:"#fff",border:`1px solid ${T.line}`,borderRadius:12,padding:"13px 15px",marginTop:8}}>
                      <p style={{margin:"0 0 8px",fontSize:11,letterSpacing:"0.1em",color:T.dim}}>원소 균형 — 강한 기운과 부족한 기운{A.astro.approx?" (출생시간 미상 — 상승 제외 근사치)":""}</p>
                      <div className="lb-elem-bars" style={{display:"flex",gap:6,marginBottom:9}}>
                        {ELEMS.map((nm,i)=>{
                          const pct=Math.round(eb.tot[i]/eb.sum*100);
                          const on=i===eb.hi&&!eb.flat,off=i===eb.lo&&!eb.flat;
                          return(
                            <div key={nm} style={{flex:1,textAlign:"center"}}>
                              <div style={{height:52,display:"flex",alignItems:"flex-end"}}>
                                <div style={{width:"100%",height:`${Math.max(8,Math.min(100,pct*2.2))}%`,background:ELEM_COLOR[i],opacity:on?1:off?0.25:0.55,borderRadius:"4px 4px 0 0"}}/>
                              </div>
                              <p style={{margin:"3px 0 0",fontSize:10.5,fontWeight:on||off?800:400,color:on?ELEM_COLOR[i]:off?T.bad:T.dim}}>{nm} {pct}%</p>
                            </div>
                          );
                        })}
                      </div>
                      <p style={{margin:"0 0 8px",fontSize:10.5,color:T.dim,lineHeight:1.6}}>태양·달(가중 3), 상승(2), 수성·금성·화성(2), 목성·토성(1), 외행성(0.5)의 별자리 원소를 합산한 분포다. 세대 공유 행성은 낮게 반영했다.</p>
                      {eb.flat
                        ?<p style={{margin:0,fontSize:12.5,lineHeight:1.75}}>네 원소가 고르게 분포된 <b>균형형 차트</b>다 — 특정 기운의 과잉이나 결핍보다, 상황에 따라 필요한 원소를 골라 쓰는 유연함이 이 차트의 자원이다.</p>
                        :<>
                          <p style={{margin:"0 0 6px",fontSize:12.5,lineHeight:1.75}}><b style={{color:ELEM_COLOR[eb.hi]}}>강한 기운 · {ELEMS[eb.hi]}</b> — {ELEM_STRONG[eb.hi]}</p>
                          <p style={{margin:"0 0 8px",fontSize:12.5,lineHeight:1.75}}><b style={{color:T.bad}}>부족한 기운 · {ELEMS[eb.lo]}</b> — {ELEM_LACK[eb.lo]}</p>
                          <div style={{background:T.tint,borderRadius:8,padding:"10px 12px"}}>
                            <p style={{margin:0,fontSize:12.5,lineHeight:1.75}}><b style={{color:T.accent}}>{ELEMS[eb.lo]} 기운 보충 처방</b> — {ELEM_REMEDY[eb.lo]}</p>
                          </div>
                        </>}
                    </div>
                  );
                })()}
              </>
            ):<p style={{color:T.dim,fontSize:13}}>출생시간 입력 시 자동 계산된다.</p>}

            {A.astro&&(
              <>
                <H>4 · 애스펙트 — 내 안의 행성들이 맺는 관계</H>
                <div className="lb-v91-aspects" style={{textAlign:"left"}}>
                  <p style={{margin:"0 0 9px",fontSize:13,lineHeight:1.8,color:T.dim,textAlign:"left"}}>행성 사이의 각도를 통해 함께 나타날 수 있는 성향을 살펴본다. 상담에서 실제 경험과 일치하는지 확인하는 상징적 해석이다. 상담 전 핵심 판독은 요약으로, 이곳은 자세한 관계 설명으로 사용한다.</p>
                  {swissCheck.state!=="ok"?(
                    <div role="status" style={{padding:"12px 14px",border:`1px solid ${T.line}`,borderRadius:10,textAlign:"left",color:swissCheck.state==="error"?T.bad:T.dim}}>
                      {swissCheck.state==="error"?`Swiss Ephemeris 연결 오류: ${swissCheck.error} — 정밀 애스펙트를 표시하지 않는다.`:"Swiss Ephemeris 출생차트 계산 중 — 정밀 애스펙트가 준비되면 표시한다."}
                    </div>
                  ):(
                    <>
                      <div style={{display:"flex",gap:7,flexWrap:"wrap",marginBottom:12}}>
                        {[["core","핵심 관계 3개"],["all",`전체 관계 ${v91Aspects.length}개`],["basis","계산 근거"]].map(([key,label])=>(
                          <button type="button" key={key} onClick={()=>setV91AspectTab(key)} aria-pressed={v91AspectTab===key}
                            style={{padding:"9px 12px",borderRadius:9,border:`1px solid ${v91AspectTab===key?"#175CD3":T.line}`,background:v91AspectTab===key?"#175CD3":"#fff",color:v91AspectTab===key?"#fff":T.ink,fontWeight:700,fontSize:12.5,cursor:"pointer",textAlign:"center"}}>{label}</button>
                        ))}
                      </div>
                      {v91AspectTab==="basis"?(
                        <div style={{padding:"12px 14px",background:"#F6F7F9",borderRadius:10,lineHeight:1.85,textAlign:"left",fontSize:13}}>
                          <b>Swiss Ephemeris 출생 경도 기준</b>
                          <p style={{margin:"6px 0"}}>기준 시각: {swissCheck.data.isoUtc} · JD(UT): {swissCheck.data.jdUt.toFixed(8)}</p>
                          <p style={{margin:"6px 0"}}>비교 대상: 태양·달·수성·금성·화성과 그보다 뒤에 놓인 행성의 쌍. 합·대립·스퀘어·트라인·섹스타일·퀸컹스 및 기존 허용 오브를 적용한다. 전체 행성 쌍을 망라한 목록은 아니다.</p>
                          {A.astro.approx&&<p style={{color:T.bad,margin:"6px 0"}}>출생시간이 확정되지 않아 달과 관련된 각도는 대표 시각의 참고값이다.</p>}
                          {v91Ranked.map((r,i)=><p key={`${r.a}-${r.b}-${i}`} style={{margin:"4px 0",borderTop:`1px solid ${T.line}`,paddingTop:5}}>{KR10[r.a]} {ASPECT_SYM[r.nm]} {KR10[r.b]} · {r.nm} · 오브 {r.o.toFixed(2)}°</p>)}
                        </div>
                      ):v91Ranked.length===0?(
                        <p style={{color:T.dim,fontSize:13}}>현재 표시 기준에 해당하는 주요 애스펙트가 없다.</p>
                      ):(v91AspectTab==="core"?v91Ranked.slice(0,3):v91Ranked).map((r,i)=>{
                        const info=v91AspectExplanation(r);
                        return <div key={`${r.a}-${r.b}-${r.nm}`} data-card data-tone={info.difficult?"h":"s"} style={{background:"#fff",border:`1px solid ${T.line}`,borderLeft:`3px solid ${info.difficult?"#B42318":"#175CD3"}`,borderRadius:10,padding:"13px 15px",marginBottom:9,textAlign:"left"}}>
                          <p style={{margin:"0 0 10px",fontWeight:800,fontSize:15,color:T.ink,textAlign:"left"}}>{KR10[r.a]} {ASPECT_SYM[r.nm]} {KR10[r.b]} <span style={{fontSize:12,fontWeight:500,color:T.dim}}>· {info.theme} · {r.nm}</span></p>
                          <div style={{display:"grid",gap:9,textAlign:"left"}}>
                            <div><b style={{color:"#175CD3"}}>핵심 성향</b><p style={{margin:"3px 0 0",lineHeight:1.8,fontSize:13.5}}>{info.strength}</p></div>
                            {info.difficult&&<div><b style={{color:"#B42318"}}>어려워질 수 있는 부분</b><p style={{margin:"3px 0 0",lineHeight:1.8,fontSize:13.5}}>{info.difficulty}</p></div>}
                            <div><b style={{color:"#167347"}}>조절하는 방법</b><p style={{margin:"3px 0 0",lineHeight:1.8,fontSize:13.5}}>{info.guide}</p></div>
                          </div>
                        </div>;
                      })}
                      {v91AspectTab==="core"&&v91Aspects.length>3&&<p style={{fontSize:12,color:T.dim,margin:"0 0 7px"}}>나머지 {v91Aspects.length-3}개는 '전체 관계'에서 확인할 수 있다. 우선순위는 개인 행성과 오브 등을 기준으로 한 상담용 정렬이다.</p>}
                    </>
                  )}
                </div>
              </>
            )}

            {A.astro&&!A.astro.approx&&(
              <>
                <H>5 · 하우스 12궁 — 에너지의 지도</H>
                <ChartWheel astro={A.astro}/>
                <HouseGrid astro={A.astro}/>
              </>
            )}
            {A.astro?.approx&&(
              <>
                <H>5 · 하우스 12궁</H>
                <p style={{fontSize:12.5,color:T.dim,lineHeight:1.7}}>
                  하우스는 출생시간과 출생지로 계산되는 '삶의 무대 배치'라, 시간을 모르면 산출할 수 없다.
                  출생시간을 확인할 방법(출생증명서, 산모수첩, 가족의 기억)이 생기면 입력 즉시 12개 무대가 표시된다.
                </p>
              </>
            )}

            </div>
            {A.astro&&(
              <div className="lb-sec679">
                <H>6 · 강한 기능과 약한 기능, 그리고 성패가 갈리는 자리</H>
                <p className="lb-note">품위는 어떤 기능이 비교적 수월한지, 어떤 기능은 연습이 필요한지를 보여 줍니다. 등급이 없는 행성은 이 기준에서 중립일 뿐, 성격 전체가 고르게 작동한다는 뜻은 아닙니다.</p>
                {(()=>{
                  const rows=[["Sun",A.astro.sun],["Moon",A.astro.moon],...Object.entries(A.astro.planets).filter(([p])=>DIGNITY[p]).map(([p,v])=>[p,v.lon])];
                  const sp=rows.map(([p,l])=>({p,s:signOf(l),dg:dignity(p,signOf(l))})).filter(r=>r.dg);
                  const strongs=sp.filter(r=>r.dg==="dom"||r.dg==="ex");
                  const weaks=sp.filter(r=>r.dg==="det"||r.dg==="fall");
                  const card=(r)=>{
                    const read=dignityRead(r.p,r.s,r.dg);
                    const tone=read.strong?LB_BLUE:LB_RED;
                    return(
                      <div key={r.p} data-card data-tone={read.strong?"s":"w"} style={{background:read.strong?"#F4F8FD":"#fff",borderLeft:`3px solid ${tone}`,padding:"12px 14px",marginBottom:8}}>
                        <p className="lb-sub" style={{marginTop:0,color:LB_INK}}>{KR10[r.p]} · {SIGNS[r.s]} <span style={{color:tone}}>[{DIG_LABEL[r.dg]}]</span></p>
                        <p className="lb-sub" style={{color:tone}}>{read.strong?"강점":"어려움"}</p>
                        <p className="lb-body">{read.point}</p>
                        <p className="lb-sub" style={{color:LB_GREEN}}>{read.strong?"쓰는 방향":"훈련 방향"}</p>
                        <p className="lb-body" style={{marginBottom:0}}>{read.guide}</p>
                      </div>
                    );
                  };
                  return(
                    <>
                      <p className="lb-body" style={{background:"#F4F8FD",padding:"9px 12px"}}>
                        <b style={{color:LB_BLUE}}>수월한 기능</b> — {strongs.length?strongs.map(r=>PLANET_FUNC[r.p]).join(" · "):"이 기준에서는 두드러지지 않습니다"}.
                        {" "}<b style={{color:LB_RED}}>연습이 필요한 기능</b> — {weaks.length?weaks.map(r=>PLANET_FUNC[r.p]).join(" · "):"이 기준에서는 두드러지지 않습니다"}.
                      </p>
                      <p className="lb-sub" style={{color:LB_BLUE}}>잘 발휘되는 기능</p>
                      {strongs.length?strongs.map(card):<p className="lb-note">본좌·고양으로 잡힌 행성은 없습니다.</p>}
                      <p className="lb-sub" style={{color:LB_RED}}>의식적으로 보완할 기능</p>
                      {weaks.length?weaks.map(card):<p className="lb-note">손상·쇠약으로 잡힌 행성은 없습니다.</p>}
                    </>
                  );
                })()}
                <p className="lb-sub" style={{color:LB_GREEN}}>성패가 갈리는 자리</p>
                {A.astro.approx?(
                  <p className="lb-note">출생시간이 확정되지 않아 하우스 체인은 확정하지 않습니다.</p>
                ):(
                  <>
                    <p className="lb-note">돈·인연·큰돈·커리어는 방의 주인이 실제로 머무는 방에서 갈리는 경우가 많습니다.</p>
                    {CHAIN_TARGETS.map(([hn,label])=>{
                      const c=chainOf(A.astro,hn);
                      const self=c.rh===hn;
                      return(
                        <div key={hn} data-card data-tone="chain" style={{background:"#fff",borderLeft:`3px solid ${LB_GREEN}`,padding:"12px 14px",marginBottom:8}}>
                          <p className="lb-note" style={{margin:0,color:"#5C6570"}}>{hn}하우스 · {label}</p>
                          <p className="lb-sub" style={{color:LB_INK}}>주인 {KR10[c.rp]} → {c.rh}하우스 · {HOUSE_SHORT[c.rh-1]}</p>
                          <p className="lb-body" style={{marginBottom:0}}>
                            {self
                              ?"주인이 자기 방에 있습니다. 이 주제는 바깥 조건보다 본인이 어떻게 다루느냐에 따라 결과가 달라지기 쉽습니다. 전부 맡기기보다 기준을 직접 잡아 두는 편이 맞습니다."
                              :<>이 주제는 <b style={{color:LB_GREEN}}>{HOUSE_ACTION[c.rh-1]}</b> 풀리는 쪽에 가깝습니다. 다른 곳에만 힘을 쓰면 결과가 더디게 느껴질 수 있습니다.</>}
                          </p>
                        </div>
                      );
                    })}
                  </>
                )}
              </div>
            )}

            {(la||A.astro?.approx)&&(
              <div className="lb-sec679">
                <H>7 · 인생 전반의 영역</H>
                {la&&Object.entries(la).filter(([k])=>!k.startsWith("__")).filter(([k])=>!(clientMode&&k.includes("경고등"))).map(([k,v])=>(
                  <LifeAreaCard key={k} name={k} value={v} basis={la.__basis&&la.__basis[k]} hideBasis={clientMode} person={A}/>
                ))}
                {A.astro?.approx&&(
                  <p className="lb-note">인생 전반의 영역(직업·인연·금전 등)은 하우스 기반이라 출생시간 입력 시 표시됩니다.</p>
                )}
              </div>
            )}

            <H>8 · {baseYear}년 핵심 조언</H>
            <div className="noprint" style={{marginBottom:8}}>
              <button className="go" disabled={loading} onClick={()=>makeAdvice()}>
                {loading?"세 체계를 통합해 읽는 중…":"AI 핵심 조언 생성"}
              </button>
            </div>
            {loading&&<p className="pulse" style={{fontSize:12.5,color:T.dim}}>수비학 × 타로 × 점성학의 원자료를 통합하는 중이다…</p>}
            {advErr&&<p style={{fontSize:11.5,color:T.bad,margin:"0 0 6px"}}>{advErr}</p>}
            {advice&&(
              <div data-card style={{background:T.tint,border:`1.5px solid ${T.accent}`,borderRadius:12,padding:"14px 16px"}}>
                {fromCache&&<p style={{margin:"0 0 6px",fontSize:10.5,color:T.dim}}>저장된 조언 (같은 입력값) — 새로 생성하려면 아래 '다시 생성'</p>}
                <p style={{margin:0,fontSize:13,lineHeight:1.85,whiteSpace:"pre-wrap"}}>{advice}</p>
                <button className="mini noprint" style={{marginTop:9}} onClick={()=>makeAdvice(true)}>다시 생성</button>
              </div>
            )}

            {!clientMode&&(<div className="lb-sec679 lb-crisis">
<H>9 · 위기 구간</H>
            {(()=>{
              if(!A.astro)return <p style={{fontSize:12,color:T.dim,margin:0}}>출생 정보로 천체 계산이 되어야 위기 구간을 산출할 수 있다.</p>;
              const from=baseYear-2,to=baseYear+18;
              const cs=crisisScan(A,from,to);
              const pf=profectionCrisis(A,baseYear,to);
              const usedP=[...new Set(cs.wins.map(w=>w.p))];
              return(
                <>
                  <p style={{fontSize:12,color:T.dim,margin:"0 0 10px",lineHeight:1.7}}>
                    {from}~{to}년 중 쉽게 바꾸기 어려운 압박이 생기는 시기이다. <b>사건 예언이 아니라 가설</b>이며, 무엇이 일어나는가보다 <b>무엇을 점검하라는 신호인가</b>가 상담의 핵심이다.
                  </p>

                  {cs.rets.length>0&&cs.rets.map((r,i)=>{
                    const age=Math.floor((r.peak-1)/12)-A.sy;
                    return(
                    <div key={"r"+i} data-card data-tone="crisis" style={{background:"#fff",borderLeft:"3px solid #B42318",padding:"12px 14px",marginBottom:8}}>
                      <p className="lb-sub" style={{margin:0,fontWeight:800,color:"#B42318"}}>
                        ★ {age<45?"1차":"2차"} 토성 회귀 — {mLab(r.s)} ~ {mLab(r.e)} <span style={{fontWeight:400,color:"#5C6570"}}>(정점 {mLab(r.peak)} · 만 {age}세 · 해제 {mLab(r.e+1)})</span>
                      </p>
                      <p style={{margin:"4px 0 0"}}>
                        <b style={{color:"#B42318"}}>최강</b>
                      </p>
                      <p style={{margin:"5px 0 0",fontSize:12.5,lineHeight:1.7}}>
                        약 29년 주기로 토성이 출생 위치로 돌아와 삶의 뼈대를 채점하는 구간이다. 적성에 맞지 않는 직업, 억지로 유지한 관계, 회피해 온 부채처럼 <b>모래 위에 지은 것</b>이 이때 무너진다.
                      </p>
                    </div>
                    );})}

                  {cs.uops&&cs.uops.map((u,i)=>(
                    <div key={"u"+i} data-card data-tone="crisis" style={{background:"#fff",borderLeft:"3px solid #B42318",padding:"12px 14px",marginBottom:8}}>
                      <p className="lb-sub" style={{margin:0,fontWeight:800,color:"#B42318"}}>
                        ★ 천왕성 대립 — {mLab(u.s)} ~ {mLab(u.e)} <span style={{fontWeight:400,color:"#5C6570"}}>(정점 {mLab(u.peak)} · 만 {Math.floor((u.peak-1)/12)-A.sy}세 · 해제 {mLab(u.e+1)})</span>
                      </p>
                      <p style={{margin:"4px 0 0"}}>
                        <b style={{color:"#B42318"}}>최강</b>
                      </p>
                    </div>
                  ))}

                  {(()=>{
                    const shown=cs.wins.map(w=>({w,lv:crisisLevel(w,cs.wins,cs.rets)})).filter(x=>x.lv>0);
                    if(!shown.length)return <p style={{fontSize:12.5,margin:"0 0 8px",lineHeight:1.7}}>이 창에는 유의미한 강도의 하드각 구간이 없다 — 쉽게 바꾸기 어려운 압박이 두드러지지 않는 시기다.</p>;
                    return shown.map(({w,lv},i)=>(
                      <div key={i} data-card data-tone="crisis" style={{background:"#fff",borderLeft:"3px solid #B42318",padding:"12px 14px",marginBottom:8}}>
                        <p style={{margin:0}}>
                          <b style={{color:"#B42318"}}>{mLab(w.s)} ~ {mLab(w.e)}</b> <span style={{color:"#5C6570"}}>· 정점 {mLab(w.peak)} · 만 {Math.floor((w.peak-1)/12)-A.sy}세 ·</span> <b style={{color:"#167347"}}>해제 {mLab(w.e+1)}</b>
                        </p>
                        <p style={{margin:"4px 0 0"}}>
                          <b style={{color:"#B42318"}}>{CRISIS_LV[lv-1][0]}</b>
                        </p>
                        <p style={{margin:"4px 0 0",fontSize:12.5,lineHeight:1.7}}>
                          <b>{MALEFIC_KR[w.p].split("(")[0]} {w.nm==="스퀘어"?"□":"☍"} {CRISIS_PT_KR[w.pt].split(" · ")[0]}</b> <span style={{fontSize:10.5,color:T.dim}}>({CRISIS_PT_KR[w.pt].split(" · ")[1]})</span> — <b style={{color:T.dim}}>가설:</b> {CRISIS_HIT[`${w.p}|${w.pt}`]}
                        </p>
                        {(()=>{const bn=benefitAt(A.astro,Math.floor((w.peak-1)/12));return(
                        <p style={{margin:"4px 0 0",color:bn?"#167347":"#5C6570",paddingLeft:9,borderLeft:`2px solid ${bn?"#167347":T.line}`}}>
                          <b style={{color:bn?"#167347":"#5C6570"}}>반대신호</b> — {bn||"지지 트랜짓 약함 — 확장보다 방어·정비로 통과할 구간."}
                        </p>);})()}
                      </div>
                    ));
                  })()}

                  {pf.length>0&&(
                    <div data-card data-tone="practice" style={{background:"#fff",borderLeft:"3px solid #167347",padding:"12px 14px",marginBottom:8}}>
                      <p className="lb-sub" style={{margin:0,fontWeight:800,color:"#167347"}}>돈·건강을 특히 점검할 해</p>
                      <p style={{margin:"3px 0 0",fontSize:11,color:T.dim,lineHeight:1.6}}>큰 사건이 예정된 해가 아니라, <b>평소보다 확인을 한 번 더 해야 손실이 없는 해</b>다. 아래 항목만 챙기면 대부분 무리 없이 지나간다.</p>
                      {pf.map((x,i)=>(
                        <p key={i} style={{margin:"5px 0 0",fontSize:12.5,lineHeight:1.7}}>
                          <b>{x.y}년</b> <span style={{fontSize:10.5,color:T.dim}}>만 {x.age}세</span> — {(x.lh===8||x.ph===8)
                            ?<><b style={{color:"#B42318"}}>남의 돈이 얽히는 해</b>. 빚·보증·공동투자, 그리고 가족이나 동업자의 금전 문제가 내 일로 넘어오기 쉽다.<br/><span style={{color:"#167347"}}>점검할 것 — ① 보증·연대·명의 대여는 하지 말 것 ② 대출·투자 확대는 이 해를 넘겨서 ③ 돈이 오가는 합의는 금액이 작아도 문서로 ④ 가족·동업자의 자금 상황을 미리 파악해 둘 것</span></>
                            :<><b style={{color:"#B42318"}}>소진과 뒷말이 쌓이는 해</b>. 겉으로 드러나지 않는 곳에서 피로와 오해가 누적되기 쉽다.<br/><span style={{color:"#167347"}}>점검할 것 — ① 건강검진을 미루지 말 것 ② 새 확장·전면 노출은 다음 해로 ③ 뒤에서 들리는 말에 즉시 반응하지 말 것 ④ 쉬는 시간과 정리할 일을 일정에 먼저 넣을 것</span></>}
                        </p>
                      ))}
                      <p style={{margin:"6px 0 0",fontSize:10.5,color:T.dim}}>※ 한 해의 기준은 1월 1일이 아니라 <b>생일부터 다음 생일까지</b>다.</p>
                    </div>
                  )}

                  {usedP.length>0&&(
                    <div data-card data-tone="practice" style={{background:"#F3F8F5",borderLeft:"3px solid #167347",padding:"12px 14px",marginBottom:8}}>
                      <p className="lb-sub" style={{margin:0,fontWeight:800,color:"#167347"}}>통과 원칙 — 흉성별 대응</p>
                      {usedP.map(p=>(
                        <p key={p} style={{margin:"5px 0 0",fontSize:12.5,lineHeight:1.7}}><b>{MALEFIC_KR[p].split("(")[0]}</b> — {CRISIS_EXIT[p]}</p>
                      ))}
                    </div>
                  )}

                  <p style={{fontSize:10.5,color:T.dim,margin:"6px 0 0",lineHeight:1.6}}>
                    {cs.approx?"출생시간 미상이라 상승점은 제외했고, 구간의 시작·해제 시점이 실제와 어긋날 수 있다. ":""}※ 불행의 선고가 아니라 압력이 걸리는 시기의 지도다. 같은 각도라도 준비된 사람에게는 구조 개편으로, 방치한 사람에게는 붕괴로 나타난다 — 상담에서는 <b>해제 시점과 대응 원칙</b>을 반드시 함께 전달할 것.
                  </p>
                </>
              );
            })()}

            </div>)}

            </>
        )}

        {coupleMode&&A&&B&&(
          <>
            <H>궁합 비교 — {pa.name||"A"} × {pb.name||"B"}</H>
            <p style={{fontSize:12,color:T.dim,margin:"0 0 10px",lineHeight:1.7}}>
              두 사람의 세 층을 나란히 놓고, 관계의 수와 원소, 그리고 두 차트가 실제로 맺는 각도(시너스트리)로 결속의 구조를 본다.
            </p>

            <div data-card style={{background:"#fff",border:`1px solid ${T.line}`,borderRadius:12,padding:"12px 14px",marginBottom:8,overflowX:"auto"}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:12.5}}>
                <thead>
                  <tr>
                    <th style={{textAlign:"left",padding:"4px 6px",color:T.dim,fontWeight:400,fontSize:11}}>층</th>
                    <th style={{textAlign:"left",padding:"4px 6px",color:T.accent}}>{pa.name||"A"}</th>
                    <th style={{textAlign:"left",padding:"4px 6px",color:T.accent}}>{pb.name||"B"}</th>
                  </tr>
                </thead>
                <tbody>
                  {[["의식층","cons"],["전의식층","pre"],["무의식층","unc"]].map(([nm,key])=>(
                    <tr key={key} style={{borderTop:`1px solid ${T.line}`}}>
                      <td style={{padding:"7px 6px",color:T.dim,fontSize:11.5,whiteSpace:"nowrap"}}>{nm}</td>
                      {[A,B].map((P,i)=>(
                        <td key={i} style={{padding:"7px 6px"}}>
                          <b>{P[key].main} {card(P[key].main)[0]}</b>
                          <span style={{color:ELEM_COLOR[cardElem(P[key].main)],fontWeight:700}}> ({ELEMS[cardElem(P[key].main)]})</span>
                          <span style={{color:T.dim,fontSize:11}}> · {GROUP_NAMES[GROUP_OF[P[key].main===22?0:P[key].main]]}</span>
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {relNum&&(
              <div data-card style={{background:T.tint,border:`1.5px solid ${T.accent}`,borderRadius:12,padding:"14px 16px",marginBottom:8}}>
                <div style={{display:"flex",gap:13,alignItems:"center",marginBottom:7}}>
                  <Seal n={relNum.main}/>
                  <div>
                    <p style={{margin:0,fontSize:10.5,letterSpacing:"0.1em",color:T.dim}}>관계의 수 · 두 생년월일의 합 · 계산 {relNum.steps}</p>
                    <p style={{margin:"2px 0 0",fontFamily:"var(--fd)",fontSize:18,fontWeight:"var(--fdw)"}}>
                      <span style={{color:T.accent}}>{card(relNum.main)[0]}</span>
                      <span style={{fontSize:13,color:ELEM_COLOR[cardElem(relNum.main)],fontWeight:700}}> ({ELEMS[cardElem(relNum.main)]})</span>
                    </p>
                  </div>
                </div>
                <p style={{margin:0,fontSize:12.5,lineHeight:1.8}}>
                  이 관계 자체가 하나의 인격처럼 갖는 성격이다 — {card(relNum.main)[2]}
                </p>
              </div>
            )}

            <div data-card style={{background:"#fff",border:`1px solid ${T.line}`,borderRadius:12,padding:"13px 15px",marginBottom:8}}>
              <p style={{margin:"0 0 5px",fontSize:11,letterSpacing:"0.1em",color:T.dim}}>원소 궁합</p>
              {(()=>{
                const ea=A.astro?elemOf(signOf(A.astro.sun)):cardElem(A.cons.main);
                const eb2=B.astro?elemOf(signOf(B.astro.sun)):cardElem(B.cons.main);
                const basis=(A.astro&&B.astro)?"태양 별자리 기준":"의식층 카드 기준";
                return(
                  <p style={{margin:0,fontSize:13,lineHeight:1.8}}>
                    <b style={{color:ELEM_COLOR[ea]}}>{ELEMS[ea]}</b> × <b style={{color:ELEM_COLOR[eb2]}}>{ELEMS[eb2]}</b> ({basis}) — {elemRel(ea,eb2)}
                  </p>
                );
              })()}
            </div>

            {(A.astro&&B.astro)?(
              <>
                <p style={{fontSize:12,color:T.dim,margin:"10px 0",lineHeight:1.7}}>
                  시너스트리 — 끌림축(태양·달·금성·화성), 일상축(같은 행성끼리), 안정축(토성 접착)의 각도를 본다. 오차가 작을수록 강하게 작동한다.
                </p>
                {syn.length===0?(
                  <p style={{fontSize:13,color:T.dim,lineHeight:1.75}}>
                    주요 축의 각도가 없다 — 강한 화학반응 없이 각자의 리듬을 존중하는 담백한 조합이다. 뜨겁지 않은 것이지 약한 것이 아니며, 결속은 각도가 아니라 함께 쌓는 시간과 약속에서 온다.
                  </p>
                ):syn.sort((x,y)=>x.o-y.o).map((r,i)=>(
                  <div key={i} data-card style={{background:r.stab?T.tint:"#fff",border:`1px solid ${r.stab?T.accent:T.line}`,borderRadius:12,padding:"11px 14px",marginBottom:7}}>
                    <p style={{margin:0,fontFamily:"var(--fd)",fontSize:14,fontWeight:"var(--fdw)"}}>
                      <span style={{color:T.accent}}>{pa.name||"A"}의 {r.p1} {ASPECT_SYM[r.nm]} {pb.name||"B"}의 {r.p2}</span>
                      <span style={{fontSize:11,color:T.dim,fontWeight:400}}> · {r.axis} · {r.nm} · 오차 {r.o.toFixed(1)}°</span>
                    </p>
                    <p style={{margin:"4px 0 0",fontSize:12.5,lineHeight:1.75}}>{SYN_TONE[r.tone]}{r.stab?" — 이 각도는 관계를 오래 붙드는 접착의 자리다.":""}</p>
                  </div>
                ))}
                {(()=>{
                  const v=synVerdict(syn);
                  return(
                    <div data-card style={{background:T.tint,border:`1.5px solid ${T.accent}`,borderRadius:12,padding:"14px 16px",marginTop:3}}>
                      <p style={{margin:0,fontSize:10.5,letterSpacing:"0.12em",color:T.dim}}>종합 판정</p>
                      <p style={{margin:"3px 0 6px",fontFamily:"var(--fd)",fontSize:16,fontWeight:"var(--fdw)",color:T.accent}}>{v.head}</p>
                      <p style={{margin:0,fontSize:12.5,lineHeight:1.8}}>{v.body}</p>
                    </div>
                  );
                })()}
              </>
            ):(
              <p style={{fontSize:12.5,color:T.dim,lineHeight:1.7}}>
                시너스트리는 두 사람 모두의 출생시간이 있어야 계산된다 — 시간 미상인 쪽이 있으면 위의 층 비교·관계의 수·원소 궁합까지만 표시된다.
              </p>
            )}

            <p style={{fontSize:10.5,color:T.dim,margin:"26px 0 0",lineHeight:1.7}}>
              궁합의 각도는 관계의 '기본 지형'이지 결말이 아니다 — 같은 지형에서도 어떻게 걷는가는 두 사람의 성숙과 합의가 정한다. 상징 체계 내부의 진술이며, 관계의 결정은 당사자의 몫이다.
            </p>
          </>
        )}
      </div>
    </div>
  );
}
